INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u5-C1','math',5,1,'u5',2,'통분해서 더하는 까닭 — 분모는 조각의 크기(이름), 분자는 조각의 개수임을 알고, 크기가 다른 조각은 그대로 셀 수 없어 통분해 크기를 맞춘 뒤 분자끼리 더함을 띠로 설명하기(분모끼리 더하면 안 되는 까닭)',ARRAY['6수01-06']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u5-C2','math',5,1,'u5',2,'진분수의 덧셈 — 분모가 다른 진분수를 분모의 곱이나 최소공배수로 통분하여 분자끼리 더하고 기약분수로 나타내며, 두 공통분모의 결과가 같은 수임을 알기',ARRAY['6수01-06']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u5-C3','math',5,1,'u5',3,'합이 1보다 큰 진분수의 덧셈 — 통분해 더한 분자가 분모보다 커지면 분모만큼을 1로 묶어 대분수로 나타내고, 합이 1을 넘는지 미리 어림하기',ARRAY['6수01-06']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u5-C4','math',5,1,'u5',4,'대분수의 덧셈 — 자연수끼리·분수끼리 더하거나 가분수로 바꾸어 더하고(결과 같음), 분수 부분의 합이 1을 넘으면 자연수로 올려 정리하기',ARRAY['6수01-06']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u5-C5','math',5,1,'u5',5,'진분수의 뺄셈 — 분모가 다른 진분수를 통분해 칸의 크기를 맞춘 뒤 분자끼리 빼고 분모는 그대로 두며, 덧셈과 뺄셈이 섞인 식도 통분해 차례로 셈하기',ARRAY['6수01-06']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u5-C6','math',5,1,'u5',6,'대분수의 뺄셈 — 분수 부분끼리 뺄 수 있을 때 자연수끼리·분수끼리 빼거나 가분수로 바꾸어 빼고, 두 방법의 결과가 같음을 알기',ARRAY['6수01-06']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u5-C7','math',5,1,'u5',7,'1을 빌려 오는 뺄셈 — 통분한 분자끼리 뺄 수 없을 때 자연수에서 1을 빌려 분모만큼의 조각으로 바꾸고(⟨3 3/12⟩ = ⟨2 15/12⟩), 자연수 − 분수도 같은 방법으로 셈하기',ARRAY['6수01-06']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u5-C8','math',5,1,'u5',8,'문제 해결 — 길마다 거리를 더해 구하고 통분해 견주며, 차·남은 거리·왕복처럼 상황에 맞는 덧셈·뺄셈 식을 세워 가장 짧은 길을 찾기',ARRAY['6수01-06']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u5-X01','math',5,'u5',ARRAY['M5-1-u5-C1','M5-1-u5-C2','M5-1-u5-C3','M5-1-u5-C5','M5-1-u5-C8']::text[],'통분하지 않고 분모는 분모끼리, 분자는 분자끼리 더하거나 뺀다(⟨1/4⟩ + ⟨1/3⟩을 ⟨2/7⟩로)','조각 크기부터 맞추기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u5-X02','math',5,'u5',ARRAY['M5-1-u5-C2','M5-1-u5-C3','M5-1-u5-C5']::text[],'통분할 때 분모만 공통분모로 바꾸고 분자는 그대로 둔다(⟨1/4⟩을 ⟨1/12⟩로)','분모를 몇 배 했으면 분자도 몇 배') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u5-X03','math',5,'u5',ARRAY['M5-1-u5-C1','M5-1-u5-C2','M5-1-u5-C5']::text[],'통분한 뒤 분모끼리도 더하거나 뺀다(⟨2/4⟩ + ⟨1/4⟩을 ⟨3/8⟩로, 뺄셈에서 분모 0)','분모는 조각의 이름 — 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u5-X04','math',5,'u5',ARRAY['M5-1-u5-C1','M5-1-u5-C2']::text[],'공통분모를 잘못 안다 — 공배수가 아닌 수로 통분하거나, 분모의 곱과 최소공배수로 통분한 결과가 서로 다른 수라고 여긴다','두 분모의 공배수면 모두 공통분모') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u5-X05','math',5,'u5',ARRAY['M5-1-u5-C3','M5-1-u5-C4']::text[],'분자가 분모보다 커져도 1로 묶지 않거나, 가분수를 대분수로 잘못 바꾼다(⟨17/12⟩을 ⟨1 7/12⟩이나 ⟨5/12⟩로)','분모만큼 모이면 1') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u5-X06','math',5,'u5',ARRAY['M5-1-u5-C4']::text[],'대분수의 덧셈에서 분수 부분의 합이 1을 넘었는데 자연수에 1을 올리지 않거나 1을 버린다','분수 부분이 넘친 만큼 자연수에 1') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u5-X07','math',5,'u5',ARRAY['M5-1-u5-C4','M5-1-u5-C6']::text[],'대분수를 가분수로 잘못 바꾼다(⟨2 2/5⟩을 ⟨22/5⟩, ⟨4/5⟩, ⟨6/5⟩로) — 자연수 × 분모 + 분자를 하지 않는다','자연수 × 분모 + 분자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u5-X08','math',5,'u5',ARRAY['M5-1-u5-C4','M5-1-u5-C6','M5-1-u5-C7']::text[],'대분수 계산에서 자연수 부분을 빠뜨리거나 잘못 셈한다(뺄셈인데 자연수끼리 더함)','자연수 자리도 따로 한 번 더 셈하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u5-X09','math',5,'u5',ARRAY['M5-1-u5-C7']::text[],'분수 부분끼리 뺄 수 없을 때 큰 분자에서 작은 분자를 거꾸로 뺀다(⟨3/12⟩ − ⟨8/12⟩에서 8 − 3)','빼는 차례는 그대로 — 모자라면 1 빌리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u5-X10','math',5,'u5',ARRAY['M5-1-u5-C7']::text[],'1을 빌려 올 때 분자에 분모만큼이 아니라 10이나 1을 더하거나, 빌려 준 자연수에서 1을 빼지 않는다','1 = 분모/분모, 자연수는 1 작게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u5-X11','math',5,'u5',ARRAY['M5-1-u5-C3','M5-1-u5-C5','M5-1-u5-C8']::text[],'상황에 맞지 않는 식을 세운다 — 남은 양을 더하거나, 왕복을 한 번만 세거나, 차를 구할 때 두 수를 더한다','무엇을 묻는지 그림으로 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u5-X12','math',5,'u5',ARRAY['M5-1-u5-C1','M5-1-u5-C3','M5-1-u5-C5','M5-1-u5-C8']::text[],'결과의 크기를 어림하지 않는다 — 더했는데 작아진 답, 1보다 작은 두 수의 합이 2를 넘는 답을 그대로 둔다','⟨1/2⟩·1과 견주어 어림하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u5-X13','math',5,'u5',ARRAY['M5-1-u5-C1','M5-1-u5-C2','M5-1-u5-C3','M5-1-u5-C4','M5-1-u5-C5','M5-1-u5-C6','M5-1-u5-C7','M5-1-u5-C8']::text[],'한 걸음의 셈(통분한 분자·분자끼리의 덧셈·뺄셈·대분수 바꾸기)을 잘못한다','통분한 분자를 다시 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u5-X14','math',5,'u5',ARRAY['M5-1-u5-C1','M5-1-u5-C2','M5-1-u5-C3','M5-1-u5-C4','M5-1-u5-C5','M5-1-u5-C6','M5-1-u5-C7','M5-1-u5-C8']::text[],'묻는 말을 거꾸로 읽는다 — 아닌↔맞는, 잘못↔바르게, 가장 짧은↔가장 긴, 큰↔작은','물음의 「아닌·잘못·가장」에 동그라미 치기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L02_basic#1','math',5,1,'u5','L02','g5_1_math_u5_L02_basic','lesson_basic','M5-1-u5-C1',1,'mc','auto','⟨1/4⟩ + ⟨1/3⟩을 계산할 때 가장 먼저 할 일은 무엇인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X02']::text[],true,'{"seq":1,"concept":"M5-1-u5-C1","difficulty":1,"kind":"mc","stem":"⟨1/4⟩ + ⟨1/3⟩을 계산할 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"두 분수를 통분한다","correct":true},{"t":"분모끼리 더한다","mis":"M5-1-u5-X01"},{"t":"분자끼리 더한다","mis":"M5-1-u5-X01"},{"t":"분모를 곱한 뒤 분자를 더한다","mis":"M5-1-u5-X02"}],"explanation":["⟨1/4⟩과 ⟨1/3⟩은 분모가 달라 조각의 크기가 달라요.","크기가 다른 조각은 한꺼번에 셀 수 없어요.","그래서 먼저 통분해 조각 크기를 맞춘 뒤 분자끼리 더해요."],"variant_rule":{"alt":[{"stem":"⟨1/2⟩ + ⟨1/5⟩을 계산할 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"두 분수를 통분한다","correct":true},{"t":"분모끼리 더한다","mis":"M5-1-u5-X01"},{"t":"분자끼리 더한다","mis":"M5-1-u5-X01"},{"t":"분모를 곱한 뒤 분자를 더한다","mis":"M5-1-u5-X02"}],"explanation":["⟨1/2⟩과 ⟨1/5⟩은 분모가 달라 조각의 크기가 달라요.","크기가 다른 조각은 한꺼번에 셀 수 없어요.","그래서 먼저 통분해 조각 크기를 맞춘 뒤 분자끼리 더해요."]},{"stem":"⟨1/6⟩ + ⟨1/4⟩을 계산할 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"두 분수를 통분한다","correct":true},{"t":"분모끼리 더한다","mis":"M5-1-u5-X01"},{"t":"분자끼리 더한다","mis":"M5-1-u5-X01"},{"t":"분모를 곱한 뒤 분자를 더한다","mis":"M5-1-u5-X02"}],"explanation":["⟨1/6⟩과 ⟨1/4⟩은 분모가 달라 조각의 크기가 달라요.","크기가 다른 조각은 한꺼번에 셀 수 없어요.","그래서 먼저 통분해 조각 크기를 맞춘 뒤 분자끼리 더해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L02_basic#2','math',5,1,'u5','L02','g5_1_math_u5_L02_basic','lesson_basic','M5-1-u5-C1',1,'sa','auto','⟨1/4⟩과 ⟨1/3⟩을 통분할 때 공통분모로 알맞은 가장 작은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u5-C1","difficulty":1,"kind":"sa","stem":"⟨1/4⟩과 ⟨1/3⟩을 통분할 때 공통분모로 알맞은 가장 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["공통분모는 두 분모 4와 3의 공배수예요.","가장 작은 공배수는 최소공배수 12예요.","분모의 곱 4 × 3 = 12도 공통분모가 될 수 있지만 가장 작은 수는 12예요."],"variant_rule":{"alt":[{"stem":"⟨1/6⟩과 ⟨1/4⟩을 통분할 때 공통분모로 알맞은 가장 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["공통분모는 두 분모 6과 4의 공배수예요.","가장 작은 공배수는 최소공배수 12예요.","분모의 곱 6 × 4 = 24도 공통분모가 될 수 있지만 가장 작은 수는 12예요."]},{"stem":"⟨1/2⟩과 ⟨1/5⟩을 통분할 때 공통분모로 알맞은 가장 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["공통분모는 두 분모 2와 5의 공배수예요.","가장 작은 공배수는 최소공배수 10이에요.","분모의 곱 2 × 5 = 10도 공통분모가 될 수 있지만 가장 작은 수는 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L02_basic#3','math',5,1,'u5','L02','g5_1_math_u5_L02_basic','lesson_basic','M5-1-u5-C2',1,'mc','auto','⟨1/2⟩ + ⟨1/5⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X02']::text[],true,'{"seq":3,"concept":"M5-1-u5-C2","difficulty":1,"kind":"mc","stem":"⟨1/2⟩ + ⟨1/5⟩을 계산하면 얼마인가요?","options":[{"t":"⟨7/10⟩","correct":true},{"t":"⟨2/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨7/20⟩","mis":"M5-1-u5-X03"},{"t":"⟨1/5⟩","mis":"M5-1-u5-X02"}],"explanation":["공통분모 10으로 통분하면 ⟨5/10⟩ + ⟨2/10⟩예요.","분모는 그대로 두고 분자끼리 더하면 ⟨5/10⟩ + ⟨2/10⟩ = ⟨7/10⟩이에요.","그래서 ⟨1/2⟩ + ⟨1/5⟩ = ⟨7/10⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1/3⟩ + ⟨1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨7/12⟩","correct":true},{"t":"⟨2/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨7/24⟩","mis":"M5-1-u5-X03"},{"t":"⟨1/6⟩","mis":"M5-1-u5-X02"}],"explanation":["공통분모 12로 통분하면 ⟨4/12⟩ + ⟨3/12⟩이에요.","분모는 그대로 두고 분자끼리 더하면 ⟨4/12⟩ + ⟨3/12⟩ = ⟨7/12⟩이에요.","그래서 ⟨1/3⟩ + ⟨1/4⟩ = ⟨7/12⟩이에요."]},{"stem":"⟨2/5⟩ + ⟨1/3⟩을 계산하면 얼마인가요?","options":[{"t":"⟨11/15⟩","correct":true},{"t":"⟨3/8⟩","mis":"M5-1-u5-X01"},{"t":"⟨11/30⟩","mis":"M5-1-u5-X03"},{"t":"⟨1/5⟩","mis":"M5-1-u5-X02"}],"explanation":["공통분모 15로 통분하면 ⟨6/15⟩ + ⟨5/15⟩예요.","분모는 그대로 두고 분자끼리 더하면 ⟨6/15⟩ + ⟨5/15⟩ = ⟨11/15⟩이에요.","그래서 ⟨2/5⟩ + ⟨1/3⟩ = ⟨11/15⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L02_basic#4','math',5,1,'u5','L02','g5_1_math_u5_L02_basic','lesson_basic','M5-1-u5-C2',1,'sa','auto','⟨2/5⟩ + ⟨1/3⟩을 분모 15로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u5-C2","difficulty":1,"kind":"sa","stem":"⟨2/5⟩ + ⟨1/3⟩을 분모 15로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["분모를 15로 맞추면 ⟨6/15⟩ + ⟨5/15⟩예요.","분모 15는 그대로 두고 분자끼리 6 + 5 = 11이에요.","그래서 분자는 11이에요."],"variant_rule":{"alt":[{"stem":"⟨1/3⟩ + ⟨1/4⟩을 분모 12로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["분모를 12로 맞추면 ⟨4/12⟩ + ⟨3/12⟩이에요.","분모 12는 그대로 두고 분자끼리 4 + 3 = 7이에요.","그래서 분자는 7이에요."]},{"stem":"⟨1/2⟩ + ⟨1/7⟩을 분모 14로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["분모를 14로 맞추면 ⟨7/14⟩ + ⟨2/14⟩예요.","분모 14는 그대로 두고 분자끼리 7 + 2 = 9예요.","그래서 분자는 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L02_basic#5','math',5,1,'u5','L02','g5_1_math_u5_L02_basic','lesson_basic','M5-1-u5-C1',2,'mc','auto','⟨1/4⟩과 ⟨1/3⟩을 그림처럼 12칸으로 맞추어 나타냈어요. 두 분수를 더하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X13']::text[],true,'{"seq":5,"concept":"M5-1-u5-C1","difficulty":2,"kind":"mc","stem":"⟨1/4⟩과 ⟨1/3⟩을 그림처럼 12칸으로 맞추어 나타냈어요. 두 분수를 더하면 얼마인가요?","options":[{"t":"⟨7/12⟩","correct":true},{"t":"⟨2/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨7/24⟩","mis":"M5-1-u5-X03"},{"t":"⟨2/3⟩","mis":"M5-1-u5-X13"}],"explanation":["⟨1/4⟩은 12칸 중 3칸, ⟨1/3⟩은 12칸 중 4칸이에요.","같은 크기의 칸이라 3칸 + 4칸 = 7칸으로 셀 수 있어요.","⟨3/12⟩ + ⟨4/12⟩ = ⟨7/12⟩이에요."],"asset":{"type":"fbar","bars":[{"den":12,"num":3,"label":"⟨1/4⟩"},{"den":12,"num":4,"label":"⟨1/3⟩"}]},"variant_rule":{"alt":[{"stem":"⟨1/2⟩과 ⟨1/6⟩을 그림처럼 6칸으로 맞추어 나타냈어요. 두 분수를 더하면 얼마인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨1/4⟩","mis":"M5-1-u5-X01"},{"t":"⟨1/3⟩","mis":"M5-1-u5-X03"},{"t":"⟨5/6⟩","mis":"M5-1-u5-X13"}],"explanation":["⟨1/2⟩은 6칸 중 3칸, ⟨1/6⟩은 6칸 중 1칸이에요.","같은 크기의 칸이라 3칸 + 1칸 = 4칸으로 셀 수 있어요.","⟨3/6⟩ + ⟨1/6⟩ = ⟨2/3⟩예요."],"asset":{"type":"fbar","bars":[{"den":6,"num":3,"label":"⟨1/2⟩"},{"den":6,"num":1,"label":"⟨1/6⟩"}]}},{"stem":"⟨1/3⟩과 ⟨1/6⟩을 그림처럼 6칸으로 맞추어 나타냈어요. 두 분수를 더하면 얼마인가요?","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨2/9⟩","mis":"M5-1-u5-X01"},{"t":"⟨1/4⟩","mis":"M5-1-u5-X03"},{"t":"⟨2/3⟩","mis":"M5-1-u5-X13"}],"explanation":["⟨1/3⟩은 6칸 중 2칸, ⟨1/6⟩은 6칸 중 1칸이에요.","같은 크기의 칸이라 2칸 + 1칸 = 3칸으로 셀 수 있어요.","⟨2/6⟩ + ⟨1/6⟩ = ⟨1/2⟩이에요."],"asset":{"type":"fbar","bars":[{"den":6,"num":2,"label":"⟨1/3⟩"},{"den":6,"num":1,"label":"⟨1/6⟩"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L02_basic#6','math',5,1,'u5','L02','g5_1_math_u5_L02_basic','lesson_basic','M5-1-u5-C1',2,'ox','auto','⟨1/4⟩ + ⟨1/3⟩의 분모끼리, 분자끼리 더한 ⟨2/7⟩는 바른 답이에요.',ARRAY['M5-1-u5-X01']::text[],true,'{"seq":6,"concept":"M5-1-u5-C1","difficulty":2,"kind":"ox","stem":"⟨1/4⟩ + ⟨1/3⟩의 분모끼리, 분자끼리 더한 ⟨2/7⟩는 바른 답이에요.","answer":"X","reason_options":[{"t":"⟨2/7⟩는 ⟨1/3⟩보다도 작아 더한 값이 될 수 없으므로","correct":true},{"t":"분모끼리, 분자끼리 빠짐없이 더했으므로","mis":"M5-1-u5-X01"}],"mis":"M5-1-u5-X01","explanation":["⟨1/4⟩의 한 칸과 ⟨1/3⟩의 한 칸은 크기가 달라요.","⟨2/7⟩는 ⟨1/3⟩보다 작아요 — 더했는데 작아졌어요.","12로 통분하면 ⟨3/12⟩ + ⟨4/12⟩ = ⟨7/12⟩이 바른 답이에요."],"variant_rule":{"alt":[{"stem":"⟨1/2⟩ + ⟨1/5⟩을 10으로 통분해 계산하면 ⟨7/10⟩이에요.","answer":"O","reason_options":[{"t":"⟨5/10⟩ + ⟨2/10⟩로 조각 크기를 맞춘 뒤 분자끼리 더했으므로","correct":true},{"t":"분모끼리 더하면 7이 되므로","mis":"M5-1-u5-X01"}],"explanation":["⟨1/2⟩ = ⟨5/10⟩, ⟨1/5⟩ = ⟨2/10⟩예요.","분자끼리 5 + 2 = 7이에요.","⟨5/10⟩ + ⟨2/10⟩ = ⟨7/10⟩ — 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L02_basic#7','math',5,1,'u5','L02','g5_1_math_u5_L02_basic','lesson_basic','M5-1-u5-C2',2,'sa','auto','⟨1/6⟩ + ⟨1/4⟩을 분모 24로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-1-u5-C2","difficulty":2,"kind":"sa","stem":"⟨1/6⟩ + ⟨1/4⟩을 분모 24로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["분모를 24로 맞추면 ⟨4/24⟩ + ⟨6/24⟩이에요.","분모 24는 그대로 두고 분자끼리 4 + 6 = 10이에요.","그래서 분자는 10이에요."],"variant_rule":{"alt":[{"stem":"⟨1/4⟩ + ⟨1/6⟩을 분모 24로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["분모를 24로 맞추면 ⟨6/24⟩ + ⟨4/24⟩예요.","분모 24는 그대로 두고 분자끼리 6 + 4 = 10이에요.","그래서 분자는 10이에요."]},{"stem":"⟨1/6⟩ + ⟨2/9⟩를 분모 54로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["분모를 54로 맞추면 ⟨9/54⟩ + ⟨12/54⟩예요.","분모 54는 그대로 두고 분자끼리 9 + 12 = 21이에요.","그래서 분자는 21이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L02_basic#8','math',5,1,'u5','L02','g5_1_math_u5_L02_basic','lesson_basic','M5-1-u5-C2',2,'mc','auto','⟨1/6⟩ + ⟨1/3⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X02']::text[],true,'{"seq":8,"concept":"M5-1-u5-C2","difficulty":2,"kind":"mc","stem":"⟨1/6⟩ + ⟨1/3⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨2/9⟩","mis":"M5-1-u5-X01"},{"t":"⟨1/4⟩","mis":"M5-1-u5-X03"},{"t":"⟨1/3⟩","mis":"M5-1-u5-X02"}],"explanation":["공통분모 6으로 통분하면 ⟨1/6⟩ + ⟨2/6⟩예요.","분모는 그대로 두고 분자끼리 더하면 ⟨1/6⟩ + ⟨2/6⟩ = ⟨3/6⟩ = ⟨1/2⟩이에요.","그래서 ⟨1/6⟩ + ⟨1/3⟩ = ⟨1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1/4⟩ + ⟨1/12⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"⟨1/8⟩","mis":"M5-1-u5-X01"},{"t":"⟨1/6⟩","mis":"M5-1-u5-X03"},{"t":"⟨5/12⟩","mis":"M5-1-u5-X13"}],"explanation":["공통분모 12로 통분하면 ⟨3/12⟩ + ⟨1/12⟩이에요.","분모는 그대로 두고 분자끼리 더하면 ⟨3/12⟩ + ⟨1/12⟩ = ⟨4/12⟩ = ⟨1/3⟩이에요.","그래서 ⟨1/4⟩ + ⟨1/12⟩ = ⟨1/3⟩이에요."]},{"stem":"⟨3/10⟩ + ⟨1/5⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨4/15⟩","mis":"M5-1-u5-X01"},{"t":"⟨1/4⟩","mis":"M5-1-u5-X03"},{"t":"⟨2/5⟩","mis":"M5-1-u5-X02"}],"explanation":["공통분모 10으로 통분하면 ⟨3/10⟩ + ⟨2/10⟩예요.","분모는 그대로 두고 분자끼리 더하면 ⟨3/10⟩ + ⟨2/10⟩ = ⟨5/10⟩ = ⟨1/2⟩이에요.","그래서 ⟨3/10⟩ + ⟨1/5⟩ = ⟨1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L02_basic#9','math',5,1,'u5','L02','g5_1_math_u5_L02_basic','lesson_basic','M5-1-u5-C2',2,'match','auto','계산 결과가 같은 것끼리 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M5-1-u5-C2","difficulty":2,"kind":"match","stem":"계산 결과가 같은 것끼리 이으세요.","pairs":[{"l":"⟨1/2⟩ + ⟨1/3⟩","r":"⟨5/6⟩"},{"l":"⟨1/3⟩ + ⟨1/4⟩","r":"⟨7/12⟩"},{"l":"⟨1/2⟩ + ⟨1/4⟩","r":"⟨3/4⟩"}],"mis":"M5-1-u5-X13","explanation":["⟨1/2⟩ + ⟨1/3⟩ = ⟨3/6⟩ + ⟨2/6⟩ = ⟨5/6⟩예요.","⟨1/3⟩ + ⟨1/4⟩ = ⟨4/12⟩ + ⟨3/12⟩ = ⟨7/12⟩이에요.","⟨1/2⟩ + ⟨1/4⟩ = ⟨2/4⟩ + ⟨1/4⟩ = ⟨3/4⟩이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 계산 결과가 같은 것끼리 이으세요.","pairs":[{"l":"⟨1/5⟩ + ⟨1/2⟩","r":"⟨7/10⟩"},{"l":"⟨1/3⟩ + ⟨1/6⟩","r":"⟨1/2⟩"},{"l":"⟨2/5⟩ + ⟨1/3⟩","r":"⟨11/15⟩"}],"explanation":["⟨1/5⟩ + ⟨1/2⟩ = ⟨2/10⟩ + ⟨5/10⟩ = ⟨7/10⟩이에요.","⟨1/3⟩ + ⟨1/6⟩ = ⟨2/6⟩ + ⟨1/6⟩ = ⟨3/6⟩ = ⟨1/2⟩이에요.","⟨2/5⟩ + ⟨1/3⟩ = ⟨6/15⟩ + ⟨5/15⟩ = ⟨11/15⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L02_basic#10','math',5,1,'u5','L02','g5_1_math_u5_L02_basic','lesson_basic','M5-1-u5-C2',3,'mc','auto','텃밭의 ⟨1/4⟩에는 상추를, ⟨1/3⟩에는 방울토마토를 심었어요. 아무것도 심지 않은 부분은 전체의 얼마인가요?',ARRAY['M5-1-u5-X11','M5-1-u5-X01']::text[],true,'{"seq":10,"concept":"M5-1-u5-C2","difficulty":3,"kind":"mc","stem":"텃밭의 ⟨1/4⟩에는 상추를, ⟨1/3⟩에는 방울토마토를 심었어요. 아무것도 심지 않은 부분은 전체의 얼마인가요?","options":[{"t":"⟨5/12⟩","correct":true},{"t":"⟨7/12⟩","mis":"M5-1-u5-X11"},{"t":"⟨2/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨5/7⟩","mis":"M5-1-u5-X01"}],"explanation":["심은 부분은 ⟨1/4⟩ + ⟨1/3⟩ = ⟨3/12⟩ + ⟨4/12⟩ = ⟨7/12⟩이에요.","전체 1은 ⟨12/12⟩예요.","심지 않은 부분은 ⟨12/12⟩ − ⟨7/12⟩ = ⟨5/12⟩예요."],"variant_rule":{"alt":[{"stem":"텃밭의 ⟨1/5⟩에는 고추를, ⟨1/2⟩에는 가지를 심었어요. 아무것도 심지 않은 부분은 전체의 얼마인가요?","options":[{"t":"⟨3/10⟩","correct":true},{"t":"⟨7/10⟩","mis":"M5-1-u5-X11"},{"t":"⟨2/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨5/7⟩","mis":"M5-1-u5-X01"}],"explanation":["심은 부분은 ⟨1/5⟩ + ⟨1/2⟩ = ⟨2/10⟩ + ⟨5/10⟩ = ⟨7/10⟩이에요.","전체 1은 ⟨10/10⟩이에요.","심지 않은 부분은 ⟨10/10⟩ − ⟨7/10⟩ = ⟨3/10⟩이에요."]},{"stem":"텃밭의 ⟨1/6⟩에는 오이를, ⟨3/8⟩에는 감자를 심었어요. 아무것도 심지 않은 부분은 전체의 얼마인가요?","options":[{"t":"⟨11/24⟩","correct":true},{"t":"⟨13/24⟩","mis":"M5-1-u5-X11"},{"t":"⟨2/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨5/7⟩","mis":"M5-1-u5-X01"}],"explanation":["심은 부분은 ⟨1/6⟩ + ⟨3/8⟩ = ⟨4/24⟩ + ⟨9/24⟩ = ⟨13/24⟩이에요.","전체 1은 ⟨24/24⟩예요.","심지 않은 부분은 ⟨24/24⟩ − ⟨13/24⟩ = ⟨11/24⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L02_challenge#1','math',5,1,'u5','L02','g5_1_math_u5_L02_challenge','lesson_challenge','M5-1-u5-C2',2,'error','auto','⟨1/4⟩ + ⟨1/3⟩을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X14']::text[],true,'{"seq":1,"concept":"M5-1-u5-C2","difficulty":2,"kind":"error","stem":"⟨1/4⟩ + ⟨1/3⟩을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「분모끼리, 분자끼리 더하면 ⟨2/7⟩야.」","correct":true,"mis_target":"M5-1-u5-X01"},{"t":"도현 — 「12로 통분하면 ⟨3/12⟩ + ⟨4/12⟩야.」","mis":"M5-1-u5-X14"},{"t":"하은 — 「답은 ⟨1/3⟩보다 커야 해.」","mis":"M5-1-u5-X14"}],"explanation":["⟨2/7⟩는 ⟨1/3⟩보다도 작아요 — 더했는데 작아질 수는 없어요.","통분하면 ⟨3/12⟩ + ⟨4/12⟩ = ⟨7/12⟩이에요.","서윤은 분모끼리 더해 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"⟨1/2⟩ + ⟨1/5⟩을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「분모끼리, 분자끼리 더하면 ⟨2/7⟩야.」","correct":true,"mis_target":"M5-1-u5-X01"},{"t":"라온 — 「10으로 통분하면 ⟨5/10⟩ + ⟨2/10⟩야.」","mis":"M5-1-u5-X14"},{"t":"예준 — 「답은 ⟨1/2⟩보다 커야 해.」","mis":"M5-1-u5-X14"}],"explanation":["⟨2/7⟩는 ⟨1/2⟩보다도 작아요 — 더했는데 작아질 수는 없어요.","통분하면 ⟨5/10⟩ + ⟨2/10⟩ = ⟨7/10⟩이에요.","지민은 분모끼리 더해 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L02_challenge#2','math',5,1,'u5','L02','g5_1_math_u5_L02_challenge','lesson_challenge','M5-1-u5-C2',2,'sa','auto','⟨3/8⟩ + ⟨1/4⟩을 분모 8로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u5-C2","difficulty":2,"kind":"sa","stem":"⟨3/8⟩ + ⟨1/4⟩을 분모 8로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모를 8로 맞추면 ⟨3/8⟩ + ⟨2/8⟩예요.","분모 8은 그대로 두고 분자끼리 3 + 2 = 5예요.","그래서 분자는 5예요."],"variant_rule":{"alt":[{"stem":"⟨1/6⟩ + ⟨5/12⟩를 분모 12로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["분모를 12로 맞추면 ⟨2/12⟩ + ⟨5/12⟩예요.","분모 12는 그대로 두고 분자끼리 2 + 5 = 7이에요.","그래서 분자는 7이에요."]},{"stem":"⟨3/10⟩ + ⟨2/5⟩를 분모 10으로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["분모를 10으로 맞추면 ⟨3/10⟩ + ⟨4/10⟩예요.","분모 10은 그대로 두고 분자끼리 3 + 4 = 7이에요.","그래서 분자는 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L02_challenge#3','math',5,1,'u5','L02','g5_1_math_u5_L02_challenge','lesson_challenge','M5-1-u5-C2',3,'mc','auto','계산한 결과가 1에 가장 가까운 것은 어느 것인가요?',ARRAY['M5-1-u5-X12']::text[],true,'{"seq":3,"concept":"M5-1-u5-C2","difficulty":3,"kind":"mc","stem":"계산한 결과가 1에 가장 가까운 것은 어느 것인가요?","options":[{"t":"⟨1/2⟩ + ⟨1/3⟩","correct":true},{"t":"⟨1/4⟩ + ⟨1/4⟩","mis":"M5-1-u5-X12"},{"t":"⟨1/6⟩ + ⟨1/3⟩","mis":"M5-1-u5-X12"},{"t":"⟨1/5⟩ + ⟨1/4⟩","mis":"M5-1-u5-X12"}],"explanation":["네 식을 계산하면 ⟨1/4⟩ + ⟨1/4⟩ = ⟨1/2⟩, ⟨1/2⟩ + ⟨1/3⟩ = ⟨5/6⟩, ⟨1/6⟩ + ⟨1/3⟩ = ⟨1/2⟩, ⟨1/5⟩ + ⟨1/4⟩ = ⟨9/20⟩예요.","1과의 차를 견주면 ⟨5/6⟩가 1에 가장 가까워요.","그래서 답은 ⟨1/2⟩ + ⟨1/3⟩이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 계산한 결과가 1에 가장 가까운 것은 어느 것인가요?","options":[{"t":"⟨1/2⟩ + ⟨1/4⟩","correct":true},{"t":"⟨1/3⟩ + ⟨1/3⟩","mis":"M5-1-u5-X12"},{"t":"⟨1/6⟩ + ⟨1/2⟩","mis":"M5-1-u5-X12"},{"t":"⟨2/5⟩ + ⟨1/3⟩","mis":"M5-1-u5-X12"}],"explanation":["네 식을 계산하면 ⟨1/3⟩ + ⟨1/3⟩ = ⟨2/3⟩, ⟨1/2⟩ + ⟨1/4⟩ = ⟨3/4⟩, ⟨1/6⟩ + ⟨1/2⟩ = ⟨2/3⟩, ⟨2/5⟩ + ⟨1/3⟩ = ⟨11/15⟩이에요.","1과의 차를 견주면 ⟨3/4⟩이 1에 가장 가까워요.","그래서 답은 ⟨1/2⟩ + ⟨1/4⟩이에요."]},{"stem":"이번에는 다른 보기예요. 계산한 결과가 1에 가장 가까운 것은 어느 것인가요?","options":[{"t":"⟨2/3⟩ + ⟨1/4⟩","correct":true},{"t":"⟨1/8⟩ + ⟨1/2⟩","mis":"M5-1-u5-X12"},{"t":"⟨1/3⟩ + ⟨1/4⟩","mis":"M5-1-u5-X12"},{"t":"⟨1/2⟩ + ⟨1/5⟩","mis":"M5-1-u5-X12"}],"explanation":["네 식을 계산하면 ⟨1/8⟩ + ⟨1/2⟩ = ⟨5/8⟩, ⟨2/3⟩ + ⟨1/4⟩ = ⟨11/12⟩, ⟨1/3⟩ + ⟨1/4⟩ = ⟨7/12⟩, ⟨1/2⟩ + ⟨1/5⟩ = ⟨7/10⟩이에요.","1과의 차를 견주면 ⟨11/12⟩이 1에 가장 가까워요.","그래서 답은 ⟨2/3⟩ + ⟨1/4⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L02_challenge#4','math',5,1,'u5','L02','g5_1_math_u5_L02_challenge','lesson_challenge','M5-1-u5-C2',3,'sa','auto','⟨1/2⟩ + ⟨□/6⟩ = ⟨5/6⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u5-C2","difficulty":3,"kind":"sa","stem":"⟨1/2⟩ + ⟨□/6⟩ = ⟨5/6⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨1/2⟩을 분모 6으로 나타내면 ⟨3/6⟩이에요.","⟨5/6⟩ = ⟨5/6⟩ — 분자끼리 5 − 3 = 2예요.","그래서 □는 2예요."],"variant_rule":{"alt":[{"stem":"⟨1/3⟩ + ⟨□/12⟩ = ⟨3/4⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨1/3⟩을 분모 12로 나타내면 ⟨4/12⟩예요.","⟨3/4⟩ = ⟨9/12⟩ — 분자끼리 9 − 4 = 5예요.","그래서 □는 5예요."]},{"stem":"⟨2/5⟩ + ⟨□/10⟩ = ⟨7/10⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨2/5⟩를 분모 10으로 나타내면 ⟨4/10⟩예요.","⟨7/10⟩ = ⟨7/10⟩ — 분자끼리 7 − 4 = 3이에요.","그래서 □는 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L02_challenge#5','math',5,1,'u5','L02','g5_1_math_u5_L02_challenge','lesson_challenge','M5-1-u5-C1',3,'mc','auto','분모가 다른 분수의 덧셈에 대한 설명으로 옳은 것은 어느 것인가요?',ARRAY['M5-1-u5-X04','M5-1-u5-X01','M5-1-u5-X02']::text[],true,'{"seq":5,"concept":"M5-1-u5-C1","difficulty":3,"kind":"mc","stem":"분모가 다른 분수의 덧셈에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"분모의 곱을 공통분모로 써도 된다","correct":true},{"t":"공통분모는 반드시 최소공배수여야 한다","mis":"M5-1-u5-X04"},{"t":"분모끼리 더한 뒤 분자끼리 더한다","mis":"M5-1-u5-X01"},{"t":"통분하면 분자는 그대로 두고 분모만 바꾼다","mis":"M5-1-u5-X02"}],"explanation":["공통분모는 두 분모의 공배수면 무엇이든 돼요 — 분모의 곱도, 최소공배수도.","최소공배수를 쓰면 수가 작아 셈이 편할 뿐이에요.","통분할 때는 분모를 곱한 수만큼 분자에도 곱해요."],"variant_rule":{"alt":[{"stem":"분모가 다른 분수의 덧셈에 대한 설명으로 옳지 않은 것은 어느 것인가요?","options":[{"t":"통분한 뒤 분모끼리도 더한다","correct":true},{"t":"통분해서 조각의 크기를 맞춘다","mis":"M5-1-u5-X14"},{"t":"최소공배수로 통분하면 수가 작아 편하다","mis":"M5-1-u5-X14"},{"t":"분모의 곱으로 통분해도 답은 같다","mis":"M5-1-u5-X14"}],"explanation":["분모는 조각의 이름이라 더하지 않아요.","통분한 뒤에는 분모는 그대로, 분자끼리만 더해요.","그래서 옳지 않은 것은 「분모끼리도 더한다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L02_challenge#6','math',5,1,'u5','L02','g5_1_math_u5_L02_challenge','lesson_challenge','M5-1-u5-C4',3,'sa','auto','⟨1/6⟩ + ⟨1/4⟩을 분모의 곱으로 통분하면 ⟨□/24⟩, 최소공배수로 통분하면 ⟨○/12⟩이 돼요. □ + ○는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u5-C4","difficulty":3,"kind":"sa","stem":"⟨1/6⟩ + ⟨1/4⟩을 분모의 곱으로 통분하면 ⟨□/24⟩, 최소공배수로 통분하면 ⟨○/12⟩이 돼요. □ + ○는 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["분모의 곱 24로 통분하면 ⟨4/24⟩ + ⟨6/24⟩ = ⟨10/24⟩이에요.","최소공배수 12로 통분하면 ⟨2/12⟩ + ⟨3/12⟩ = ⟨5/12⟩예요 — ⟨10/24⟩ = ⟨5/12⟩, 같은 수예요.","□ + ○ = 10 + 5 = 15예요."],"variant_rule":{"alt":[{"stem":"⟨1/4⟩ + ⟨3/10⟩을 분모의 곱으로 통분하면 ⟨□/40⟩, 최소공배수로 통분하면 ⟨○/20⟩이 돼요. □ + ○는 얼마인가요? 숫자로 쓰세요.","answer":["33"],"explanation":["분모의 곱 40으로 통분하면 ⟨10/40⟩ + ⟨12/40⟩ = ⟨22/40⟩예요.","최소공배수 20으로 통분하면 ⟨5/20⟩ + ⟨6/20⟩ = ⟨11/20⟩이에요 — ⟨22/40⟩ = ⟨11/20⟩, 같은 수예요.","□ + ○ = 22 + 11 = 33이에요."]},{"stem":"⟨1/6⟩ + ⟨2/9⟩를 분모의 곱으로 통분하면 ⟨□/54⟩, 최소공배수로 통분하면 ⟨○/18⟩이 돼요. □ + ○는 얼마인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["분모의 곱 54로 통분하면 ⟨9/54⟩ + ⟨12/54⟩ = ⟨21/54⟩이에요.","최소공배수 18로 통분하면 ⟨3/18⟩ + ⟨4/18⟩ = ⟨7/18⟩이에요 — ⟨21/54⟩ = ⟨7/18⟩, 같은 수예요.","□ + ○ = 21 + 7 = 28이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L02_challenge#7','math',5,1,'u5','L02','g5_1_math_u5_L02_challenge','lesson_challenge','M5-1-u5-C1',3,'ox','auto','두 분수 ⟨1/2⟩ + ⟨1/3⟩의 답은 ⟨1/2⟩보다 커야 하므로 ⟨2/5⟩는 답이 될 수 없어요.',ARRAY['M5-1-u5-X12']::text[],true,'{"seq":7,"concept":"M5-1-u5-C1","difficulty":3,"kind":"ox","stem":"두 분수 ⟨1/2⟩ + ⟨1/3⟩의 답은 ⟨1/2⟩보다 커야 하므로 ⟨2/5⟩는 답이 될 수 없어요.","answer":"O","reason_options":[{"t":"⟨2/5⟩는 ⟨1/2⟩보다 작아 더한 값이 될 수 없으므로","correct":true},{"t":"분모 5가 2와 3보다 크므로","mis":"M5-1-u5-X12"}],"mis":"M5-1-u5-X12","explanation":["더하면 더한 수보다 커져야 해요.","⟨2/5⟩ < ⟨1/2⟩이라 답이 될 수 없어요.","바른 답은 ⟨3/6⟩ + ⟨2/6⟩ = ⟨5/6⟩예요."],"variant_rule":{"alt":[{"stem":"⟨1/4⟩ + ⟨1/6⟩의 답이 ⟨2/10⟩이라면 ⟨1/4⟩보다 작아지므로 잘못된 답이에요.","answer":"O","reason_options":[{"t":"더했는데 ⟨1/4⟩보다 작아졌으므로","correct":true},{"t":"분모가 10이면 늘 틀린 답이므로","mis":"M5-1-u5-X12"}],"explanation":["⟨2/10⟩ = ⟨1/5⟩ < ⟨1/4⟩이에요.","더했는데 작아질 수는 없어요.","바른 답은 ⟨3/12⟩ + ⟨2/12⟩ = ⟨5/12⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L02_challenge#8','math',5,1,'u5','L02','g5_1_math_u5_L02_challenge','lesson_challenge','M5-1-u5-C2',4,'sa','auto','⟨1/3⟩ + ⟨□/12⟩의 계산 결과가 1보다 작을 때 □에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u5-C2","difficulty":4,"kind":"sa","stem":"⟨1/3⟩ + ⟨□/12⟩의 계산 결과가 1보다 작을 때 □에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["⟨1/3⟩ = ⟨4/12⟩이고, 1 = ⟨12/12⟩예요.","4 + □가 12보다 작아야 하니 □는 12 − 4 = 8보다 작아요.","그래서 가장 큰 □는 7이에요."],"variant_rule":{"alt":[{"stem":"⟨3/8⟩ + ⟨□/16⟩의 계산 결과가 1보다 작을 때 □에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["⟨3/8⟩ = ⟨6/16⟩이고, 1 = ⟨16/16⟩이에요.","6 + □가 16보다 작아야 하니 □는 16 − 6 = 10보다 작아요.","그래서 가장 큰 □는 9예요."]},{"stem":"⟨2/5⟩ + ⟨□/15⟩의 계산 결과가 1보다 작을 때 □에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["⟨2/5⟩ = ⟨6/15⟩이고, 1 = ⟨15/15⟩예요.","6 + □가 15보다 작아야 하니 □는 15 − 6 = 9보다 작아요.","그래서 가장 큰 □는 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L02_challenge#9','math',5,1,'u5','L02','g5_1_math_u5_L02_challenge','lesson_challenge','M5-1-u5-C2',4,'mc','auto','⟨1/4⟩ + ⟨1/6⟩ + ⟨1/3⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X13']::text[],true,'{"seq":9,"concept":"M5-1-u5-C2","difficulty":4,"kind":"mc","stem":"⟨1/4⟩ + ⟨1/6⟩ + ⟨1/3⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨3/13⟩","mis":"M5-1-u5-X01"},{"t":"⟨1/4⟩","mis":"M5-1-u5-X03"},{"t":"⟨5/6⟩","mis":"M5-1-u5-X13"}],"explanation":["세 분모의 최소공배수 12로 통분하면 ⟨3/12⟩ + ⟨2/12⟩ + ⟨4/12⟩예요.","분자끼리 3 + 2 + 4 = 9예요.","⟨9/12⟩ = ⟨3/4⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1/2⟩ + ⟨1/5⟩ + ⟨1/10⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨3/17⟩","mis":"M5-1-u5-X01"},{"t":"⟨4/15⟩","mis":"M5-1-u5-X03"},{"t":"⟨9/10⟩","mis":"M5-1-u5-X13"}],"explanation":["세 분모의 최소공배수 10으로 통분하면 ⟨5/10⟩ + ⟨2/10⟩ + ⟨1/10⟩이에요.","분자끼리 5 + 2 + 1 = 8이에요.","⟨8/10⟩ = ⟨4/5⟩예요."]},{"stem":"⟨1/3⟩ + ⟨1/4⟩ + ⟨1/12⟩을 계산하면 얼마인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨3/19⟩","mis":"M5-1-u5-X01"},{"t":"⟨2/9⟩","mis":"M5-1-u5-X03"},{"t":"⟨3/4⟩","mis":"M5-1-u5-X13"}],"explanation":["세 분모의 최소공배수 12로 통분하면 ⟨4/12⟩ + ⟨3/12⟩ + ⟨1/12⟩이에요.","분자끼리 4 + 3 + 1 = 8이에요.","⟨8/12⟩ = ⟨2/3⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L02_challenge#10','math',5,1,'u5','L02','g5_1_math_u5_L02_challenge','lesson_challenge','M5-1-u5-C1',4,'essay','teacher','⟨1/4⟩ + ⟨1/3⟩을 계산할 때 분모끼리 더하면 안 되는 까닭을 띠 그림이나 「조각」이라는 말을 써서 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u5-C1","difficulty":4,"kind":"essay","stem":"⟨1/4⟩ + ⟨1/3⟩을 계산할 때 분모끼리 더하면 안 되는 까닭을 띠 그림이나 「조각」이라는 말을 써서 설명하세요.","answer_guide":{"answer":"예: 분모는 조각의 크기를 알려 주는 이름이고 분자는 조각의 개수이다. ⟨1/4⟩의 조각과 ⟨1/3⟩의 조각은 크기가 달라 그대로 셀 수 없다. 12칸으로 통분하면 3칸 + 4칸 = 7칸이 되어 ⟨7/12⟩이고, 분모 12는 조각의 이름이라 더하지 않는다.","scoring_points":["분모는 조각의 크기(이름), 분자는 개수라고 썼는가","조각 크기가 달라 통분해야 한다고 썼는가","통분한 뒤 분자끼리만 더해 ⟨7/12⟩을 구했는가"]},"explanation":["⟨1/4⟩과 ⟨1/3⟩은 조각 크기가 달라요.","12칸으로 맞추면 3칸 + 4칸 = 7칸이에요.","⟨3/12⟩ + ⟨4/12⟩ = ⟨7/12⟩ — 분모는 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L03_basic#1','math',5,1,'u5','L03','g5_1_math_u5_L03_basic','lesson_basic','M5-1-u5-C3',1,'mc','auto','⟨2/3⟩ + ⟨3/4⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X05']::text[],true,'{"seq":1,"concept":"M5-1-u5-C3","difficulty":1,"kind":"mc","stem":"⟨2/3⟩ + ⟨3/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 5/12⟩","correct":true},{"t":"⟨5/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨17/24⟩","mis":"M5-1-u5-X03"},{"t":"⟨5/12⟩","mis":"M5-1-u5-X05"}],"explanation":["공통분모 12로 통분하면 ⟨8/12⟩ + ⟨9/12⟩예요.","분자끼리 더하면 ⟨8/12⟩ + ⟨9/12⟩ = ⟨17/12⟩ — 분모만큼 모인 12칸이 1이에요.","⟨17/12⟩ = ⟨1 5/12⟩이므로 ⟨2/3⟩ + ⟨3/4⟩ = ⟨1 5/12⟩예요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩ + ⟨1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 1/12⟩","correct":true},{"t":"⟨3/5⟩","mis":"M5-1-u5-X01"},{"t":"⟨13/24⟩","mis":"M5-1-u5-X03"},{"t":"⟨1/12⟩","mis":"M5-1-u5-X05"}],"explanation":["공통분모 12로 통분하면 ⟨10/12⟩ + ⟨3/12⟩이에요.","분자끼리 더하면 ⟨10/12⟩ + ⟨3/12⟩ = ⟨13/12⟩ — 분모만큼 모인 12칸이 1이에요.","⟨13/12⟩ = ⟨1 1/12⟩이므로 ⟨5/6⟩ + ⟨1/4⟩ = ⟨1 1/12⟩이에요."]},{"stem":"⟨3/5⟩ + ⟨1/2⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 1/10⟩","correct":true},{"t":"⟨4/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨11/20⟩","mis":"M5-1-u5-X03"},{"t":"⟨1/10⟩","mis":"M5-1-u5-X05"}],"explanation":["공통분모 10으로 통분하면 ⟨6/10⟩ + ⟨5/10⟩예요.","분자끼리 더하면 ⟨6/10⟩ + ⟨5/10⟩ = ⟨11/10⟩ — 분모만큼 모인 10칸이 1이에요.","⟨11/10⟩ = ⟨1 1/10⟩이므로 ⟨3/5⟩ + ⟨1/2⟩ = ⟨1 1/10⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L03_basic#2','math',5,1,'u5','L03','g5_1_math_u5_L03_basic','lesson_basic','M5-1-u5-C3',1,'sa','auto','⟨5/6⟩ + ⟨1/2⟩을 분모 6으로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u5-C3","difficulty":1,"kind":"sa","stem":"⟨5/6⟩ + ⟨1/2⟩을 분모 6으로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["분모를 6으로 맞추면 ⟨5/6⟩ + ⟨3/6⟩이에요.","분모 6은 그대로 두고 분자끼리 5 + 3 = 8이에요.","그래서 분자는 8이에요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩ + ⟨5/8⟩를 분모 8로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["분모를 8로 맞추면 ⟨6/8⟩ + ⟨5/8⟩예요.","분모 8은 그대로 두고 분자끼리 6 + 5 = 11이에요.","그래서 분자는 11이에요."]},{"stem":"⟨7/10⟩ + ⟨2/5⟩를 분모 10으로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["분모를 10으로 맞추면 ⟨7/10⟩ + ⟨4/10⟩예요.","분모 10은 그대로 두고 분자끼리 7 + 4 = 11이에요.","그래서 분자는 11이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L03_basic#3','math',5,1,'u5','L03','g5_1_math_u5_L03_basic','lesson_basic','M5-1-u5-C3',1,'sa','auto','⟨17/12⟩을 대분수로 나타내면 ⟨1 □/12⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-1-u5-C3","difficulty":1,"kind":"sa","stem":"⟨17/12⟩을 대분수로 나타내면 ⟨1 □/12⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모 12만큼 모이면 1이에요.","17칸에서 12칸을 덜어 내면 5칸이 남아요 — 17 − 12 = 5.","⟨17/12⟩ = ⟨1 5/12⟩예요."],"variant_rule":{"alt":[{"stem":"⟨13/8⟩을 대분수로 나타내면 ⟨1 □/8⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모 8만큼 모이면 1이에요.","13칸에서 8칸을 덜어 내면 5칸이 남아요 — 13 − 8 = 5.","⟨13/8⟩ = ⟨1 5/8⟩예요."]},{"stem":"⟨11/6⟩을 대분수로 나타내면 ⟨1 □/6⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모 6만큼 모이면 1이에요.","11칸에서 6칸을 덜어 내면 5칸이 남아요 — 11 − 6 = 5.","⟨11/6⟩ = ⟨1 5/6⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L03_basic#4','math',5,1,'u5','L03','g5_1_math_u5_L03_basic','lesson_basic','M5-1-u5-C3',1,'mc','auto','계산 결과가 1보다 큰 것은 어느 것인가요?',ARRAY['M5-1-u5-X14']::text[],true,'{"seq":4,"concept":"M5-1-u5-C3","difficulty":1,"kind":"mc","stem":"계산 결과가 1보다 큰 것은 어느 것인가요?","options":[{"t":"⟨3/5⟩ + ⟨1/2⟩","correct":true},{"t":"⟨1/3⟩ + ⟨1/2⟩","mis":"M5-1-u5-X14"},{"t":"⟨2/5⟩ + ⟨1/2⟩","mis":"M5-1-u5-X14"},{"t":"⟨1/4⟩ + ⟨2/3⟩","mis":"M5-1-u5-X14"}],"explanation":["⟨1/2⟩과 견주어 어림하면 빨라요 — 둘 다 ⟨1/2⟩보다 크면 1을 넘어요.","계산하면 ⟨1/3⟩ + ⟨1/2⟩ = ⟨5/6⟩, ⟨2/5⟩ + ⟨1/2⟩ = ⟨9/10⟩, ⟨3/5⟩ + ⟨1/2⟩ = ⟨1 1/10⟩, ⟨1/4⟩ + ⟨2/3⟩ = ⟨11/12⟩이에요.","그래서 1보다 큰 것은 ⟨3/5⟩ + ⟨1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 계산 결과가 1보다 큰 것은 어느 것인가요?","options":[{"t":"⟨2/3⟩ + ⟨3/4⟩","correct":true},{"t":"⟨1/6⟩ + ⟨1/2⟩","mis":"M5-1-u5-X14"},{"t":"⟨1/4⟩ + ⟨1/3⟩","mis":"M5-1-u5-X14"},{"t":"⟨2/7⟩ + ⟨1/2⟩","mis":"M5-1-u5-X14"}],"explanation":["⟨1/2⟩과 견주어 어림하면 빨라요 — 둘 다 ⟨1/2⟩보다 크면 1을 넘어요.","계산하면 ⟨1/6⟩ + ⟨1/2⟩ = ⟨2/3⟩, ⟨2/3⟩ + ⟨3/4⟩ = ⟨1 5/12⟩, ⟨1/4⟩ + ⟨1/3⟩ = ⟨7/12⟩, ⟨2/7⟩ + ⟨1/2⟩ = ⟨11/14⟩이에요.","그래서 1보다 큰 것은 ⟨2/3⟩ + ⟨3/4⟩이에요."]},{"stem":"계산 결과가 1보다 작은 것은 어느 것인가요?","options":[{"t":"⟨2/5⟩ + ⟨1/3⟩","correct":true},{"t":"⟨3/4⟩ + ⟨2/3⟩","mis":"M5-1-u5-X14"},{"t":"⟨5/6⟩ + ⟨1/3⟩","mis":"M5-1-u5-X14"},{"t":"⟨4/5⟩ + ⟨1/2⟩","mis":"M5-1-u5-X14"}],"explanation":["⟨1/2⟩과 견주어 어림하면 빨라요 — 둘 다 ⟨1/2⟩보다 크면 1을 넘어요.","계산하면 ⟨3/4⟩ + ⟨2/3⟩ = ⟨1 5/12⟩, ⟨5/6⟩ + ⟨1/3⟩ = ⟨1 1/6⟩, ⟨2/5⟩ + ⟨1/3⟩ = ⟨11/15⟩, ⟨4/5⟩ + ⟨1/2⟩ = ⟨1 3/10⟩이에요.","그래서 1보다 작은 것은 ⟨2/5⟩ + ⟨1/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L03_basic#5','math',5,1,'u5','L03','g5_1_math_u5_L03_basic','lesson_basic','M5-1-u5-C3',2,'mc','auto','⟨3/4⟩ + ⟨1/2⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X05']::text[],true,'{"seq":5,"concept":"M5-1-u5-C3","difficulty":2,"kind":"mc","stem":"⟨3/4⟩ + ⟨1/2⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 1/4⟩","correct":true},{"t":"⟨2/3⟩","mis":"M5-1-u5-X01"},{"t":"⟨5/8⟩","mis":"M5-1-u5-X03"},{"t":"⟨1/4⟩","mis":"M5-1-u5-X05"}],"explanation":["공통분모 4로 통분하면 ⟨3/4⟩ + ⟨2/4⟩예요.","분자끼리 더하면 ⟨3/4⟩ + ⟨2/4⟩ = ⟨5/4⟩ — 분모만큼 모인 4칸이 1이에요.","⟨5/4⟩ = ⟨1 1/4⟩이므로 ⟨3/4⟩ + ⟨1/2⟩ = ⟨1 1/4⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩ + ⟨2/3⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1 1/2⟩","correct":true},{"t":"⟨7/9⟩","mis":"M5-1-u5-X01"},{"t":"⟨3/4⟩","mis":"M5-1-u5-X03"},{"t":"⟨1/2⟩","mis":"M5-1-u5-X05"}],"explanation":["공통분모 6으로 통분하면 ⟨5/6⟩ + ⟨4/6⟩예요.","분자끼리 더하면 ⟨5/6⟩ + ⟨4/6⟩ = ⟨9/6⟩ — 분모만큼 모인 6칸이 1이에요.","⟨9/6⟩ = ⟨1 1/2⟩이므로 ⟨5/6⟩ + ⟨2/3⟩ = ⟨1 1/2⟩이에요."]},{"stem":"⟨7/8⟩ + ⟨1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 1/8⟩","correct":true},{"t":"⟨2/3⟩","mis":"M5-1-u5-X01"},{"t":"⟨9/16⟩","mis":"M5-1-u5-X03"},{"t":"⟨1/8⟩","mis":"M5-1-u5-X05"}],"explanation":["공통분모 8로 통분하면 ⟨7/8⟩ + ⟨2/8⟩예요.","분자끼리 더하면 ⟨7/8⟩ + ⟨2/8⟩ = ⟨9/8⟩ — 분모만큼 모인 8칸이 1이에요.","⟨9/8⟩ = ⟨1 1/8⟩이므로 ⟨7/8⟩ + ⟨1/4⟩ = ⟨1 1/8⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L03_basic#6','math',5,1,'u5','L03','g5_1_math_u5_L03_basic','lesson_basic','M5-1-u5-C3',2,'sa','auto','리본 ⟨5/6⟩ m와 ⟨3/4⟩ m를 이어 붙이면 ⟨1 □/12⟩ m예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u5-C3","difficulty":2,"kind":"sa","stem":"리본 ⟨5/6⟩ m와 ⟨3/4⟩ m를 이어 붙이면 ⟨1 □/12⟩ m예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["공통분모 12로 통분하면 ⟨10/12⟩ + ⟨9/12⟩예요.","분자끼리 더하면 ⟨10/12⟩ + ⟨9/12⟩ = ⟨19/12⟩ — 분모만큼 모인 12칸이 1이에요.","⟨19/12⟩ = ⟨1 7/12⟩이므로 ⟨5/6⟩ + ⟨3/4⟩ = ⟨1 7/12⟩이에요."],"variant_rule":{"alt":[{"stem":"색 테이프 ⟨2/3⟩ m와 ⟨5/6⟩ m를 이어 붙이면 ⟨1 □/6⟩ m예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["공통분모 6으로 통분하면 ⟨4/6⟩ + ⟨5/6⟩예요.","분자끼리 더하면 ⟨4/6⟩ + ⟨5/6⟩ = ⟨9/6⟩ — 분모만큼 모인 6칸이 1이에요.","⟨9/6⟩ = ⟨1 1/2⟩이므로 ⟨2/3⟩ + ⟨5/6⟩ = ⟨1 1/2⟩이에요. ⟨1 1/2⟩ = ⟨1 3/6⟩이에요."]},{"stem":"끈 ⟨3/4⟩ m와 ⟨7/10⟩ m를 이어 붙이면 ⟨1 □/20⟩ m예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["공통분모 20으로 통분하면 ⟨15/20⟩ + ⟨14/20⟩예요.","분자끼리 더하면 ⟨15/20⟩ + ⟨14/20⟩ = ⟨29/20⟩ — 분모만큼 모인 20칸이 1이에요.","⟨29/20⟩ = ⟨1 9/20⟩이므로 ⟨3/4⟩ + ⟨7/10⟩ = ⟨1 9/20⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L03_basic#7','math',5,1,'u5','L03','g5_1_math_u5_L03_basic','lesson_basic','M5-1-u5-C3',2,'ox','auto','⟨12/12⟩는 1과 같아요.',ARRAY['M5-1-u5-X05']::text[],true,'{"seq":7,"concept":"M5-1-u5-C3","difficulty":2,"kind":"ox","stem":"⟨12/12⟩는 1과 같아요.","answer":"O","reason_options":[{"t":"12칸으로 나눈 것 중 12칸 — 곧 전체이므로","correct":true},{"t":"분자가 12로 크니 1보다 크므로","mis":"M5-1-u5-X05"}],"mis":"M5-1-u5-X05","explanation":["⟨12/12⟩는 12칸 중 12칸을 다 칠한 것이에요.","전체를 다 칠하면 1이에요.","분자와 분모가 같으면 언제나 1이에요."],"variant_rule":{"alt":[{"stem":"⟨10/8⟩은 1보다 작아요.","answer":"X","reason_options":[{"t":"분자 10이 분모 8보다 커 8칸이 모여 1이 되고 2칸이 남으므로","correct":true},{"t":"분모 8이 10보다 작아 작은 수이므로","mis":"M5-1-u5-X05"}],"explanation":["8칸이 모이면 1이에요.","10칸에서 8칸을 덜어 내면 2칸 — ⟨10/8⟩ = ⟨1 2/8⟩예요.","그래서 ⟨10/8⟩은 1보다 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L03_basic#8','math',5,1,'u5','L03','g5_1_math_u5_L03_basic','lesson_basic','M5-1-u5-C3',2,'mc','auto','⟨2/3⟩ + ⟨3/4⟩을 12칸 띠에 칠했더니 그림처럼 첫째 띠가 가득 차고 둘째 띠에 5칸이 칠해졌어요. 합은 얼마인가요?',ARRAY['M5-1-u5-X05','M5-1-u5-X03']::text[],true,'{"seq":8,"concept":"M5-1-u5-C3","difficulty":2,"kind":"mc","stem":"⟨2/3⟩ + ⟨3/4⟩을 12칸 띠에 칠했더니 그림처럼 첫째 띠가 가득 차고 둘째 띠에 5칸이 칠해졌어요. 합은 얼마인가요?","options":[{"t":"⟨1 5/12⟩","correct":true},{"t":"⟨5/12⟩","mis":"M5-1-u5-X05"},{"t":"⟨17/24⟩","mis":"M5-1-u5-X03"},{"t":"⟨1 7/12⟩","mis":"M5-1-u5-X05"}],"explanation":["⟨2/3⟩ = ⟨8/12⟩, ⟨3/4⟩ = ⟨9/12⟩ — 모두 17칸이에요.","가득 찬 띠 하나가 1, 남은 5칸이 ⟨5/12⟩예요.","⟨17/12⟩ = ⟨1 5/12⟩예요."],"asset":{"type":"fbar","bars":[{"den":12,"num":12,"label":"1"},{"den":12,"num":5,"label":"⟨5/12⟩"}]},"variant_rule":{"alt":[{"stem":"⟨5/6⟩ + ⟨1/2⟩을 6칸 띠에 칠했더니 그림처럼 첫째 띠가 가득 차고 둘째 띠에 2칸이 칠해졌어요. 합은 얼마인가요?","options":[{"t":"⟨1 1/3⟩","correct":true},{"t":"⟨1/3⟩","mis":"M5-1-u5-X05"},{"t":"⟨2/3⟩","mis":"M5-1-u5-X03"},{"t":"⟨1 1/2⟩","mis":"M5-1-u5-X05"}],"explanation":["⟨5/6⟩ = ⟨5/6⟩, ⟨1/2⟩ = ⟨3/6⟩ — 모두 8칸이에요.","가득 찬 띠 하나가 1, 남은 2칸이 ⟨2/6⟩예요.","⟨8/6⟩ = ⟨1 1/3⟩이에요."],"asset":{"type":"fbar","bars":[{"den":6,"num":6,"label":"1"},{"den":6,"num":2,"label":"⟨2/6⟩"}]}},{"stem":"⟨3/4⟩ + ⟨5/8⟩를 8칸 띠에 칠했더니 그림처럼 첫째 띠가 가득 차고 둘째 띠에 3칸이 칠해졌어요. 합은 얼마인가요?","options":[{"t":"⟨1 3/8⟩","correct":true},{"t":"⟨3/8⟩","mis":"M5-1-u5-X05"},{"t":"⟨11/16⟩","mis":"M5-1-u5-X03"},{"t":"⟨1 1/8⟩","mis":"M5-1-u5-X05"}],"explanation":["⟨3/4⟩ = ⟨6/8⟩, ⟨5/8⟩ = ⟨5/8⟩ — 모두 11칸이에요.","가득 찬 띠 하나가 1, 남은 3칸이 ⟨3/8⟩이에요.","⟨11/8⟩ = ⟨1 3/8⟩이에요."],"asset":{"type":"fbar","bars":[{"den":8,"num":8,"label":"1"},{"den":8,"num":3,"label":"⟨3/8⟩"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L03_basic#9','math',5,1,'u5','L03','g5_1_math_u5_L03_basic','lesson_basic','M5-1-u5-C3',2,'match','auto','가분수와 크기가 같은 대분수를 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M5-1-u5-C3","difficulty":2,"kind":"match","stem":"가분수와 크기가 같은 대분수를 이으세요.","pairs":[{"l":"⟨17/12⟩","r":"⟨1 5/12⟩"},{"l":"⟨13/10⟩","r":"⟨1 3/10⟩"},{"l":"⟨11/6⟩","r":"⟨1 5/6⟩"}],"mis":"M5-1-u5-X05","explanation":["⟨17/12⟩ — 12칸이 1, 남은 5칸이에요.","⟨13/10⟩ = ⟨1 3/10⟩, ⟨11/6⟩ = ⟨1 5/6⟩예요.","분모만큼 덜어 내면 1, 남은 칸이 분수 부분이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 가분수와 크기가 같은 대분수를 이으세요.","pairs":[{"l":"⟨15/8⟩","r":"⟨1 7/8⟩"},{"l":"⟨19/12⟩","r":"⟨1 7/12⟩"},{"l":"⟨7/4⟩","r":"⟨1 3/4⟩"}],"explanation":["⟨15/8⟩ — 8칸이 1, 남은 7칸이에요.","⟨19/12⟩ = ⟨1 7/12⟩, ⟨7/4⟩ = ⟨1 3/4⟩이에요.","분자에서 분모만큼 덜어 낸 나머지가 분수 부분이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L03_basic#10','math',5,1,'u5','L03','g5_1_math_u5_L03_basic','lesson_basic','M5-1-u5-C3',3,'mc','auto','주스 2 L 중에서 어제 ⟨3/4⟩ L, 오늘 ⟨2/3⟩ L를 마셨어요. 남은 양은 얼마인가요?',ARRAY['M5-1-u5-X11','M5-1-u5-X05']::text[],true,'{"seq":10,"concept":"M5-1-u5-C3","difficulty":3,"kind":"mc","stem":"주스 2 L 중에서 어제 ⟨3/4⟩ L, 오늘 ⟨2/3⟩ L를 마셨어요. 남은 양은 얼마인가요?","options":[{"t":"⟨7/12⟩","correct":true},{"t":"⟨1 5/12⟩","mis":"M5-1-u5-X11"},{"t":"⟨1 7/12⟩","mis":"M5-1-u5-X05"},{"t":"⟨3 5/12⟩","mis":"M5-1-u5-X11"}],"explanation":["마신 양은 ⟨3/4⟩ + ⟨2/3⟩ = ⟨9/12⟩ + ⟨8/12⟩ = ⟨1 5/12⟩ L예요.","2 = ⟨1 12/12⟩로 보면 셈하기 쉬워요.","남은 양은 2 − ⟨1 5/12⟩ = ⟨7/12⟩ L예요."],"variant_rule":{"alt":[{"stem":"우유 2 L 중에서 어제 ⟨5/6⟩ L, 오늘 ⟨1/2⟩ L를 마셨어요. 남은 양은 얼마인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨1 1/3⟩","mis":"M5-1-u5-X11"},{"t":"⟨1 2/3⟩","mis":"M5-1-u5-X05"},{"t":"⟨3 1/3⟩","mis":"M5-1-u5-X11"}],"explanation":["마신 양은 ⟨5/6⟩ + ⟨1/2⟩ = ⟨5/6⟩ + ⟨3/6⟩ = ⟨1 1/3⟩ L예요.","2 = ⟨1 6/6⟩으로 보면 셈하기 쉬워요.","남은 양은 2 − ⟨1 1/3⟩ = ⟨2/3⟩ L예요."]},{"stem":"보리차 2 L 중에서 어제 ⟨3/5⟩ L, 오늘 ⟨7/10⟩ L를 마셨어요. 남은 양은 얼마인가요?","options":[{"t":"⟨7/10⟩","correct":true},{"t":"⟨1 3/10⟩","mis":"M5-1-u5-X11"},{"t":"⟨1 7/10⟩","mis":"M5-1-u5-X05"},{"t":"⟨3 3/10⟩","mis":"M5-1-u5-X11"}],"explanation":["마신 양은 ⟨3/5⟩ + ⟨7/10⟩ = ⟨6/10⟩ + ⟨7/10⟩ = ⟨1 3/10⟩ L예요.","2 = ⟨1 10/10⟩으로 보면 셈하기 쉬워요.","남은 양은 2 − ⟨1 3/10⟩ = ⟨7/10⟩ L예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L03_challenge#1','math',5,1,'u5','L03','g5_1_math_u5_L03_challenge','lesson_challenge','M5-1-u5-C3',2,'error','auto','⟨2/3⟩ + ⟨3/4⟩을 계산하는 과정에서 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u5-X05','M5-1-u5-X14']::text[],true,'{"seq":1,"concept":"M5-1-u5-C3","difficulty":2,"kind":"error","stem":"⟨2/3⟩ + ⟨3/4⟩을 계산하는 과정에서 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「⟨17/12⟩은 ⟨1 7/12⟩이야.」","correct":true,"mis_target":"M5-1-u5-X05"},{"t":"도현 — 「12로 통분하면 ⟨8/12⟩ + ⟨9/12⟩야.」","mis":"M5-1-u5-X14"},{"t":"하은 — 「분자가 분모보다 커졌으니 1보다 커.」","mis":"M5-1-u5-X14"}],"explanation":["⟨8/12⟩ + ⟨9/12⟩ = ⟨17/12⟩이에요.","17칸에서 1이 되는 12칸을 덜어 내면 5칸이 남아요 — ⟨17/12⟩ = ⟨1 5/12⟩.","서윤은 일의 자리 숫자만 남겨 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩ + ⟨3/4⟩을 계산하는 과정에서 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「⟨19/12⟩는 ⟨1 9/12⟩야.」","correct":true,"mis_target":"M5-1-u5-X05"},{"t":"라온 — 「12로 통분하면 ⟨10/12⟩ + ⟨9/12⟩야.」","mis":"M5-1-u5-X14"},{"t":"예준 — 「분자가 분모보다 커졌으니 1보다 커.」","mis":"M5-1-u5-X14"}],"explanation":["⟨10/12⟩ + ⟨9/12⟩ = ⟨19/12⟩예요.","19칸에서 1이 되는 12칸을 덜어 내면 7칸이 남아요 — ⟨19/12⟩ = ⟨1 7/12⟩.","지민은 일의 자리 숫자만 남겨 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L03_challenge#2','math',5,1,'u5','L03','g5_1_math_u5_L03_challenge','lesson_challenge','M5-1-u5-C3',2,'sa','auto','⟨4/5⟩ + ⟨1/2⟩을 분모 10으로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u5-C3","difficulty":2,"kind":"sa","stem":"⟨4/5⟩ + ⟨1/2⟩을 분모 10으로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["분모를 10으로 맞추면 ⟨8/10⟩ + ⟨5/10⟩예요.","분모 10은 그대로 두고 분자끼리 8 + 5 = 13이에요.","그래서 분자는 13이에요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩ + ⟨3/8⟩을 분모 24로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["29"],"explanation":["분모를 24로 맞추면 ⟨20/24⟩ + ⟨9/24⟩예요.","분모 24는 그대로 두고 분자끼리 20 + 9 = 29예요.","그래서 분자는 29예요."]},{"stem":"⟨2/3⟩ + ⟨4/9⟩를 분모 9로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["분모를 9로 맞추면 ⟨6/9⟩ + ⟨4/9⟩예요.","분모 9는 그대로 두고 분자끼리 6 + 4 = 10이에요.","그래서 분자는 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L03_challenge#3','math',5,1,'u5','L03','g5_1_math_u5_L03_challenge','lesson_challenge','M5-1-u5-C3',3,'mc','auto','⟨4/5⟩ + ⟨1/2⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X05']::text[],true,'{"seq":3,"concept":"M5-1-u5-C3","difficulty":3,"kind":"mc","stem":"⟨4/5⟩ + ⟨1/2⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 3/10⟩","correct":true},{"t":"⟨5/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨13/20⟩","mis":"M5-1-u5-X03"},{"t":"⟨3/10⟩","mis":"M5-1-u5-X05"}],"explanation":["공통분모 10으로 통분하면 ⟨8/10⟩ + ⟨5/10⟩예요.","분자끼리 더하면 ⟨8/10⟩ + ⟨5/10⟩ = ⟨13/10⟩ — 분모만큼 모인 10칸이 1이에요.","⟨13/10⟩ = ⟨1 3/10⟩이므로 ⟨4/5⟩ + ⟨1/2⟩ = ⟨1 3/10⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨7/9⟩ + ⟨1/2⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 5/18⟩","correct":true},{"t":"⟨8/11⟩","mis":"M5-1-u5-X01"},{"t":"⟨23/36⟩","mis":"M5-1-u5-X03"},{"t":"⟨5/18⟩","mis":"M5-1-u5-X05"}],"explanation":["공통분모 18로 통분하면 ⟨14/18⟩ + ⟨9/18⟩예요.","분자끼리 더하면 ⟨14/18⟩ + ⟨9/18⟩ = ⟨23/18⟩ — 분모만큼 모인 18칸이 1이에요.","⟨23/18⟩ = ⟨1 5/18⟩이므로 ⟨7/9⟩ + ⟨1/2⟩ = ⟨1 5/18⟩예요."]},{"stem":"⟨5/8⟩ + ⟨5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1 11/24⟩","correct":true},{"t":"⟨5/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨35/48⟩","mis":"M5-1-u5-X03"},{"t":"⟨11/24⟩","mis":"M5-1-u5-X05"}],"explanation":["공통분모 24로 통분하면 ⟨15/24⟩ + ⟨20/24⟩이에요.","분자끼리 더하면 ⟨15/24⟩ + ⟨20/24⟩ = ⟨35/24⟩ — 분모만큼 모인 24칸이 1이에요.","⟨35/24⟩ = ⟨1 11/24⟩이므로 ⟨5/8⟩ + ⟨5/6⟩ = ⟨1 11/24⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L03_challenge#4','math',5,1,'u5','L03','g5_1_math_u5_L03_challenge','lesson_challenge','M5-1-u5-C3',3,'mc','auto','⟨5/8⟩ + ⟨3/4⟩의 계산 결과를 1과 견준 것으로 알맞은 것은 어느 것인가요?',ARRAY['M5-1-u5-X14','M5-1-u5-X13','M5-1-u5-X12']::text[],true,'{"seq":4,"concept":"M5-1-u5-C3","difficulty":3,"kind":"mc","stem":"⟨5/8⟩ + ⟨3/4⟩의 계산 결과를 1과 견준 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"1보다 ⟨3/8⟩만큼 크다","correct":true},{"t":"1보다 ⟨3/8⟩만큼 작다","mis":"M5-1-u5-X14"},{"t":"1보다 ⟨1/2⟩만큼 크다","mis":"M5-1-u5-X13"},{"t":"1과 같다","mis":"M5-1-u5-X12"}],"explanation":["⟨5/8⟩ + ⟨3/4⟩ = ⟨1 3/8⟩이에요.","⟨1 3/8⟩ − 1 = ⟨3/8⟩ — 1보다 ⟨3/8⟩만큼 더 있어요.","그래서 「1보다 ⟨3/8⟩만큼 크다」예요."],"variant_rule":{"alt":[{"stem":"⟨2/3⟩ + ⟨1/2⟩의 계산 결과를 1과 견준 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"1보다 ⟨1/6⟩만큼 크다","correct":true},{"t":"1보다 ⟨1/6⟩만큼 작다","mis":"M5-1-u5-X14"},{"t":"1보다 ⟨1/3⟩만큼 크다","mis":"M5-1-u5-X13"},{"t":"1과 같다","mis":"M5-1-u5-X12"}],"explanation":["⟨2/3⟩ + ⟨1/2⟩ = ⟨1 1/6⟩이에요.","⟨1 1/6⟩ − 1 = ⟨1/6⟩ — 1보다 ⟨1/6⟩만큼 더 있어요.","그래서 「1보다 ⟨1/6⟩만큼 크다」예요."]},{"stem":"⟨4/5⟩ + ⟨3/10⟩의 계산 결과를 1과 견준 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"1보다 ⟨1/10⟩만큼 크다","correct":true},{"t":"1보다 ⟨1/10⟩만큼 작다","mis":"M5-1-u5-X14"},{"t":"1보다 ⟨1/5⟩만큼 크다","mis":"M5-1-u5-X13"},{"t":"1과 같다","mis":"M5-1-u5-X12"}],"explanation":["⟨4/5⟩ + ⟨3/10⟩ = ⟨1 1/10⟩이에요.","⟨1 1/10⟩ − 1 = ⟨1/10⟩ — 1보다 ⟨1/10⟩만큼 더 있어요.","그래서 「1보다 ⟨1/10⟩만큼 크다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L03_challenge#5','math',5,1,'u5','L03','g5_1_math_u5_L03_challenge','lesson_challenge','M5-1-u5-C3',3,'sa','auto','⟨2/3⟩ + ⟨□/12⟩의 계산 결과가 1보다 클 때 □에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-1-u5-C3","difficulty":3,"kind":"sa","stem":"⟨2/3⟩ + ⟨□/12⟩의 계산 결과가 1보다 클 때 □에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨2/3⟩ = ⟨8/12⟩이고, 1 = ⟨12/12⟩예요.","8 + □가 12보다 커야 하니 □는 12 − 8 = 4보다 커요.","그래서 가장 작은 □는 5예요."],"variant_rule":{"alt":[{"stem":"⟨3/5⟩ + ⟨□/10⟩의 계산 결과가 1보다 클 때 □에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨3/5⟩ = ⟨6/10⟩이고, 1 = ⟨10/10⟩이에요.","6 + □가 10보다 커야 하니 □는 10 − 6 = 4보다 커요.","그래서 가장 작은 □는 5예요."]},{"stem":"⟨5/8⟩ + ⟨□/16⟩의 계산 결과가 1보다 클 때 □에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["⟨5/8⟩ = ⟨10/16⟩이고, 1 = ⟨16/16⟩이에요.","10 + □가 16보다 커야 하니 □는 16 − 10 = 6보다 커요.","그래서 가장 작은 □는 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L03_challenge#6','math',5,1,'u5','L03','g5_1_math_u5_L03_challenge','lesson_challenge','M5-1-u5-C3',3,'sa','auto','⟨1/2⟩ + ⟨2/3⟩ + ⟨3/4⟩을 계산하면 ⟨1 □/12⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u5-C3","difficulty":3,"kind":"sa","stem":"⟨1/2⟩ + ⟨2/3⟩ + ⟨3/4⟩을 계산하면 ⟨1 □/12⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["12로 통분하면 ⟨6/12⟩ + ⟨8/12⟩ + ⟨9/12⟩예요.","분자끼리 6 + 8 + 9 = 23이에요.","⟨23/12⟩ = ⟨1 11/12⟩ — □는 11이에요."],"variant_rule":{"alt":[{"stem":"⟨1/2⟩ + ⟨1/3⟩ + ⟨5/6⟩를 계산하면 ⟨1 □/6⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["6으로 통분하면 ⟨3/6⟩ + ⟨2/6⟩ + ⟨5/6⟩예요.","분자끼리 3 + 2 + 5 = 10이에요.","⟨10/6⟩ = ⟨1 4/6⟩ — □는 4예요."]},{"stem":"⟨3/4⟩ + ⟨1/2⟩ + ⟨1/6⟩을 계산하면 ⟨1 □/12⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["12로 통분하면 ⟨9/12⟩ + ⟨6/12⟩ + ⟨2/12⟩예요.","분자끼리 9 + 6 + 2 = 17이에요.","⟨17/12⟩ = ⟨1 5/12⟩ — □는 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L03_challenge#7','math',5,1,'u5','L03','g5_1_math_u5_L03_challenge','lesson_challenge','M5-1-u5-C3',3,'ox','auto','1보다 작은 진분수 두 개를 더한 값은 2보다 작아요.',ARRAY['M5-1-u5-X12']::text[],true,'{"seq":7,"concept":"M5-1-u5-C3","difficulty":3,"kind":"ox","stem":"1보다 작은 진분수 두 개를 더한 값은 2보다 작아요.","answer":"O","reason_options":[{"t":"두 수가 모두 1보다 작으니 합은 1 + 1 = 2보다 작으므로","correct":true},{"t":"분자끼리 더하면 분모보다 커질 수 있으므로","mis":"M5-1-u5-X12"}],"mis":"M5-1-u5-X12","explanation":["진분수는 1보다 작아요.","1보다 작은 두 수의 합은 2보다 작아요.","그래서 진분수 두 개의 합은 ⟨1 □/○⟩꼴이 되어도 2를 넘지 못해요."],"variant_rule":{"alt":[{"stem":"⟨1/2⟩보다 큰 진분수 두 개를 더하면 언제나 1보다 커요.","answer":"O","reason_options":[{"t":"⟨1/2⟩ + ⟨1/2⟩ = 1이고 두 수가 그보다 크므로","correct":true},{"t":"분모가 다르면 알 수 없으므로","mis":"M5-1-u5-X12"}],"explanation":["⟨1/2⟩ + ⟨1/2⟩ = 1이에요.","두 수가 모두 ⟨1/2⟩보다 크면 합은 1보다 커요.","그래서 ⟨1/2⟩ 기준으로 1을 넘는지 어림할 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L03_challenge#8','math',5,1,'u5','L03','g5_1_math_u5_L03_challenge','lesson_challenge','M5-1-u5-C3',4,'mc','auto','⟨3/4⟩, ⟨2/3⟩, ⟨5/6⟩, ⟨1/2⟩ 중 두 수를 골라 더할 때 합이 가장 큰 두 수는 어느 것인가요?',ARRAY['M5-1-u5-X14']::text[],true,'{"seq":8,"concept":"M5-1-u5-C3","difficulty":4,"kind":"mc","stem":"⟨3/4⟩, ⟨2/3⟩, ⟨5/6⟩, ⟨1/2⟩ 중 두 수를 골라 더할 때 합이 가장 큰 두 수는 어느 것인가요?","options":[{"t":"⟨3/4⟩과 ⟨5/6⟩","correct":true},{"t":"⟨3/4⟩과 ⟨2/3⟩","mis":"M5-1-u5-X14"},{"t":"⟨3/4⟩과 ⟨1/2⟩","mis":"M5-1-u5-X14"},{"t":"⟨2/3⟩와 ⟨5/6⟩","mis":"M5-1-u5-X14"}],"explanation":["합이 가장 크게 하려면 가장 큰 두 수를 골라요.","⟨3/4⟩ + ⟨5/6⟩ = ⟨1 7/12⟩이에요.","그래서 답은 ⟨3/4⟩과 ⟨5/6⟩예요."],"variant_rule":{"alt":[{"stem":"⟨3/5⟩, ⟨7/10⟩, ⟨1/2⟩, ⟨4/5⟩ 중 두 수를 골라 더할 때 합이 가장 큰 두 수는 어느 것인가요?","options":[{"t":"⟨7/10⟩과 ⟨4/5⟩","correct":true},{"t":"⟨3/5⟩과 ⟨7/10⟩","mis":"M5-1-u5-X14"},{"t":"⟨3/5⟩과 ⟨1/2⟩","mis":"M5-1-u5-X14"},{"t":"⟨3/5⟩과 ⟨4/5⟩","mis":"M5-1-u5-X14"}],"explanation":["합이 가장 크게 하려면 가장 큰 두 수를 골라요.","⟨7/10⟩ + ⟨4/5⟩ = ⟨1 1/2⟩이에요.","그래서 답은 ⟨7/10⟩과 ⟨4/5⟩예요."]},{"stem":"⟨5/6⟩, ⟨3/4⟩, ⟨7/12⟩, ⟨2/3⟩ 중 두 수를 골라 더할 때 합이 가장 작은 두 수는 어느 것인가요?","options":[{"t":"⟨7/12⟩과 ⟨2/3⟩","correct":true},{"t":"⟨5/6⟩와 ⟨3/4⟩","mis":"M5-1-u5-X14"},{"t":"⟨5/6⟩와 ⟨7/12⟩","mis":"M5-1-u5-X14"},{"t":"⟨5/6⟩와 ⟨2/3⟩","mis":"M5-1-u5-X14"}],"explanation":["합이 가장 작게 하려면 가장 작은 두 수를 골라요.","⟨7/12⟩ + ⟨2/3⟩ = ⟨1 1/4⟩이에요.","그래서 답은 ⟨7/12⟩과 ⟨2/3⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L03_challenge#9','math',5,1,'u5','L03','g5_1_math_u5_L03_challenge','lesson_challenge','M5-1-u5-C3',4,'sa','auto','⟨3/4⟩ + □ = ⟨1 1/6⟩일 때 □를 분모 12인 분수 ⟨○/12⟩로 나타내면 ○는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-1-u5-C3","difficulty":4,"kind":"sa","stem":"⟨3/4⟩ + □ = ⟨1 1/6⟩일 때 □를 분모 12인 분수 ⟨○/12⟩로 나타내면 ○는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["□ = ⟨1 1/6⟩ − ⟨3/4⟩이에요.","분모 12로 나타내면 ⟨14/12⟩ − ⟨9/12⟩ = ⟨5/12⟩예요.","그래서 ○는 5예요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩ + □ = ⟨1 7/12⟩일 때 □를 분모 12인 분수 ⟨○/12⟩로 나타내면 ○는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["□ = ⟨1 7/12⟩ − ⟨5/6⟩예요.","분모 12로 나타내면 ⟨19/12⟩ − ⟨10/12⟩ = ⟨9/12⟩예요.","그래서 ○는 9예요."]},{"stem":"⟨2/3⟩ + □ = ⟨1 2/9⟩일 때 □를 분모 9인 분수 ⟨○/9⟩로 나타내면 ○는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["□ = ⟨1 2/9⟩ − ⟨2/3⟩예요.","분모 9로 나타내면 ⟨11/9⟩ − ⟨6/9⟩ = ⟨5/9⟩예요.","그래서 ○는 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L03_challenge#10','math',5,1,'u5','L03','g5_1_math_u5_L03_challenge','lesson_challenge','M5-1-u5-C3',4,'essay','teacher','⟨2/3⟩ + ⟨3/4⟩ = ⟨17/12⟩을 대분수로 나타내는 방법을 「12칸」이라는 말을 써서 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u5-C3","difficulty":4,"kind":"essay","stem":"⟨2/3⟩ + ⟨3/4⟩ = ⟨17/12⟩을 대분수로 나타내는 방법을 「12칸」이라는 말을 써서 설명하세요.","answer_guide":{"answer":"예: 12칸으로 나눈 띠에서 12칸이 모이면 전체 1이 된다. ⟨17/12⟩은 17칸이므로 12칸을 덜어 내 1로 묶고, 남은 5칸이 ⟨5/12⟩이다. 그래서 ⟨17/12⟩ = ⟨1 5/12⟩이다.","scoring_points":["12칸(분모만큼)이 모이면 1이라고 썼는가","17칸에서 12칸을 덜어 내 5칸이 남는다고 썼는가","⟨1 5/12⟩로 바르게 나타냈는가"]},"explanation":["⟨12/12⟩ = 1이에요.","17칸 − 12칸 = 5칸이 남아요.","⟨17/12⟩ = ⟨1 5/12⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L04_basic#1','math',5,1,'u5','L04','g5_1_math_u5_L04_basic','lesson_basic','M5-1-u5-C4',1,'mc','auto','⟨1 1/2⟩ + ⟨2 2/5⟩를 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X02']::text[],true,'{"seq":1,"concept":"M5-1-u5-C4","difficulty":1,"kind":"mc","stem":"⟨1 1/2⟩ + ⟨2 2/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨3 9/10⟩","correct":true},{"t":"⟨3 3/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨3 9/20⟩","mis":"M5-1-u5-X03"},{"t":"⟨3 3/10⟩","mis":"M5-1-u5-X02"}],"explanation":["분수 부분을 10으로 통분하면 ⟨1 5/10⟩ + ⟨2 4/10⟩예요.","자연수끼리 1 + 2 = 3, 분수끼리 ⟨5/10⟩ + ⟨4/10⟩ = ⟨9/10⟩예요.","그래서 ⟨1 1/2⟩ + ⟨2 2/5⟩ = ⟨3 9/10⟩예요."],"variant_rule":{"alt":[{"stem":"⟨2 1/3⟩ + ⟨1 1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3 7/12⟩","correct":true},{"t":"⟨3 2/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨3 7/24⟩","mis":"M5-1-u5-X03"},{"t":"⟨3 1/6⟩","mis":"M5-1-u5-X02"}],"explanation":["분수 부분을 12로 통분하면 ⟨2 4/12⟩ + ⟨1 3/12⟩이에요.","자연수끼리 2 + 1 = 3, 분수끼리 ⟨4/12⟩ + ⟨3/12⟩ = ⟨7/12⟩이에요.","그래서 ⟨2 1/3⟩ + ⟨1 1/4⟩ = ⟨3 7/12⟩이에요."]},{"stem":"⟨1 1/6⟩ + ⟨3 3/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 11/12⟩","correct":true},{"t":"⟨4 2/5⟩","mis":"M5-1-u5-X01"},{"t":"⟨4 11/24⟩","mis":"M5-1-u5-X03"},{"t":"⟨4 1/3⟩","mis":"M5-1-u5-X02"}],"explanation":["분수 부분을 12로 통분하면 ⟨1 2/12⟩ + ⟨3 9/12⟩예요.","자연수끼리 1 + 3 = 4, 분수끼리 ⟨2/12⟩ + ⟨9/12⟩ = ⟨11/12⟩이에요.","그래서 ⟨1 1/6⟩ + ⟨3 3/4⟩ = ⟨4 11/12⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L04_basic#2','math',5,1,'u5','L04','g5_1_math_u5_L04_basic','lesson_basic','M5-1-u5-C4',1,'sa','auto','⟨1 1/2⟩ + ⟨2 2/5⟩에서 분수 부분을 분모 10으로 통분해 더한 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u5-C4","difficulty":1,"kind":"sa","stem":"⟨1 1/2⟩ + ⟨2 2/5⟩에서 분수 부분을 분모 10으로 통분해 더한 분자는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["분수 부분은 ⟨1/2⟩과 ⟨2/5⟩예요.","분모 10으로 통분하면 ⟨5/10⟩ + ⟨4/10⟩ — 분자끼리 5 + 4 = 9예요.","그래서 분자는 9예요."],"variant_rule":{"alt":[{"stem":"⟨2 1/3⟩ + ⟨1 1/4⟩에서 분수 부분을 분모 12로 통분해 더한 분자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["분수 부분은 ⟨1/3⟩과 ⟨1/4⟩이에요.","분모 12로 통분하면 ⟨4/12⟩ + ⟨3/12⟩ — 분자끼리 4 + 3 = 7이에요.","그래서 분자는 7이에요."]},{"stem":"⟨3 1/6⟩ + ⟨1 3/8⟩에서 분수 부분을 분모 24로 통분해 더한 분자는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["분수 부분은 ⟨1/6⟩과 ⟨3/8⟩이에요.","분모 24로 통분하면 ⟨4/24⟩ + ⟨9/24⟩ — 분자끼리 4 + 9 = 13이에요.","그래서 분자는 13이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L04_basic#3','math',5,1,'u5','L04','g5_1_math_u5_L04_basic','lesson_basic','M5-1-u5-C4',1,'mc','auto','⟨2 2/5⟩를 가분수로 나타내면 어느 것인가요?',ARRAY['M5-1-u5-X07']::text[],true,'{"seq":3,"concept":"M5-1-u5-C4","difficulty":1,"kind":"mc","stem":"⟨2 2/5⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨12/5⟩","correct":true},{"t":"⟨22/5⟩","mis":"M5-1-u5-X07"},{"t":"⟨4/5⟩","mis":"M5-1-u5-X07"},{"t":"⟨10/5⟩","mis":"M5-1-u5-X07"}],"explanation":["자연수 2는 ⟨10/5⟩이에요 — 2 × 5 = 10.","여기에 ⟨2/5⟩를 더하면 분자는 10 + 2 = 12예요.","⟨2 2/5⟩ = ⟨12/5⟩예요."],"variant_rule":{"alt":[{"stem":"⟨1 3/4⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨7/4⟩","correct":true},{"t":"⟨13/4⟩","mis":"M5-1-u5-X07"},{"t":"⟨4/4⟩","mis":"M5-1-u5-X07"},{"t":"⟨3/4⟩","mis":"M5-1-u5-X07"}],"explanation":["자연수 1은 ⟨4/4⟩예요 — 1 × 4 = 4.","여기에 ⟨3/4⟩을 더하면 분자는 4 + 3 = 7이에요.","⟨1 3/4⟩ = ⟨7/4⟩이에요."]},{"stem":"⟨3 1/3⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨10/3⟩","correct":true},{"t":"⟨31/3⟩","mis":"M5-1-u5-X07"},{"t":"⟨4/3⟩","mis":"M5-1-u5-X07"},{"t":"⟨9/3⟩","mis":"M5-1-u5-X07"}],"explanation":["자연수 3은 ⟨9/3⟩예요 — 3 × 3 = 9.","여기에 ⟨1/3⟩을 더하면 분자는 9 + 1 = 10이에요.","⟨3 1/3⟩ = ⟨10/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L04_basic#4','math',5,1,'u5','L04','g5_1_math_u5_L04_basic','lesson_basic','M5-1-u5-C4',1,'sa','auto','⟨1 1/2⟩ + ⟨2 2/5⟩에서 자연수 부분끼리 더하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u5-C4","difficulty":1,"kind":"sa","stem":"⟨1 1/2⟩ + ⟨2 2/5⟩에서 자연수 부분끼리 더하면 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨1 1/2⟩의 자연수 부분은 1, ⟨2 2/5⟩의 자연수 부분은 2예요.","자연수끼리 1 + 2 = 3이에요.","분수 부분은 따로 통분해 셈해요."],"variant_rule":{"alt":[{"stem":"⟨3 1/4⟩ + ⟨2 1/3⟩에서 자연수 부분끼리 더하면 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨3 1/4⟩의 자연수 부분은 3, ⟨2 1/3⟩의 자연수 부분은 2예요.","자연수끼리 3 + 2 = 5예요.","분수 부분은 따로 통분해 셈해요."]},{"stem":"⟨4 2/5⟩ + ⟨1 1/2⟩에서 자연수 부분끼리 더하면 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨4 2/5⟩의 자연수 부분은 4, ⟨1 1/2⟩의 자연수 부분은 1이에요.","자연수끼리 4 + 1 = 5예요.","분수 부분은 따로 통분해 셈해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L04_basic#5','math',5,1,'u5','L04','g5_1_math_u5_L04_basic','lesson_basic','M5-1-u5-C4',2,'mc','auto','⟨1 2/3⟩ + ⟨2 3/4⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X06']::text[],true,'{"seq":5,"concept":"M5-1-u5-C4","difficulty":2,"kind":"mc","stem":"⟨1 2/3⟩ + ⟨2 3/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 5/12⟩","correct":true},{"t":"⟨3 5/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨3 17/24⟩","mis":"M5-1-u5-X03"},{"t":"⟨3 5/12⟩","mis":"M5-1-u5-X06"}],"explanation":["분수 부분을 12로 통분하면 ⟨1 8/12⟩ + ⟨2 9/12⟩예요.","자연수끼리 1 + 2 = 3, 분수끼리 ⟨8/12⟩ + ⟨9/12⟩ = ⟨17/12⟩ = ⟨1 5/12⟩예요.","분수 부분에서 넘친 1을 자연수에 올리면 ⟨1 2/3⟩ + ⟨2 3/4⟩ = ⟨4 5/12⟩예요."],"variant_rule":{"alt":[{"stem":"⟨2 5/6⟩ + ⟨1 1/2⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 1/3⟩","correct":true},{"t":"⟨3 3/4⟩","mis":"M5-1-u5-X01"},{"t":"⟨3 2/3⟩","mis":"M5-1-u5-X03"},{"t":"⟨3 1/3⟩","mis":"M5-1-u5-X06"}],"explanation":["분수 부분을 6으로 통분하면 ⟨2 5/6⟩ + ⟨1 3/6⟩이에요.","자연수끼리 2 + 1 = 3, 분수끼리 ⟨5/6⟩ + ⟨3/6⟩ = ⟨8/6⟩ = ⟨1 1/3⟩이에요.","분수 부분에서 넘친 1을 자연수에 올리면 ⟨2 5/6⟩ + ⟨1 1/2⟩ = ⟨4 1/3⟩이에요."]},{"stem":"⟨1 3/5⟩ + ⟨1 7/10⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3 3/10⟩","correct":true},{"t":"⟨2 2/3⟩","mis":"M5-1-u5-X01"},{"t":"⟨2 13/20⟩","mis":"M5-1-u5-X03"},{"t":"⟨2 3/10⟩","mis":"M5-1-u5-X06"}],"explanation":["분수 부분을 10으로 통분하면 ⟨1 6/10⟩ + ⟨1 7/10⟩이에요.","자연수끼리 1 + 1 = 2, 분수끼리 ⟨6/10⟩ + ⟨7/10⟩ = ⟨13/10⟩ = ⟨1 3/10⟩이에요.","분수 부분에서 넘친 1을 자연수에 올리면 ⟨1 3/5⟩ + ⟨1 7/10⟩ = ⟨3 3/10⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L04_basic#6','math',5,1,'u5','L04','g5_1_math_u5_L04_basic','lesson_basic','M5-1-u5-C4',2,'sa','auto','⟨2 3/4⟩ + ⟨1 1/2⟩을 계산하여 대분수로 나타냈더니 분수 부분이 ⟨1/4⟩이었어요. 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u5-C4","difficulty":2,"kind":"sa","stem":"⟨2 3/4⟩ + ⟨1 1/2⟩을 계산하여 대분수로 나타냈더니 분수 부분이 ⟨1/4⟩이었어요. 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["분수 부분을 4로 통분하면 ⟨2 3/4⟩ + ⟨1 2/4⟩예요.","자연수끼리 2 + 1 = 3, 분수끼리 ⟨3/4⟩ + ⟨2/4⟩ = ⟨5/4⟩ = ⟨1 1/4⟩이에요.","분수 부분에서 넘친 1을 자연수에 올리면 ⟨2 3/4⟩ + ⟨1 1/2⟩ = ⟨4 1/4⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1 5/6⟩ + ⟨2 1/3⟩을 계산하여 대분수로 나타냈더니 분수 부분이 ⟨1/6⟩이었어요. 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["분수 부분을 6으로 통분하면 ⟨1 5/6⟩ + ⟨2 2/6⟩예요.","자연수끼리 1 + 2 = 3, 분수끼리 ⟨5/6⟩ + ⟨2/6⟩ = ⟨7/6⟩ = ⟨1 1/6⟩이에요.","분수 부분에서 넘친 1을 자연수에 올리면 ⟨1 5/6⟩ + ⟨2 1/3⟩ = ⟨4 1/6⟩이에요."]},{"stem":"⟨3 3/5⟩ + ⟨1 1/2⟩을 계산하여 대분수로 나타냈더니 분수 부분이 ⟨1/10⟩이었어요. 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분수 부분을 10으로 통분하면 ⟨3 6/10⟩ + ⟨1 5/10⟩예요.","자연수끼리 3 + 1 = 4, 분수끼리 ⟨6/10⟩ + ⟨5/10⟩ = ⟨11/10⟩ = ⟨1 1/10⟩이에요.","분수 부분에서 넘친 1을 자연수에 올리면 ⟨3 3/5⟩ + ⟨1 1/2⟩ = ⟨5 1/10⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L04_basic#7','math',5,1,'u5','L04','g5_1_math_u5_L04_basic','lesson_basic','M5-1-u5-C4',2,'mc','auto','⟨1 1/3⟩ + ⟨1 1/2⟩을 가분수로 바꾸어 계산할 때 알맞은 식은 어느 것인가요?',ARRAY['M5-1-u5-X08','M5-1-u5-X07']::text[],true,'{"seq":7,"concept":"M5-1-u5-C4","difficulty":2,"kind":"mc","stem":"⟨1 1/3⟩ + ⟨1 1/2⟩을 가분수로 바꾸어 계산할 때 알맞은 식은 어느 것인가요?","options":[{"t":"⟨8/6⟩ + ⟨9/6⟩","correct":true},{"t":"⟨4/3⟩ + ⟨1/2⟩","mis":"M5-1-u5-X08"},{"t":"⟨2/6⟩ + ⟨3/6⟩","mis":"M5-1-u5-X08"},{"t":"⟨11/3⟩ + ⟨11/2⟩","mis":"M5-1-u5-X07"}],"explanation":["⟨1 1/3⟩ = ⟨4/3⟩, ⟨1 1/2⟩ = ⟨3/2⟩이에요.","분모를 6으로 통분하면 ⟨4/3⟩ = ⟨8/6⟩, ⟨3/2⟩ = ⟨9/6⟩예요.","그래서 알맞은 식은 ⟨8/6⟩ + ⟨9/6⟩예요."],"variant_rule":{"alt":[{"stem":"⟨2 1/4⟩ + ⟨1 1/3⟩을 가분수로 바꾸어 계산할 때 알맞은 식은 어느 것인가요?","options":[{"t":"⟨27/12⟩ + ⟨16/12⟩","correct":true},{"t":"⟨9/4⟩ + ⟨1/3⟩","mis":"M5-1-u5-X08"},{"t":"⟨3/12⟩ + ⟨4/12⟩","mis":"M5-1-u5-X08"},{"t":"⟨21/4⟩ + ⟨11/3⟩","mis":"M5-1-u5-X07"}],"explanation":["⟨2 1/4⟩ = ⟨9/4⟩, ⟨1 1/3⟩ = ⟨4/3⟩예요.","분모를 12로 통분하면 ⟨9/4⟩ = ⟨27/12⟩, ⟨4/3⟩ = ⟨16/12⟩이에요.","그래서 알맞은 식은 ⟨27/12⟩ + ⟨16/12⟩이에요."]},{"stem":"⟨1 2/5⟩ + ⟨2 1/2⟩을 가분수로 바꾸어 계산할 때 알맞은 식은 어느 것인가요?","options":[{"t":"⟨14/10⟩ + ⟨25/10⟩","correct":true},{"t":"⟨7/5⟩ + ⟨1/2⟩","mis":"M5-1-u5-X08"},{"t":"⟨4/10⟩ + ⟨5/10⟩","mis":"M5-1-u5-X08"},{"t":"⟨12/5⟩ + ⟨21/2⟩","mis":"M5-1-u5-X07"}],"explanation":["⟨1 2/5⟩ = ⟨7/5⟩, ⟨2 1/2⟩ = ⟨5/2⟩예요.","분모를 10으로 통분하면 ⟨7/5⟩ = ⟨14/10⟩, ⟨5/2⟩ = ⟨25/10⟩예요.","그래서 알맞은 식은 ⟨14/10⟩ + ⟨25/10⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L04_basic#8','math',5,1,'u5','L04','g5_1_math_u5_L04_basic','lesson_basic','M5-1-u5-C4',2,'ox','auto','대분수의 덧셈에서 자연수끼리·분수끼리 더한 결과와 가분수로 바꾸어 더한 결과는 같아요.',ARRAY['M5-1-u5-X04']::text[],true,'{"seq":8,"concept":"M5-1-u5-C4","difficulty":2,"kind":"ox","stem":"대분수의 덧셈에서 자연수끼리·분수끼리 더한 결과와 가분수로 바꾸어 더한 결과는 같아요.","answer":"O","reason_options":[{"t":"대분수는 자연수와 분수를 더한 수이고, 더하는 순서를 바꾸어도 합은 그대로이므로","correct":true},{"t":"가분수로 바꾸면 수가 커져서 결과도 커지므로","mis":"M5-1-u5-X04"}],"mis":"M5-1-u5-X04","explanation":["⟨1 1/2⟩ + ⟨2 2/5⟩ — 자리끼리 더하면 ⟨3 9/10⟩예요.","가분수로 ⟨15/10⟩ + ⟨24/10⟩ = ⟨39/10⟩ = ⟨3 9/10⟩예요.","두 방법의 결과는 같아요."],"variant_rule":{"alt":[{"stem":"⟨2 1/4⟩ + ⟨1 1/2⟩을 자리끼리 더한 값과 ⟨9/4⟩ + ⟨3/2⟩의 값은 달라요.","answer":"X","reason_options":[{"t":"⟨2 1/4⟩ = ⟨9/4⟩, ⟨1 1/2⟩ = ⟨3/2⟩으로 같은 수를 더한 것이므로","correct":true},{"t":"하나는 대분수, 하나는 가분수이므로","mis":"M5-1-u5-X04"}],"explanation":["⟨2 1/4⟩ = ⟨9/4⟩, ⟨1 1/2⟩ = ⟨3/2⟩이에요.","자리끼리 더하면 ⟨3 3/4⟩, 가분수로 ⟨9/4⟩ + ⟨6/4⟩ = ⟨15/4⟩ = ⟨3 3/4⟩이에요.","같은 수를 더했으니 값이 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L04_basic#9','math',5,1,'u5','L04','g5_1_math_u5_L04_basic','lesson_basic','M5-1-u5-C4',2,'match','auto','대분수와 크기가 같은 가분수를 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M5-1-u5-C4","difficulty":2,"kind":"match","stem":"대분수와 크기가 같은 가분수를 이으세요.","pairs":[{"l":"⟨1 1/2⟩","r":"⟨3/2⟩"},{"l":"⟨2 2/5⟩","r":"⟨12/5⟩"},{"l":"⟨1 3/4⟩","r":"⟨7/4⟩"}],"mis":"M5-1-u5-X07","explanation":["⟨1 1/2⟩ — 1 × 2 + 1 = 3, ⟨3/2⟩이에요.","⟨2 2/5⟩ — 2 × 5 + 2 = 12, ⟨12/5⟩예요.","⟨1 3/4⟩ — 1 × 4 + 3 = 7, ⟨7/4⟩이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 대분수와 크기가 같은 가분수를 이으세요.","pairs":[{"l":"⟨2 1/3⟩","r":"⟨7/3⟩"},{"l":"⟨1 5/6⟩","r":"⟨11/6⟩"},{"l":"⟨3 1/4⟩","r":"⟨13/4⟩"}],"explanation":["⟨2 1/3⟩ — 2 × 3 + 1 = 7, ⟨7/3⟩이에요.","⟨1 5/6⟩ — 1 × 6 + 5 = 11, ⟨11/6⟩이에요.","⟨3 1/4⟩ — 3 × 4 + 1 = 13, ⟨13/4⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L04_basic#10','math',5,1,'u5','L04','g5_1_math_u5_L04_basic','lesson_basic','M5-1-u5-C4',3,'mc','auto','⟨2 1/4⟩ + ⟨1 2/3⟩를 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X02']::text[],true,'{"seq":10,"concept":"M5-1-u5-C4","difficulty":3,"kind":"mc","stem":"⟨2 1/4⟩ + ⟨1 2/3⟩를 계산하면 얼마인가요?","options":[{"t":"⟨3 11/12⟩","correct":true},{"t":"⟨3 3/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨3 11/24⟩","mis":"M5-1-u5-X03"},{"t":"⟨3 1/4⟩","mis":"M5-1-u5-X02"}],"explanation":["분수 부분을 12로 통분하면 ⟨2 3/12⟩ + ⟨1 8/12⟩이에요.","자연수끼리 2 + 1 = 3, 분수끼리 ⟨3/12⟩ + ⟨8/12⟩ = ⟨11/12⟩이에요.","그래서 ⟨2 1/4⟩ + ⟨1 2/3⟩ = ⟨3 11/12⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1 3/4⟩ + ⟨2 5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨4 7/12⟩","correct":true},{"t":"⟨3 4/5⟩","mis":"M5-1-u5-X01"},{"t":"⟨3 19/24⟩","mis":"M5-1-u5-X03"},{"t":"⟨3 7/12⟩","mis":"M5-1-u5-X06"}],"explanation":["분수 부분을 12로 통분하면 ⟨1 9/12⟩ + ⟨2 10/12⟩이에요.","자연수끼리 1 + 2 = 3, 분수끼리 ⟨9/12⟩ + ⟨10/12⟩ = ⟨19/12⟩ = ⟨1 7/12⟩이에요.","분수 부분에서 넘친 1을 자연수에 올리면 ⟨1 3/4⟩ + ⟨2 5/6⟩ = ⟨4 7/12⟩이에요."]},{"stem":"⟨3 2/5⟩ + ⟨1 3/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨5 3/20⟩","correct":true},{"t":"⟨4 5/9⟩","mis":"M5-1-u5-X01"},{"t":"⟨4 23/40⟩","mis":"M5-1-u5-X03"},{"t":"⟨4 3/20⟩","mis":"M5-1-u5-X06"}],"explanation":["분수 부분을 20으로 통분하면 ⟨3 8/20⟩ + ⟨1 15/20⟩예요.","자연수끼리 3 + 1 = 4, 분수끼리 ⟨8/20⟩ + ⟨15/20⟩ = ⟨23/20⟩ = ⟨1 3/20⟩이에요.","분수 부분에서 넘친 1을 자연수에 올리면 ⟨3 2/5⟩ + ⟨1 3/4⟩ = ⟨5 3/20⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L04_challenge#1','math',5,1,'u5','L04','g5_1_math_u5_L04_challenge','lesson_challenge','M5-1-u5-C4',2,'error','auto','⟨1 2/3⟩ + ⟨2 3/4⟩을 계산하는 과정에서 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u5-X06','M5-1-u5-X14']::text[],true,'{"seq":1,"concept":"M5-1-u5-C4","difficulty":2,"kind":"error","stem":"⟨1 2/3⟩ + ⟨2 3/4⟩을 계산하는 과정에서 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「분수끼리 더한 ⟨17/12⟩에서 넘친 1은 버리고 ⟨3 5/12⟩라고 쓰면 돼.」","correct":true,"mis_target":"M5-1-u5-X06"},{"t":"도현 — 「자연수끼리 1 + 2 = 3이야.」","mis":"M5-1-u5-X14"},{"t":"하은 — 「분수끼리 더하면 1보다 커.」","mis":"M5-1-u5-X14"}],"explanation":["분수끼리 ⟨17/12⟩ = ⟨1 5/12⟩ — 1이 넘쳐요.","넘친 1을 자연수 3에 올리면 ⟨4 5/12⟩예요.","서윤은 넘친 1을 버려 1만큼 작게 말했어요."],"variant_rule":{"alt":[{"stem":"⟨2 5/6⟩ + ⟨1 1/2⟩을 계산하는 과정에서 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「분수끼리 더한 ⟨8/6⟩에서 넘친 1은 버리고 ⟨3 1/3⟩이라고 쓰면 돼.」","correct":true,"mis_target":"M5-1-u5-X06"},{"t":"라온 — 「자연수끼리 2 + 1 = 3이야.」","mis":"M5-1-u5-X14"},{"t":"예준 — 「분수끼리 더하면 1보다 커.」","mis":"M5-1-u5-X14"}],"explanation":["분수끼리 ⟨8/6⟩ = ⟨1 1/3⟩ — 1이 넘쳐요.","넘친 1을 자연수 3에 올리면 ⟨4 1/3⟩이에요.","지민은 넘친 1을 버려 1만큼 작게 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L04_challenge#2','math',5,1,'u5','L04','g5_1_math_u5_L04_challenge','lesson_challenge','M5-1-u5-C4',2,'sa','auto','⟨1 2/3⟩ + ⟨2 3/4⟩에서 분수 부분을 분모 12로 통분해 더한 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u5-C4","difficulty":2,"kind":"sa","stem":"⟨1 2/3⟩ + ⟨2 3/4⟩에서 분수 부분을 분모 12로 통분해 더한 분자는 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["분수 부분은 ⟨2/3⟩와 ⟨3/4⟩이에요.","분모 12로 통분하면 ⟨8/12⟩ + ⟨9/12⟩ — 분자끼리 8 + 9 = 17이에요.","그래서 분자는 17이에요."],"variant_rule":{"alt":[{"stem":"⟨2 5/6⟩ + ⟨1 3/4⟩에서 분수 부분을 분모 12로 통분해 더한 분자는 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["분수 부분은 ⟨5/6⟩와 ⟨3/4⟩이에요.","분모 12로 통분하면 ⟨10/12⟩ + ⟨9/12⟩ — 분자끼리 10 + 9 = 19예요.","그래서 분자는 19예요."]},{"stem":"⟨1 4/5⟩ + ⟨1 1/2⟩에서 분수 부분을 분모 10으로 통분해 더한 분자는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["분수 부분은 ⟨4/5⟩와 ⟨1/2⟩이에요.","분모 10으로 통분하면 ⟨8/10⟩ + ⟨5/10⟩ — 분자끼리 8 + 5 = 13이에요.","그래서 분자는 13이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L04_challenge#3','math',5,1,'u5','L04','g5_1_math_u5_L04_challenge','lesson_challenge','M5-1-u5-C4',3,'mc','auto','⟨2 5/6⟩ + ⟨1 3/4⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X06']::text[],true,'{"seq":3,"concept":"M5-1-u5-C4","difficulty":3,"kind":"mc","stem":"⟨2 5/6⟩ + ⟨1 3/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 7/12⟩","correct":true},{"t":"⟨3 4/5⟩","mis":"M5-1-u5-X01"},{"t":"⟨3 19/24⟩","mis":"M5-1-u5-X03"},{"t":"⟨3 7/12⟩","mis":"M5-1-u5-X06"}],"explanation":["분수 부분을 12로 통분하면 ⟨2 10/12⟩ + ⟨1 9/12⟩예요.","자연수끼리 2 + 1 = 3, 분수끼리 ⟨10/12⟩ + ⟨9/12⟩ = ⟨19/12⟩ = ⟨1 7/12⟩이에요.","분수 부분에서 넘친 1을 자연수에 올리면 ⟨2 5/6⟩ + ⟨1 3/4⟩ = ⟨4 7/12⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1 7/8⟩ + ⟨2 1/2⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 3/8⟩","correct":true},{"t":"⟨3 4/5⟩","mis":"M5-1-u5-X01"},{"t":"⟨3 11/16⟩","mis":"M5-1-u5-X03"},{"t":"⟨3 3/8⟩","mis":"M5-1-u5-X06"}],"explanation":["분수 부분을 8로 통분하면 ⟨1 7/8⟩ + ⟨2 4/8⟩예요.","자연수끼리 1 + 2 = 3, 분수끼리 ⟨7/8⟩ + ⟨4/8⟩ = ⟨11/8⟩ = ⟨1 3/8⟩이에요.","분수 부분에서 넘친 1을 자연수에 올리면 ⟨1 7/8⟩ + ⟨2 1/2⟩ = ⟨4 3/8⟩이에요."]},{"stem":"⟨3 4/9⟩ + ⟨1 5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨5 5/18⟩","correct":true},{"t":"⟨4 3/5⟩","mis":"M5-1-u5-X01"},{"t":"⟨4 23/36⟩","mis":"M5-1-u5-X03"},{"t":"⟨4 5/18⟩","mis":"M5-1-u5-X06"}],"explanation":["분수 부분을 18로 통분하면 ⟨3 8/18⟩ + ⟨1 15/18⟩예요.","자연수끼리 3 + 1 = 4, 분수끼리 ⟨8/18⟩ + ⟨15/18⟩ = ⟨23/18⟩ = ⟨1 5/18⟩예요.","분수 부분에서 넘친 1을 자연수에 올리면 ⟨3 4/9⟩ + ⟨1 5/6⟩ = ⟨5 5/18⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L04_challenge#4','math',5,1,'u5','L04','g5_1_math_u5_L04_challenge','lesson_challenge','M5-1-u5-C4',3,'sa','auto','물통 세 개에 든 물 ⟨1 1/2⟩ L, ⟨2 1/3⟩ L, ⟨1 1/4⟩ L 모두 몇 L인지 대분수로 구했더니 분수 부분이 ⟨1/12⟩이었어요. 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u5-C4","difficulty":3,"kind":"sa","stem":"물통 세 개에 든 물 ⟨1 1/2⟩ L, ⟨2 1/3⟩ L, ⟨1 1/4⟩ L 모두 몇 L인지 대분수로 구했더니 분수 부분이 ⟨1/12⟩이었어요. 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["자연수끼리 1 + 2 + 1 = 4예요.","분수끼리 ⟨6/12⟩ + ⟨4/12⟩ + ⟨3/12⟩ = ⟨13/12⟩ = ⟨1 1/12⟩이에요.","4 + ⟨1 1/12⟩ = ⟨5 1/12⟩ — 자연수 부분은 5예요."],"variant_rule":{"alt":[{"stem":"감자 세 자루의 무게 ⟨2 1/2⟩ kg, ⟨1 2/3⟩ kg, ⟨1 1/6⟩ kg 모두 몇 kg인지 대분수로 구했더니 분수 부분이 ⟨1/3⟩이었어요. 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["자연수끼리 2 + 1 + 1 = 4예요.","분수끼리 ⟨3/6⟩ + ⟨4/6⟩ + ⟨1/6⟩ = ⟨8/6⟩ = ⟨1 1/3⟩이에요.","4 + ⟨1 1/3⟩ = ⟨5 1/3⟩ — 자연수 부분은 5예요."]},{"stem":"끈 세 도막의 길이 ⟨1 3/4⟩ m, ⟨1 1/2⟩ m, ⟨2 1/8⟩ m 모두 몇 m인지 대분수로 구했더니 분수 부분이 ⟨3/8⟩이었어요. 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["자연수끼리 1 + 1 + 2 = 4예요.","분수끼리 ⟨6/8⟩ + ⟨4/8⟩ + ⟨1/8⟩ = ⟨11/8⟩ = ⟨1 3/8⟩이에요.","4 + ⟨1 3/8⟩ = ⟨5 3/8⟩ — 자연수 부분은 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L04_challenge#5','math',5,1,'u5','L04','g5_1_math_u5_L04_challenge','lesson_challenge','M5-1-u5-C4',3,'mc','auto','⟨1 3/4⟩ + ⟨2 1/3⟩의 계산 결과와 4의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. (⟨1 3/4⟩ + ⟨2 1/3⟩ ○ 4)',ARRAY['M5-1-u5-X12','M5-1-u5-X14']::text[],true,'{"seq":5,"concept":"M5-1-u5-C4","difficulty":3,"kind":"mc","stem":"⟨1 3/4⟩ + ⟨2 1/3⟩의 계산 결과와 4의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. (⟨1 3/4⟩ + ⟨2 1/3⟩ ○ 4)","options":[{"t":">","correct":true},{"t":"<","mis":"M5-1-u5-X12"},{"t":"=","mis":"M5-1-u5-X12"},{"t":"비교할 수 없다","mis":"M5-1-u5-X14"}],"explanation":["분수 부분을 12로 통분하면 ⟨1 9/12⟩ + ⟨2 4/12⟩예요.","자연수끼리 1 + 2 = 3, 분수끼리 ⟨9/12⟩ + ⟨4/12⟩ = ⟨13/12⟩ = ⟨1 1/12⟩이에요.","⟨4 1/12⟩은 4보다 커요 — 「>」예요."],"variant_rule":{"alt":[{"stem":"⟨1 1/2⟩ + ⟨2 1/3⟩의 계산 결과와 4의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. (⟨1 1/2⟩ + ⟨2 1/3⟩ ○ 4)","options":[{"t":"<","correct":true},{"t":">","mis":"M5-1-u5-X12"},{"t":"=","mis":"M5-1-u5-X12"},{"t":"비교할 수 없다","mis":"M5-1-u5-X14"}],"explanation":["분수 부분을 6으로 통분하면 ⟨1 3/6⟩ + ⟨2 2/6⟩예요.","자연수끼리 1 + 2 = 3, 분수끼리 ⟨3/6⟩ + ⟨2/6⟩ = ⟨5/6⟩예요.","⟨3 5/6⟩는 4보다 작아요 — 「<」예요."]},{"stem":"⟨2 2/5⟩ + ⟨1 3/5⟩의 계산 결과와 4의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. (⟨2 2/5⟩ + ⟨1 3/5⟩ ○ 4)","options":[{"t":"=","correct":true},{"t":">","mis":"M5-1-u5-X12"},{"t":"<","mis":"M5-1-u5-X12"},{"t":"비교할 수 없다","mis":"M5-1-u5-X14"}],"explanation":["분모가 5로 같아서 바로 분자끼리 셈할 수 있어요.","자연수끼리 2 + 1 = 3, 분수끼리 ⟨2/5⟩ + ⟨3/5⟩ = ⟨5/5⟩ = 1이에요.","4는 4보다 같아요 — 「=」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L04_challenge#6','math',5,1,'u5','L04','g5_1_math_u5_L04_challenge','lesson_challenge','M5-1-u5-C4',3,'sa','auto','⟨2 3/4⟩ + ⟨1 1/2⟩을 가분수로 바꾸어 분모 4로 계산하면 ⟨□/4⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u5-C4","difficulty":3,"kind":"sa","stem":"⟨2 3/4⟩ + ⟨1 1/2⟩을 가분수로 바꾸어 분모 4로 계산하면 ⟨□/4⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["⟨2 3/4⟩ = ⟨11/4⟩, ⟨1 1/2⟩ = ⟨6/4⟩이에요.","분자끼리 11 + 6 = 17이에요.","⟨17/4⟩ = ⟨4 1/4⟩ — □는 17이에요."],"variant_rule":{"alt":[{"stem":"⟨1 5/6⟩ + ⟨2 1/3⟩을 가분수로 바꾸어 분모 6으로 계산하면 ⟨□/6⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["⟨1 5/6⟩ = ⟨11/6⟩, ⟨2 1/3⟩ = ⟨14/6⟩예요.","분자끼리 11 + 14 = 25예요.","⟨25/6⟩ = ⟨4 1/6⟩ — □는 25예요."]},{"stem":"⟨1 3/5⟩ + ⟨2 1/2⟩을 가분수로 바꾸어 분모 10으로 계산하면 ⟨□/10⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["41"],"explanation":["⟨1 3/5⟩ = ⟨16/10⟩, ⟨2 1/2⟩ = ⟨25/10⟩예요.","분자끼리 16 + 25 = 41이에요.","⟨41/10⟩ = ⟨4 1/10⟩ — □는 41이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L04_challenge#7','math',5,1,'u5','L04','g5_1_math_u5_L04_challenge','lesson_challenge','M5-1-u5-C4',3,'ox','auto','⟨1 1/2⟩ + ⟨2 2/3⟩는 4보다 커요.',ARRAY['M5-1-u5-X06']::text[],true,'{"seq":7,"concept":"M5-1-u5-C4","difficulty":3,"kind":"ox","stem":"⟨1 1/2⟩ + ⟨2 2/3⟩는 4보다 커요.","answer":"O","reason_options":[{"t":"자연수끼리 3이고 분수끼리 ⟨3/6⟩ + ⟨4/6⟩ = ⟨7/6⟩로 1보다 커서 4를 넘으므로","correct":true},{"t":"자연수끼리 더하면 3이라 4보다 작으므로","mis":"M5-1-u5-X06"}],"mis":"M5-1-u5-X06","explanation":["자연수끼리 1 + 2 = 3이에요.","분수끼리 ⟨3/6⟩ + ⟨4/6⟩ = ⟨7/6⟩ = ⟨1 1/6⟩ — 1이 넘쳐요.","⟨1 1/2⟩ + ⟨2 2/3⟩ = ⟨4 1/6⟩ > 4예요."],"variant_rule":{"alt":[{"stem":"⟨2 1/3⟩ + ⟨1 1/4⟩은 4보다 커요.","answer":"X","reason_options":[{"t":"분수끼리 ⟨4/12⟩ + ⟨3/12⟩ = ⟨7/12⟩로 1보다 작아 ⟨3 7/12⟩이 되므로","correct":true},{"t":"자연수가 2와 1이라 더하면 4를 넘으므로","mis":"M5-1-u5-X06"}],"explanation":["자연수끼리 2 + 1 = 3이에요.","분수끼리 ⟨4/12⟩ + ⟨3/12⟩ = ⟨7/12⟩ — 1보다 작아요.","⟨2 1/3⟩ + ⟨1 1/4⟩ = ⟨3 7/12⟩ < 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L04_challenge#8','math',5,1,'u5','L04','g5_1_math_u5_L04_challenge','lesson_challenge','M5-1-u5-C4',4,'sa','auto','분수 부분이 ⟨3/8⟩인 대분수에 ⟨1 3/4⟩을 더했더니 ⟨4 1/8⟩이 되었어요. 처음 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u5-C4","difficulty":4,"kind":"sa","stem":"분수 부분이 ⟨3/8⟩인 대분수에 ⟨1 3/4⟩을 더했더니 ⟨4 1/8⟩이 되었어요. 처음 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["처음 대분수는 ⟨4 1/8⟩ − ⟨1 3/4⟩으로 구해요.","⟨4 1/8⟩ − ⟨1 3/4⟩ = ⟨2 3/8⟩이에요.","⟨2 3/8⟩의 자연수 부분은 2예요."],"variant_rule":{"alt":[{"stem":"분수 부분이 ⟨5/6⟩인 대분수에 ⟨2 2/3⟩를 더했더니 ⟨4 1/2⟩이 되었어요. 처음 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["처음 대분수는 ⟨4 1/2⟩ − ⟨2 2/3⟩로 구해요.","⟨4 1/2⟩ − ⟨2 2/3⟩ = ⟨1 5/6⟩예요.","⟨1 5/6⟩의 자연수 부분은 1이에요."]},{"stem":"분수 부분이 ⟨2/5⟩인 대분수에 ⟨1 7/10⟩을 더했더니 ⟨4 1/10⟩이 되었어요. 처음 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["처음 대분수는 ⟨4 1/10⟩ − ⟨1 7/10⟩로 구해요.","⟨4 1/10⟩ − ⟨1 7/10⟩ = ⟨2 2/5⟩예요.","⟨2 2/5⟩의 자연수 부분은 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L04_challenge#9','math',5,1,'u5','L04','g5_1_math_u5_L04_challenge','lesson_challenge','M5-1-u5-C4',4,'mc','auto','물통 세 개에 물이 ⟨1 3/4⟩, ⟨2 1/3⟩, ⟨1 5/6⟩ L 들어 있어요. 두 통을 골라 합칠 때 4 L에 가장 가까운 두 통은 어느 것인가요?',ARRAY['M5-1-u5-X12','M5-1-u5-X14']::text[],true,'{"seq":9,"concept":"M5-1-u5-C4","difficulty":4,"kind":"mc","stem":"물통 세 개에 물이 ⟨1 3/4⟩, ⟨2 1/3⟩, ⟨1 5/6⟩ L 들어 있어요. 두 통을 골라 합칠 때 4 L에 가장 가까운 두 통은 어느 것인가요?","options":[{"t":"⟨1 3/4⟩과 ⟨2 1/3⟩","correct":true},{"t":"⟨1 3/4⟩과 ⟨1 5/6⟩","mis":"M5-1-u5-X12"},{"t":"⟨2 1/3⟩과 ⟨1 5/6⟩","mis":"M5-1-u5-X12"},{"t":"어느 두 통이나 같다","mis":"M5-1-u5-X14"}],"explanation":["세 가지 합을 구하면 ⟨1 3/4⟩ + ⟨2 1/3⟩ = ⟨4 1/12⟩, ⟨1 3/4⟩ + ⟨1 5/6⟩ = ⟨3 7/12⟩, ⟨2 1/3⟩ + ⟨1 5/6⟩ = ⟨4 1/6⟩이에요.","4과의 차는 ⟨1/12⟩, ⟨5/12⟩, ⟨1/6⟩이에요.","차가 가장 작은 것은 ⟨1 3/4⟩과 ⟨2 1/3⟩이에요."],"variant_rule":{"alt":[{"stem":"물통 세 개에 물이 ⟨2 1/4⟩, ⟨1 2/3⟩, ⟨1 5/8⟩ L 들어 있어요. 두 통을 골라 합칠 때 4 L에 가장 가까운 두 통은 어느 것인가요?","options":[{"t":"⟨2 1/4⟩과 ⟨1 2/3⟩","correct":true},{"t":"⟨2 1/4⟩과 ⟨1 5/8⟩","mis":"M5-1-u5-X12"},{"t":"⟨1 2/3⟩와 ⟨1 5/8⟩","mis":"M5-1-u5-X12"},{"t":"어느 두 통이나 같다","mis":"M5-1-u5-X14"}],"explanation":["세 가지 합을 구하면 ⟨2 1/4⟩ + ⟨1 2/3⟩ = ⟨3 11/12⟩, ⟨2 1/4⟩ + ⟨1 5/8⟩ = ⟨3 7/8⟩, ⟨1 2/3⟩ + ⟨1 5/8⟩ = ⟨3 7/24⟩이에요.","4과의 차는 ⟨1/12⟩, ⟨1/8⟩, ⟨17/24⟩이에요.","차가 가장 작은 것은 ⟨2 1/4⟩과 ⟨1 2/3⟩예요."]},{"stem":"물통 세 개에 물이 ⟨1 1/2⟩, ⟨2 3/5⟩, ⟨2 1/10⟩ L 들어 있어요. 두 통을 골라 합칠 때 4 L에 가장 가까운 두 통은 어느 것인가요?","options":[{"t":"⟨1 1/2⟩과 ⟨2 3/5⟩","correct":true},{"t":"⟨1 1/2⟩과 ⟨2 1/10⟩","mis":"M5-1-u5-X12"},{"t":"⟨2 3/5⟩과 ⟨2 1/10⟩","mis":"M5-1-u5-X12"},{"t":"어느 두 통이나 같다","mis":"M5-1-u5-X14"}],"explanation":["세 가지 합을 구하면 ⟨1 1/2⟩ + ⟨2 3/5⟩ = ⟨4 1/10⟩, ⟨1 1/2⟩ + ⟨2 1/10⟩ = ⟨3 3/5⟩, ⟨2 3/5⟩ + ⟨2 1/10⟩ = ⟨4 7/10⟩이에요.","4과의 차는 ⟨1/10⟩, ⟨2/5⟩, ⟨7/10⟩이에요.","차가 가장 작은 것은 ⟨1 1/2⟩과 ⟨2 3/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L04_challenge#10','math',5,1,'u5','L04','g5_1_math_u5_L04_challenge','lesson_challenge','M5-1-u5-C4',4,'essay','teacher','⟨1 2/3⟩ + ⟨2 3/4⟩을 「자연수끼리, 분수끼리」 더하는 방법과 「가분수로 바꾸어」 더하는 방법으로 각각 계산하고, 두 결과를 견주어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u5-C4","difficulty":4,"kind":"essay","stem":"⟨1 2/3⟩ + ⟨2 3/4⟩을 「자연수끼리, 분수끼리」 더하는 방법과 「가분수로 바꾸어」 더하는 방법으로 각각 계산하고, 두 결과를 견주어 쓰세요.","answer_guide":{"answer":"예: 자연수끼리 1 + 2 = 3, 분수끼리 ⟨8/12⟩ + ⟨9/12⟩ = ⟨17/12⟩ = ⟨1 5/12⟩니 3에 1을 올려 ⟨4 5/12⟩이다. 가분수로 바꾸면 ⟨5/3⟩ + ⟨11/4⟩ = ⟨20/12⟩ + ⟨33/12⟩ = ⟨53/12⟩ = ⟨4 5/12⟩이다. 두 결과는 같다.","scoring_points":["자리끼리 더하며 넘친 1을 자연수로 올렸는가","가분수로 바르게 바꾸어 통분해 더했는가","두 결과가 ⟨4 5/12⟩로 같다고 맺었는가"]},"explanation":["자리끼리: 3 + ⟨1 5/12⟩ = ⟨4 5/12⟩예요.","가분수로: ⟨20/12⟩ + ⟨33/12⟩ = ⟨53/12⟩ = ⟨4 5/12⟩예요.","두 방법의 결과는 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L05_basic#1','math',5,1,'u5','L05','g5_1_math_u5_L05_basic','lesson_basic','M5-1-u5-C5',1,'mc','auto','⟨3/4⟩ − ⟨1/3⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X02','M5-1-u5-X13']::text[],true,'{"seq":1,"concept":"M5-1-u5-C5","difficulty":1,"kind":"mc","stem":"⟨3/4⟩ − ⟨1/3⟩을 계산하면 얼마인가요?","options":[{"t":"⟨5/12⟩","correct":true},{"t":"2","mis":"M5-1-u5-X01"},{"t":"⟨1/6⟩","mis":"M5-1-u5-X02"},{"t":"⟨1/2⟩","mis":"M5-1-u5-X13"}],"explanation":["공통분모 12로 통분하면 ⟨9/12⟩ − ⟨4/12⟩예요.","분모는 그대로 두고 분자끼리 빼면 ⟨9/12⟩ − ⟨4/12⟩ = ⟨5/12⟩예요.","그래서 ⟨3/4⟩ − ⟨1/3⟩ = ⟨5/12⟩예요."],"variant_rule":{"alt":[{"stem":"⟨2/3⟩ − ⟨1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨5/12⟩","correct":true},{"t":"1","mis":"M5-1-u5-X01"},{"t":"⟨1/12⟩","mis":"M5-1-u5-X02"},{"t":"⟨1/2⟩","mis":"M5-1-u5-X13"}],"explanation":["공통분모 12로 통분하면 ⟨8/12⟩ − ⟨3/12⟩이에요.","분모는 그대로 두고 분자끼리 빼면 ⟨8/12⟩ − ⟨3/12⟩ = ⟨5/12⟩예요.","그래서 ⟨2/3⟩ − ⟨1/4⟩ = ⟨5/12⟩예요."]},{"stem":"⟨4/5⟩ − ⟨1/2⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3/10⟩","correct":true},{"t":"1","mis":"M5-1-u5-X01"},{"t":"⟨2/5⟩","mis":"M5-1-u5-X13"},{"t":"⟨1/5⟩","mis":"M5-1-u5-X13"}],"explanation":["공통분모 10으로 통분하면 ⟨8/10⟩ − ⟨5/10⟩예요.","분모는 그대로 두고 분자끼리 빼면 ⟨8/10⟩ − ⟨5/10⟩ = ⟨3/10⟩이에요.","그래서 ⟨4/5⟩ − ⟨1/2⟩ = ⟨3/10⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L05_basic#2','math',5,1,'u5','L05','g5_1_math_u5_L05_basic','lesson_basic','M5-1-u5-C5',1,'sa','auto','⟨3/4⟩ − ⟨1/3⟩을 분모 12로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u5-C5","difficulty":1,"kind":"sa","stem":"⟨3/4⟩ − ⟨1/3⟩을 분모 12로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모를 12로 맞추면 ⟨9/12⟩ − ⟨4/12⟩예요.","분모 12는 그대로 두고 분자끼리 9 − 4 = 5예요.","그래서 분자는 5예요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩ − ⟨1/4⟩을 분모 12로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["분모를 12로 맞추면 ⟨10/12⟩ − ⟨3/12⟩이에요.","분모 12는 그대로 두고 분자끼리 10 − 3 = 7이에요.","그래서 분자는 7이에요."]},{"stem":"⟨2/3⟩ − ⟨2/9⟩를 분모 9로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["분모를 9로 맞추면 ⟨6/9⟩ − ⟨2/9⟩예요.","분모 9는 그대로 두고 분자끼리 6 − 2 = 4예요.","그래서 분자는 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L05_basic#3','math',5,1,'u5','L05','g5_1_math_u5_L05_basic','lesson_basic','M5-1-u5-C5',1,'mc','auto','⟨5/6⟩ − ⟨1/2⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X02','M5-1-u5-X13']::text[],true,'{"seq":3,"concept":"M5-1-u5-C5","difficulty":1,"kind":"mc","stem":"⟨5/6⟩ − ⟨1/2⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"1","mis":"M5-1-u5-X01"},{"t":"⟨2/3⟩","mis":"M5-1-u5-X02"},{"t":"⟨1/2⟩","mis":"M5-1-u5-X13"}],"explanation":["공통분모 6으로 통분하면 ⟨5/6⟩ − ⟨3/6⟩이에요.","분모는 그대로 두고 분자끼리 빼면 ⟨5/6⟩ − ⟨3/6⟩ = ⟨2/6⟩ = ⟨1/3⟩이에요.","그래서 ⟨5/6⟩ − ⟨1/2⟩ = ⟨1/3⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨7/10⟩ − ⟨1/5⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨1 1/5⟩","mis":"M5-1-u5-X01"},{"t":"⟨3/5⟩","mis":"M5-1-u5-X02"},{"t":"⟨2/5⟩","mis":"M5-1-u5-X13"}],"explanation":["공통분모 10으로 통분하면 ⟨7/10⟩ − ⟨2/10⟩예요.","분모는 그대로 두고 분자끼리 빼면 ⟨7/10⟩ − ⟨2/10⟩ = ⟨5/10⟩ = ⟨1/2⟩이에요.","그래서 ⟨7/10⟩ − ⟨1/5⟩ = ⟨1/2⟩이에요."]},{"stem":"⟨3/4⟩ − ⟨1/12⟩을 계산하면 얼마인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨1/4⟩","mis":"M5-1-u5-X01"},{"t":"⟨1/6⟩","mis":"M5-1-u5-X02"},{"t":"⟨3/4⟩","mis":"M5-1-u5-X13"}],"explanation":["공통분모 12로 통분하면 ⟨9/12⟩ − ⟨1/12⟩이에요.","분모는 그대로 두고 분자끼리 빼면 ⟨9/12⟩ − ⟨1/12⟩ = ⟨8/12⟩ = ⟨2/3⟩예요.","그래서 ⟨3/4⟩ − ⟨1/12⟩ = ⟨2/3⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L05_basic#4','math',5,1,'u5','L05','g5_1_math_u5_L05_basic','lesson_basic','M5-1-u5-C5',1,'sa','auto','⟨4/5⟩ − ⟨1/2⟩을 분모 10으로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u5-C5","difficulty":1,"kind":"sa","stem":"⟨4/5⟩ − ⟨1/2⟩을 분모 10으로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["분모를 10으로 맞추면 ⟨8/10⟩ − ⟨5/10⟩예요.","분모 10은 그대로 두고 분자끼리 8 − 5 = 3이에요.","그래서 분자는 3이에요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩ − ⟨3/8⟩을 분모 24로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["분모를 24로 맞추면 ⟨20/24⟩ − ⟨9/24⟩예요.","분모 24는 그대로 두고 분자끼리 20 − 9 = 11이에요.","그래서 분자는 11이에요."]},{"stem":"⟨7/9⟩ − ⟨1/3⟩을 분모 9로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["분모를 9로 맞추면 ⟨7/9⟩ − ⟨3/9⟩이에요.","분모 9는 그대로 두고 분자끼리 7 − 3 = 4예요.","그래서 분자는 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L05_basic#5','math',5,1,'u5','L05','g5_1_math_u5_L05_basic','lesson_basic','M5-1-u5-C5',2,'error','auto','⟨2/3⟩ − ⟨1/4⟩을 다음과 같이 계산했어요. 잘못된 곳은 어디인가요?  ⟨8/12⟩ − ⟨3/12⟩ = ⟨5/0⟩',ARRAY['M5-1-u5-X03','M5-1-u5-X14']::text[],true,'{"seq":5,"concept":"M5-1-u5-C5","difficulty":2,"kind":"error","stem":"⟨2/3⟩ − ⟨1/4⟩을 다음과 같이 계산했어요. 잘못된 곳은 어디인가요?  ⟨8/12⟩ − ⟨3/12⟩ = ⟨5/0⟩","options":[{"t":"분모 12에서 12를 빼 0으로 쓴 것","correct":true,"mis_target":"M5-1-u5-X03"},{"t":"⟨2/3⟩를 ⟨8/12⟩로 바꾼 것","mis":"M5-1-u5-X14"},{"t":"⟨1/4⟩을 ⟨3/12⟩으로 바꾼 것","mis":"M5-1-u5-X14"},{"t":"분자끼리 8 − 3을 한 것","mis":"M5-1-u5-X14"}],"explanation":["통분은 바르게 했어요 — ⟨2/3⟩ = ⟨8/12⟩, ⟨1/4⟩ = ⟨3/12⟩.","분모는 조각의 이름이라 빼지 않고 그대로 둬요.","바르게 쓰면 ⟨8/12⟩ − ⟨3/12⟩ = ⟨5/12⟩예요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩ − ⟨1/4⟩을 다음과 같이 계산했어요. 잘못된 곳은 어디인가요?  ⟨10/12⟩ − ⟨3/12⟩ = ⟨7/0⟩","options":[{"t":"분모 12에서 12를 빼 0으로 쓴 것","correct":true,"mis_target":"M5-1-u5-X03"},{"t":"⟨5/6⟩를 ⟨10/12⟩으로 바꾼 것","mis":"M5-1-u5-X14"},{"t":"⟨1/4⟩을 ⟨3/12⟩으로 바꾼 것","mis":"M5-1-u5-X14"},{"t":"분자끼리 10 − 3을 한 것","mis":"M5-1-u5-X14"}],"explanation":["통분은 바르게 했어요 — ⟨5/6⟩ = ⟨10/12⟩, ⟨1/4⟩ = ⟨3/12⟩.","분모는 조각의 이름이라 빼지 않고 그대로 둬요.","바르게 쓰면 ⟨10/12⟩ − ⟨3/12⟩ = ⟨7/12⟩이에요."]},{"stem":"⟨3/5⟩ − ⟨1/2⟩을 다음과 같이 계산했어요. 잘못된 곳은 어디인가요?  ⟨6/10⟩ − ⟨5/10⟩ = ⟨1/0⟩","options":[{"t":"분모 10에서 10을 빼 0으로 쓴 것","correct":true,"mis_target":"M5-1-u5-X03"},{"t":"⟨3/5⟩을 ⟨6/10⟩으로 바꾼 것","mis":"M5-1-u5-X14"},{"t":"⟨1/2⟩을 ⟨5/10⟩로 바꾼 것","mis":"M5-1-u5-X14"},{"t":"분자끼리 6 − 5를 한 것","mis":"M5-1-u5-X14"}],"explanation":["통분은 바르게 했어요 — ⟨3/5⟩ = ⟨6/10⟩, ⟨1/2⟩ = ⟨5/10⟩.","분모는 조각의 이름이라 빼지 않고 그대로 둬요.","바르게 쓰면 ⟨6/10⟩ − ⟨5/10⟩ = ⟨1/10⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L05_basic#6','math',5,1,'u5','L05','g5_1_math_u5_L05_basic','lesson_basic','M5-1-u5-C5',2,'sa','auto','⟨3/4⟩ − ⟨1/6⟩을 분모 12로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u5-C5","difficulty":2,"kind":"sa","stem":"⟨3/4⟩ − ⟨1/6⟩을 분모 12로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["분모를 12로 맞추면 ⟨9/12⟩ − ⟨2/12⟩예요.","분모 12는 그대로 두고 분자끼리 9 − 2 = 7이에요.","그래서 분자는 7이에요."],"variant_rule":{"alt":[{"stem":"⟨5/8⟩ − ⟨1/6⟩을 분모 24로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["분모를 24로 맞추면 ⟨15/24⟩ − ⟨4/24⟩예요.","분모 24는 그대로 두고 분자끼리 15 − 4 = 11이에요.","그래서 분자는 11이에요."]},{"stem":"⟨7/10⟩ − ⟨1/4⟩을 분모 20으로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["분모를 20으로 맞추면 ⟨14/20⟩ − ⟨5/20⟩예요.","분모 20은 그대로 두고 분자끼리 14 − 5 = 9예요.","그래서 분자는 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L05_basic#7','math',5,1,'u5','L05','g5_1_math_u5_L05_basic','lesson_basic','M5-1-u5-C5',2,'sa','auto','⟨5/6⟩ − ⟨□/3⟩ = ⟨1/6⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-1-u5-C5","difficulty":2,"kind":"sa","stem":"⟨5/6⟩ − ⟨□/3⟩ = ⟨1/6⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["□가 들어간 수는 ⟨5/6⟩ − ⟨1/6⟩로 구해요.","⟨5/6⟩ − ⟨1/6⟩ = ⟨2/3⟩예요.","그래서 □는 2예요."],"variant_rule":{"alt":[{"stem":"⟨7/8⟩ − ⟨□/4⟩ = ⟨5/8⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["□가 들어간 수는 ⟨7/8⟩ − ⟨5/8⟩로 구해요.","⟨7/8⟩ − ⟨5/8⟩ = ⟨1/4⟩이에요.","그래서 □는 1이에요."]},{"stem":"⟨9/10⟩ − ⟨□/5⟩ = ⟨3/10⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["□가 들어간 수는 ⟨9/10⟩ − ⟨3/10⟩으로 구해요.","⟨9/10⟩ − ⟨3/10⟩ = ⟨3/5⟩이에요.","그래서 □는 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L05_basic#8','math',5,1,'u5','L05','g5_1_math_u5_L05_basic','lesson_basic','M5-1-u5-C5',2,'ox','auto','분수의 뺄셈은 통분한 뒤 분자끼리 빼고, 분모끼리도 빼요.',ARRAY['M5-1-u5-X03']::text[],true,'{"seq":8,"concept":"M5-1-u5-C5","difficulty":2,"kind":"ox","stem":"분수의 뺄셈은 통분한 뒤 분자끼리 빼고, 분모끼리도 빼요.","answer":"X","reason_options":[{"t":"분모는 조각의 이름이라 그대로 두고 분자끼리만 빼므로","correct":true},{"t":"뺄셈이니 분모도 분자도 모두 빼야 하므로","mis":"M5-1-u5-X03"}],"mis":"M5-1-u5-X03","explanation":["통분하면 조각 크기가 같아져요.","같은 크기의 조각 개수(분자)만 빼요.","분모는 그대로 둬요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩ − ⟨1/3⟩을 계산할 때도 먼저 통분해야 해요.","answer":"O","reason_options":[{"t":"조각 크기가 달라 그대로 덜어 낼 수 없으므로","correct":true},{"t":"뺄셈은 분자만 빼면 되므로","mis":"M5-1-u5-X01"}],"explanation":["⟨3/4⟩의 조각과 ⟨1/3⟩의 조각은 크기가 달라요.","12로 통분하면 ⟨9/12⟩ − ⟨4/12⟩ = ⟨5/12⟩예요.","뺄셈도 통분이 먼저예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L05_basic#9','math',5,1,'u5','L05','g5_1_math_u5_L05_basic','lesson_basic','M5-1-u5-C5',2,'mc','auto','⟨3/4⟩에서 ⟨1/3⟩을 덜어 내려고 그림처럼 12칸으로 맞추었어요. 남은 양은 얼마인가요?',ARRAY['M5-1-u5-X11','M5-1-u5-X13']::text[],true,'{"seq":9,"concept":"M5-1-u5-C5","difficulty":2,"kind":"mc","stem":"⟨3/4⟩에서 ⟨1/3⟩을 덜어 내려고 그림처럼 12칸으로 맞추었어요. 남은 양은 얼마인가요?","options":[{"t":"⟨5/12⟩","correct":true},{"t":"⟨1 1/12⟩","mis":"M5-1-u5-X11"},{"t":"⟨1/2⟩","mis":"M5-1-u5-X13"},{"t":"⟨1/3⟩","mis":"M5-1-u5-X13"}],"explanation":["⟨3/4⟩은 12칸 중 9칸, ⟨1/3⟩은 12칸 중 4칸이에요.","9칸에서 4칸을 덜어 내면 5칸이 남아요 — 9 − 4 = 5.","⟨9/12⟩ − ⟨4/12⟩ = ⟨5/12⟩예요."],"asset":{"type":"fbar","bars":[{"den":12,"num":9,"label":"⟨3/4⟩"},{"den":12,"num":4,"label":"⟨1/3⟩"}]},"variant_rule":{"alt":[{"stem":"⟨5/6⟩에서 ⟨1/4⟩을 덜어 내려고 그림처럼 12칸으로 맞추었어요. 남은 양은 얼마인가요?","options":[{"t":"⟨7/12⟩","correct":true},{"t":"⟨1 1/12⟩","mis":"M5-1-u5-X11"},{"t":"⟨2/3⟩","mis":"M5-1-u5-X13"},{"t":"⟨1/2⟩","mis":"M5-1-u5-X13"}],"explanation":["⟨5/6⟩는 12칸 중 10칸, ⟨1/4⟩은 12칸 중 3칸이에요.","10칸에서 3칸을 덜어 내면 7칸이 남아요 — 10 − 3 = 7.","⟨10/12⟩ − ⟨3/12⟩ = ⟨7/12⟩이에요."],"asset":{"type":"fbar","bars":[{"den":12,"num":10,"label":"⟨5/6⟩"},{"den":12,"num":3,"label":"⟨1/4⟩"}]}},{"stem":"⟨2/3⟩에서 ⟨1/2⟩을 덜어 내려고 그림처럼 6칸으로 맞추었어요. 남은 양은 얼마인가요?","options":[{"t":"⟨1/6⟩","correct":true},{"t":"⟨1 1/6⟩","mis":"M5-1-u5-X11"},{"t":"⟨1/3⟩","mis":"M5-1-u5-X13"},{"t":"0","mis":"M5-1-u5-X13"}],"explanation":["⟨2/3⟩는 6칸 중 4칸, ⟨1/2⟩은 6칸 중 3칸이에요.","4칸에서 3칸을 덜어 내면 1칸이 남아요 — 4 − 3 = 1.","⟨4/6⟩ − ⟨3/6⟩ = ⟨1/6⟩이에요."],"asset":{"type":"fbar","bars":[{"den":6,"num":4,"label":"⟨2/3⟩"},{"den":6,"num":3,"label":"⟨1/2⟩"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L05_basic#10','math',5,1,'u5','L05','g5_1_math_u5_L05_basic','lesson_basic','M5-1-u5-C5',3,'mc','auto','주스 ⟨7/8⟩ L 중에서 언니가 ⟨1/4⟩ L, 동생이 ⟨1/2⟩ L를 마셨어요. 남은 주스는 몇 L인가요?',ARRAY['M5-1-u5-X11','M5-1-u5-X13']::text[],true,'{"seq":10,"concept":"M5-1-u5-C5","difficulty":3,"kind":"mc","stem":"주스 ⟨7/8⟩ L 중에서 언니가 ⟨1/4⟩ L, 동생이 ⟨1/2⟩ L를 마셨어요. 남은 주스는 몇 L인가요?","options":[{"t":"⟨1/8⟩","correct":true},{"t":"⟨3/4⟩","mis":"M5-1-u5-X11"},{"t":"⟨5/8⟩","mis":"M5-1-u5-X11"},{"t":"⟨1/4⟩","mis":"M5-1-u5-X13"}],"explanation":["8로 통분하면 ⟨7/8⟩, ⟨2/8⟩, ⟨4/8⟩예요.","앞에서부터 차례로 빼면 ⟨7/8⟩ − ⟨2/8⟩ − ⟨4/8⟩ = ⟨1/8⟩이에요.","남은 주스는 ⟨1/8⟩ L예요."],"variant_rule":{"alt":[{"stem":"주스 ⟨5/6⟩ L 중에서 형이 ⟨1/3⟩ L, 누나가 ⟨1/4⟩ L를 마셨어요. 남은 주스는 몇 L인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"⟨7/12⟩","mis":"M5-1-u5-X11"},{"t":"⟨1/2⟩","mis":"M5-1-u5-X11"},{"t":"⟨1/3⟩","mis":"M5-1-u5-X13"}],"explanation":["12로 통분하면 ⟨10/12⟩, ⟨4/12⟩, ⟨3/12⟩이에요.","앞에서부터 차례로 빼면 ⟨10/12⟩ − ⟨4/12⟩ − ⟨3/12⟩ = ⟨3/12⟩이에요.","남은 주스는 ⟨1/4⟩ L예요."]},{"stem":"주스 ⟨9/10⟩ L 중에서 아빠가 ⟨1/2⟩ L, 엄마가 ⟨1/5⟩ L를 마셨어요. 남은 주스는 몇 L인가요?","options":[{"t":"⟨1/5⟩","correct":true},{"t":"⟨7/10⟩","mis":"M5-1-u5-X11"},{"t":"⟨2/5⟩","mis":"M5-1-u5-X11"},{"t":"⟨3/10⟩","mis":"M5-1-u5-X13"}],"explanation":["10으로 통분하면 ⟨9/10⟩, ⟨5/10⟩, ⟨2/10⟩예요.","앞에서부터 차례로 빼면 ⟨9/10⟩ − ⟨5/10⟩ − ⟨2/10⟩ = ⟨2/10⟩예요.","남은 주스는 ⟨1/5⟩ L예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L05_challenge#1','math',5,1,'u5','L05','g5_1_math_u5_L05_challenge','lesson_challenge','M5-1-u5-C5',2,'mc','auto','⟨7/10⟩ − ⟨2/5⟩를 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X02','M5-1-u5-X13']::text[],true,'{"seq":1,"concept":"M5-1-u5-C5","difficulty":2,"kind":"mc","stem":"⟨7/10⟩ − ⟨2/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨3/10⟩","correct":true},{"t":"1","mis":"M5-1-u5-X01"},{"t":"⟨1/2⟩","mis":"M5-1-u5-X02"},{"t":"⟨2/5⟩","mis":"M5-1-u5-X13"}],"explanation":["공통분모 10으로 통분하면 ⟨7/10⟩ − ⟨4/10⟩예요.","분모는 그대로 두고 분자끼리 빼면 ⟨7/10⟩ − ⟨4/10⟩ = ⟨3/10⟩이에요.","그래서 ⟨7/10⟩ − ⟨2/5⟩ = ⟨3/10⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨5/8⟩ − ⟨1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3/8⟩","correct":true},{"t":"1","mis":"M5-1-u5-X01"},{"t":"⟨1/2⟩","mis":"M5-1-u5-X02"},{"t":"⟨1/4⟩","mis":"M5-1-u5-X13"}],"explanation":["공통분모 8로 통분하면 ⟨5/8⟩ − ⟨2/8⟩예요.","분모는 그대로 두고 분자끼리 빼면 ⟨5/8⟩ − ⟨2/8⟩ = ⟨3/8⟩이에요.","그래서 ⟨5/8⟩ − ⟨1/4⟩ = ⟨3/8⟩이에요."]},{"stem":"⟨11/12⟩ − ⟨2/3⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"1","mis":"M5-1-u5-X01"},{"t":"⟨3/4⟩","mis":"M5-1-u5-X02"},{"t":"⟨1/3⟩","mis":"M5-1-u5-X13"}],"explanation":["공통분모 12로 통분하면 ⟨11/12⟩ − ⟨8/12⟩이에요.","분모는 그대로 두고 분자끼리 빼면 ⟨11/12⟩ − ⟨8/12⟩ = ⟨3/12⟩ = ⟨1/4⟩이에요.","그래서 ⟨11/12⟩ − ⟨2/3⟩ = ⟨1/4⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L05_challenge#2','math',5,1,'u5','L05','g5_1_math_u5_L05_challenge','lesson_challenge','M5-1-u5-C5',2,'sa','auto','⟨5/8⟩ − ⟨1/6⟩을 분모 24로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u5-C5","difficulty":2,"kind":"sa","stem":"⟨5/8⟩ − ⟨1/6⟩을 분모 24로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["분모를 24로 맞추면 ⟨15/24⟩ − ⟨4/24⟩예요.","분모 24는 그대로 두고 분자끼리 15 − 4 = 11이에요.","그래서 분자는 11이에요."],"variant_rule":{"alt":[{"stem":"⟨7/9⟩ − ⟨1/6⟩을 분모 18로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["분모를 18로 맞추면 ⟨14/18⟩ − ⟨3/18⟩이에요.","분모 18은 그대로 두고 분자끼리 14 − 3 = 11이에요.","그래서 분자는 11이에요."]},{"stem":"⟨4/5⟩ − ⟨3/10⟩을 분모 10으로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모를 10으로 맞추면 ⟨8/10⟩ − ⟨3/10⟩이에요.","분모 10은 그대로 두고 분자끼리 8 − 3 = 5예요.","그래서 분자는 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L05_challenge#3','math',5,1,'u5','L05','g5_1_math_u5_L05_challenge','lesson_challenge','M5-1-u5-C5',3,'mc','auto','계산 결과가 가장 큰 것은 어느 것인가요?',ARRAY['M5-1-u5-X14']::text[],true,'{"seq":3,"concept":"M5-1-u5-C5","difficulty":3,"kind":"mc","stem":"계산 결과가 가장 큰 것은 어느 것인가요?","options":[{"t":"⟨5/6⟩ − ⟨1/3⟩","correct":true},{"t":"⟨3/4⟩ − ⟨1/2⟩","mis":"M5-1-u5-X14"},{"t":"⟨2/3⟩ − ⟨1/4⟩","mis":"M5-1-u5-X14"},{"t":"⟨7/8⟩ − ⟨3/4⟩","mis":"M5-1-u5-X14"}],"explanation":["네 식을 계산하면 ⟨3/4⟩ − ⟨1/2⟩ = ⟨1/4⟩, ⟨5/6⟩ − ⟨1/3⟩ = ⟨1/2⟩, ⟨2/3⟩ − ⟨1/4⟩ = ⟨5/12⟩, ⟨7/8⟩ − ⟨3/4⟩ = ⟨1/8⟩이에요.","결과를 통분해 견주어요.","가장 큰 것은 ⟨5/6⟩ − ⟨1/3⟩이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 계산 결과가 가장 큰 것은 어느 것인가요?","options":[{"t":"⟨5/6⟩ − ⟨1/4⟩","correct":true},{"t":"⟨4/5⟩ − ⟨1/2⟩","mis":"M5-1-u5-X14"},{"t":"⟨2/3⟩ − ⟨1/6⟩","mis":"M5-1-u5-X14"},{"t":"⟨7/10⟩ − ⟨1/5⟩","mis":"M5-1-u5-X14"}],"explanation":["네 식을 계산하면 ⟨4/5⟩ − ⟨1/2⟩ = ⟨3/10⟩, ⟨2/3⟩ − ⟨1/6⟩ = ⟨1/2⟩, ⟨7/10⟩ − ⟨1/5⟩ = ⟨1/2⟩, ⟨5/6⟩ − ⟨1/4⟩ = ⟨7/12⟩이에요.","결과를 통분해 견주어요.","가장 큰 것은 ⟨5/6⟩ − ⟨1/4⟩이에요."]},{"stem":"계산 결과가 가장 작은 것은 어느 것인가요?","options":[{"t":"⟨2/3⟩ − ⟨1/2⟩","correct":true},{"t":"⟨3/4⟩ − ⟨1/3⟩","mis":"M5-1-u5-X14"},{"t":"⟨5/8⟩ − ⟨1/4⟩","mis":"M5-1-u5-X14"},{"t":"⟨7/12⟩ − ⟨1/3⟩","mis":"M5-1-u5-X14"}],"explanation":["네 식을 계산하면 ⟨3/4⟩ − ⟨1/3⟩ = ⟨5/12⟩, ⟨5/8⟩ − ⟨1/4⟩ = ⟨3/8⟩, ⟨2/3⟩ − ⟨1/2⟩ = ⟨1/6⟩, ⟨7/12⟩ − ⟨1/3⟩ = ⟨1/4⟩이에요.","결과를 통분해 견주어요.","가장 작은 것은 ⟨2/3⟩ − ⟨1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L05_challenge#4','math',5,1,'u5','L05','g5_1_math_u5_L05_challenge','lesson_challenge','M5-1-u5-C5',3,'sa','auto','⟨3/4⟩ − ⟨□/8⟩의 계산 결과가 ⟨1/4⟩보다 클 때 □에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u5-C5","difficulty":3,"kind":"sa","stem":"⟨3/4⟩ − ⟨□/8⟩의 계산 결과가 ⟨1/4⟩보다 클 때 □에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["분모를 8로 맞추면 ⟨6/8⟩ − ⟨□/8⟩ > ⟨2/8⟩예요.","6 − □가 2보다 커야 하니 □는 6 − 2 = 4보다 작아요.","그래서 가장 큰 □는 3이에요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩ − ⟨□/12⟩의 계산 결과가 ⟨1/3⟩보다 클 때 □에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모를 12로 맞추면 ⟨10/12⟩ − ⟨□/12⟩ > ⟨4/12⟩예요.","10 − □가 4보다 커야 하니 □는 10 − 4 = 6보다 작아요.","그래서 가장 큰 □는 5예요."]},{"stem":"⟨9/10⟩ − ⟨□/20⟩의 계산 결과가 ⟨1/2⟩보다 클 때 □에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["분모를 20으로 맞추면 ⟨18/20⟩ − ⟨□/20⟩ > ⟨10/20⟩이에요.","18 − □가 10보다 커야 하니 □는 18 − 10 = 8보다 작아요.","그래서 가장 큰 □는 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L05_challenge#5','math',5,1,'u5','L05','g5_1_math_u5_L05_challenge','lesson_challenge','M5-1-u5-C5',3,'mc','auto','⟨2/3⟩ + ⟨1/4⟩ − ⟨1/2⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X13','M5-1-u5-X11']::text[],true,'{"seq":5,"concept":"M5-1-u5-C5","difficulty":3,"kind":"mc","stem":"⟨2/3⟩ + ⟨1/4⟩ − ⟨1/2⟩을 계산하면 얼마인가요?","options":[{"t":"⟨5/12⟩","correct":true},{"t":"⟨1/2⟩","mis":"M5-1-u5-X13"},{"t":"⟨1/3⟩","mis":"M5-1-u5-X13"},{"t":"⟨1 5/12⟩","mis":"M5-1-u5-X11"}],"explanation":["세 분수를 12로 통분하면 ⟨8/12⟩ + ⟨3/12⟩ − ⟨6/12⟩이에요.","앞에서부터 차례로 셈하면 ⟨8/12⟩ + ⟨3/12⟩ − ⟨6/12⟩ = ⟨5/12⟩예요.","그래서 ⟨2/3⟩ + ⟨1/4⟩ − ⟨1/2⟩ = ⟨5/12⟩예요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩ − ⟨1/3⟩ + ⟨1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨5/6⟩","mis":"M5-1-u5-X13"},{"t":"⟨2/3⟩","mis":"M5-1-u5-X13"},{"t":"⟨1 5/12⟩","mis":"M5-1-u5-X11"}],"explanation":["세 분수를 12로 통분하면 ⟨10/12⟩ − ⟨4/12⟩ + ⟨3/12⟩이에요.","앞에서부터 차례로 셈하면 ⟨10/12⟩ − ⟨4/12⟩ + ⟨3/12⟩ = ⟨9/12⟩예요.","그래서 ⟨5/6⟩ − ⟨1/3⟩ + ⟨1/4⟩ = ⟨3/4⟩이에요."]},{"stem":"⟨3/5⟩ + ⟨1/2⟩ − ⟨3/10⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨9/10⟩","mis":"M5-1-u5-X13"},{"t":"⟨7/10⟩","mis":"M5-1-u5-X13"},{"t":"⟨1 2/5⟩","mis":"M5-1-u5-X11"}],"explanation":["세 분수를 10으로 통분하면 ⟨6/10⟩ + ⟨5/10⟩ − ⟨3/10⟩이에요.","앞에서부터 차례로 셈하면 ⟨6/10⟩ + ⟨5/10⟩ − ⟨3/10⟩ = ⟨8/10⟩이에요.","그래서 ⟨3/5⟩ + ⟨1/2⟩ − ⟨3/10⟩ = ⟨4/5⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L05_challenge#6','math',5,1,'u5','L05','g5_1_math_u5_L05_challenge','lesson_challenge','M5-1-u5-C5',3,'sa','auto','⟨5/6⟩ − ⟨1/4⟩을 분모 24로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u5-C5","difficulty":3,"kind":"sa","stem":"⟨5/6⟩ − ⟨1/4⟩을 분모 24로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["분모를 24로 맞추면 ⟨20/24⟩ − ⟨6/24⟩이에요.","분모 24는 그대로 두고 분자끼리 20 − 6 = 14예요.","그래서 분자는 14예요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩ − ⟨1/6⟩을 분모 24로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["분모를 24로 맞추면 ⟨18/24⟩ − ⟨4/24⟩예요.","분모 24는 그대로 두고 분자끼리 18 − 4 = 14예요.","그래서 분자는 14예요."]},{"stem":"⟨2/3⟩ − ⟨1/5⟩을 분모 30으로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["분모를 30으로 맞추면 ⟨20/30⟩ − ⟨6/30⟩이에요.","분모 30은 그대로 두고 분자끼리 20 − 6 = 14예요.","그래서 분자는 14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L05_challenge#7','math',5,1,'u5','L05','g5_1_math_u5_L05_challenge','lesson_challenge','M5-1-u5-C5',3,'ox','auto','⟨5/6⟩ − ⟨1/4⟩을 24로 통분해 계산해도 12로 통분해 계산한 답과 크기가 같아요.',ARRAY['M5-1-u5-X04']::text[],true,'{"seq":7,"concept":"M5-1-u5-C5","difficulty":3,"kind":"ox","stem":"⟨5/6⟩ − ⟨1/4⟩을 24로 통분해 계산해도 12로 통분해 계산한 답과 크기가 같아요.","answer":"O","reason_options":[{"t":"24도 6과 4의 공배수라 공통분모가 되고, 약분하면 같은 수가 되므로","correct":true},{"t":"공통분모는 최소공배수 하나뿐이므로","mis":"M5-1-u5-X04"}],"mis":"M5-1-u5-X04","explanation":["24로 통분하면 ⟨20/24⟩ − ⟨6/24⟩ = ⟨14/24⟩예요.","12로 통분하면 ⟨10/12⟩ − ⟨3/12⟩ = ⟨7/12⟩이에요.","⟨14/24⟩ = ⟨7/12⟩ — 크기가 같아요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩ − ⟨1/6⟩은 공통분모 10으로 통분해 계산할 수 있어요.","answer":"X","reason_options":[{"t":"10은 4와 6의 공배수가 아니라 공통분모가 될 수 없으므로","correct":true},{"t":"두 분모를 더한 수는 언제나 공통분모이므로","mis":"M5-1-u5-X04"}],"explanation":["공통분모는 4와 6의 공배수여야 해요 — 12, 24, 36, ….","10은 4로도 6으로도 나누어떨어지지 않아요.","12로 통분하면 ⟨9/12⟩ − ⟨2/12⟩ = ⟨7/12⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L05_challenge#8','math',5,1,'u5','L05','g5_1_math_u5_L05_challenge','lesson_challenge','M5-1-u5-C5',4,'mc','auto','⟨3/4⟩, ⟨2/5⟩, ⟨5/6⟩, ⟨1/3⟩ 중에서 가장 큰 수와 가장 작은 수의 차는 얼마인가요?',ARRAY['M5-1-u5-X11','M5-1-u5-X13']::text[],true,'{"seq":8,"concept":"M5-1-u5-C5","difficulty":4,"kind":"mc","stem":"⟨3/4⟩, ⟨2/5⟩, ⟨5/6⟩, ⟨1/3⟩ 중에서 가장 큰 수와 가장 작은 수의 차는 얼마인가요?","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨1 1/6⟩","mis":"M5-1-u5-X11"},{"t":"⟨2/3⟩","mis":"M5-1-u5-X13"},{"t":"⟨1/3⟩","mis":"M5-1-u5-X13"}],"explanation":["통분해 견주면 가장 큰 수는 ⟨5/6⟩, 가장 작은 수는 ⟨1/3⟩이에요.","⟨5/6⟩ − ⟨1/3⟩ = ⟨5/6⟩ − ⟨2/6⟩ = ⟨1/2⟩이에요.","차는 ⟨1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2/3⟩, ⟨3/8⟩, ⟨5/12⟩, ⟨7/8⟩ 중에서 가장 큰 수와 가장 작은 수의 차는 얼마인가요?","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨1 1/4⟩","mis":"M5-1-u5-X11"},{"t":"⟨5/8⟩","mis":"M5-1-u5-X13"},{"t":"⟨3/8⟩","mis":"M5-1-u5-X13"}],"explanation":["통분해 견주면 가장 큰 수는 ⟨7/8⟩, 가장 작은 수는 ⟨3/8⟩이에요.","⟨7/8⟩ − ⟨3/8⟩ = ⟨7/8⟩ − ⟨3/8⟩ = ⟨1/2⟩이에요.","차는 ⟨1/2⟩이에요."]},{"stem":"⟨4/5⟩, ⟨1/2⟩, ⟨3/10⟩, ⟨2/3⟩ 중에서 가장 큰 수와 가장 작은 수의 차는 얼마인가요?","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨1 1/10⟩","mis":"M5-1-u5-X11"},{"t":"⟨3/5⟩","mis":"M5-1-u5-X13"},{"t":"⟨2/5⟩","mis":"M5-1-u5-X13"}],"explanation":["통분해 견주면 가장 큰 수는 ⟨4/5⟩, 가장 작은 수는 ⟨3/10⟩이에요.","⟨4/5⟩ − ⟨3/10⟩ = ⟨8/10⟩ − ⟨3/10⟩ = ⟨1/2⟩이에요.","차는 ⟨1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L05_challenge#9','math',5,1,'u5','L05','g5_1_math_u5_L05_challenge','lesson_challenge','M5-1-u5-C5',4,'sa','auto','어떤 수에 ⟨1/4⟩을 더해야 할 것을 잘못하여 뺐더니 ⟨1/6⟩이 되었어요. 바르게 계산한 값을 분모 12인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-1-u5-C5","difficulty":4,"kind":"sa","stem":"어떤 수에 ⟨1/4⟩을 더해야 할 것을 잘못하여 뺐더니 ⟨1/6⟩이 되었어요. 바르게 계산한 값을 분모 12인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["어떤 수는 ⟨1/6⟩ + ⟨1/4⟩ = ⟨5/12⟩예요.","바르게 계산하면 ⟨5/12⟩ + ⟨1/4⟩ = ⟨2/3⟩예요.","⟨2/3⟩ = ⟨8/12⟩ — 분자는 8이에요."],"variant_rule":{"alt":[{"stem":"어떤 수에 ⟨1/3⟩을 더해야 할 것을 잘못하여 뺐더니 ⟨1/4⟩이 되었어요. 바르게 계산한 값을 분모 12인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["어떤 수는 ⟨1/4⟩ + ⟨1/3⟩ = ⟨7/12⟩이에요.","바르게 계산하면 ⟨7/12⟩ + ⟨1/3⟩ = ⟨11/12⟩이에요.","⟨11/12⟩ = ⟨11/12⟩ — 분자는 11이에요."]},{"stem":"어떤 수에 ⟨1/5⟩을 더해야 할 것을 잘못하여 뺐더니 ⟨1/2⟩이 되었어요. 바르게 계산한 값을 분모 10인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["어떤 수는 ⟨1/2⟩ + ⟨1/5⟩ = ⟨7/10⟩이에요.","바르게 계산하면 ⟨7/10⟩ + ⟨1/5⟩ = ⟨9/10⟩예요.","⟨9/10⟩ = ⟨9/10⟩ — 분자는 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L05_challenge#10','math',5,1,'u5','L05','g5_1_math_u5_L05_challenge','lesson_challenge','M5-1-u5-C5',4,'essay','teacher','⟨3/4⟩ − ⟨1/3⟩을 계산할 때 왜 덜어 내기 전에 통분해야 하는지 「조각」이라는 말을 써서 설명하고 답을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u5-C5","difficulty":4,"kind":"essay","stem":"⟨3/4⟩ − ⟨1/3⟩을 계산할 때 왜 덜어 내기 전에 통분해야 하는지 「조각」이라는 말을 써서 설명하고 답을 쓰세요.","answer_guide":{"answer":"예: ⟨3/4⟩의 조각과 ⟨1/3⟩의 조각은 크기가 달라서 큰 조각에서 작은 조각을 덜어 내면 몇 칸이 남았는지 셀 수 없다. 12로 통분하면 ⟨9/12⟩ − ⟨4/12⟩로 조각 크기가 같아져 9칸에서 4칸을 덜어 낸 5칸, ⟨5/12⟩가 남는다.","scoring_points":["조각 크기가 달라 그대로 덜어 낼 수 없다고 썼는가","12로 통분해 ⟨9/12⟩ − ⟨4/12⟩로 나타냈는가","분모는 그대로 두고 답 ⟨5/12⟩를 구했는가"]},"explanation":["조각 크기가 달라 그대로 덜어 낼 수 없어요.","⟨9/12⟩ − ⟨4/12⟩ — 9칸에서 4칸을 덜어 내요.","⟨3/4⟩ − ⟨1/3⟩ = ⟨5/12⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L06_basic#1','math',5,1,'u5','L06','g5_1_math_u5_L06_basic','lesson_basic','M5-1-u5-C6',1,'mc','auto','⟨3 3/4⟩ − ⟨1 1/3⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X02','M5-1-u5-X08']::text[],true,'{"seq":1,"concept":"M5-1-u5-C6","difficulty":1,"kind":"mc","stem":"⟨3 3/4⟩ − ⟨1 1/3⟩을 계산하면 얼마인가요?","options":[{"t":"⟨2 5/12⟩","correct":true},{"t":"4","mis":"M5-1-u5-X01"},{"t":"⟨2 1/6⟩","mis":"M5-1-u5-X02"},{"t":"⟨4 5/12⟩","mis":"M5-1-u5-X08"}],"explanation":["분수 부분을 12로 통분하면 ⟨3 9/12⟩ − ⟨1 4/12⟩예요.","자연수끼리 3 − 1 = 2, 분수끼리 ⟨9/12⟩ − ⟨4/12⟩ = ⟨5/12⟩예요.","그래서 ⟨3 3/4⟩ − ⟨1 1/3⟩ = ⟨2 5/12⟩예요."],"variant_rule":{"alt":[{"stem":"⟨4 5/6⟩ − ⟨2 1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨2 7/12⟩","correct":true},{"t":"4","mis":"M5-1-u5-X01"},{"t":"⟨2 1/3⟩","mis":"M5-1-u5-X02"},{"t":"⟨6 7/12⟩","mis":"M5-1-u5-X08"}],"explanation":["분수 부분을 12로 통분하면 ⟨4 10/12⟩ − ⟨2 3/12⟩이에요.","자연수끼리 4 − 2 = 2, 분수끼리 ⟨10/12⟩ − ⟨3/12⟩ = ⟨7/12⟩이에요.","그래서 ⟨4 5/6⟩ − ⟨2 1/4⟩ = ⟨2 7/12⟩이에요."]},{"stem":"⟨5 2/3⟩ − ⟨3 1/2⟩을 계산하면 얼마인가요?","options":[{"t":"⟨2 1/6⟩","correct":true},{"t":"3","mis":"M5-1-u5-X01"},{"t":"⟨8 1/6⟩","mis":"M5-1-u5-X08"},{"t":"⟨2 1/3⟩","mis":"M5-1-u5-X13"}],"explanation":["분수 부분을 6으로 통분하면 ⟨5 4/6⟩ − ⟨3 3/6⟩이에요.","자연수끼리 5 − 3 = 2, 분수끼리 ⟨4/6⟩ − ⟨3/6⟩ = ⟨1/6⟩이에요.","그래서 ⟨5 2/3⟩ − ⟨3 1/2⟩ = ⟨2 1/6⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L06_basic#2','math',5,1,'u5','L06','g5_1_math_u5_L06_basic','lesson_basic','M5-1-u5-C6',1,'sa','auto','⟨3 3/4⟩ − ⟨1 1/3⟩에서 자연수 부분끼리 빼면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u5-C6","difficulty":1,"kind":"sa","stem":"⟨3 3/4⟩ − ⟨1 1/3⟩에서 자연수 부분끼리 빼면 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨3 3/4⟩의 자연수 부분은 3, ⟨1 1/3⟩의 자연수 부분은 1이에요.","자연수끼리 3 − 1 = 2예요.","분수 부분은 따로 통분해 셈해요."],"variant_rule":{"alt":[{"stem":"⟨5 4/5⟩ − ⟨2 1/2⟩에서 자연수 부분끼리 빼면 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨5 4/5⟩의 자연수 부분은 5, ⟨2 1/2⟩의 자연수 부분은 2예요.","자연수끼리 5 − 2 = 3이에요.","분수 부분은 따로 통분해 셈해요."]},{"stem":"⟨6 2/3⟩ − ⟨4 1/4⟩에서 자연수 부분끼리 빼면 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨6 2/3⟩의 자연수 부분은 6, ⟨4 1/4⟩의 자연수 부분은 4예요.","자연수끼리 6 − 4 = 2예요.","분수 부분은 따로 통분해 셈해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L06_basic#3','math',5,1,'u5','L06','g5_1_math_u5_L06_basic','lesson_basic','M5-1-u5-C6',1,'mc','auto','⟨3 3/4⟩을 가분수로 나타내면 어느 것인가요?',ARRAY['M5-1-u5-X07']::text[],true,'{"seq":3,"concept":"M5-1-u5-C6","difficulty":1,"kind":"mc","stem":"⟨3 3/4⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨15/4⟩","correct":true},{"t":"⟨33/4⟩","mis":"M5-1-u5-X07"},{"t":"⟨6/4⟩","mis":"M5-1-u5-X07"},{"t":"⟨12/4⟩","mis":"M5-1-u5-X07"}],"explanation":["자연수 3은 ⟨12/4⟩예요 — 3 × 4 = 12.","여기에 ⟨3/4⟩을 더하면 분자는 12 + 3 = 15예요.","⟨3 3/4⟩ = ⟨15/4⟩예요."],"variant_rule":{"alt":[{"stem":"⟨2 4/5⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨14/5⟩","correct":true},{"t":"⟨24/5⟩","mis":"M5-1-u5-X07"},{"t":"⟨6/5⟩","mis":"M5-1-u5-X07"},{"t":"⟨10/5⟩","mis":"M5-1-u5-X07"}],"explanation":["자연수 2는 ⟨10/5⟩이에요 — 2 × 5 = 10.","여기에 ⟨4/5⟩를 더하면 분자는 10 + 4 = 14예요.","⟨2 4/5⟩ = ⟨14/5⟩예요."]},{"stem":"⟨4 1/3⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨13/3⟩","correct":true},{"t":"⟨41/3⟩","mis":"M5-1-u5-X07"},{"t":"⟨5/3⟩","mis":"M5-1-u5-X07"},{"t":"⟨12/3⟩","mis":"M5-1-u5-X07"}],"explanation":["자연수 4는 ⟨12/3⟩예요 — 4 × 3 = 12.","여기에 ⟨1/3⟩을 더하면 분자는 12 + 1 = 13이에요.","⟨4 1/3⟩ = ⟨13/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L06_basic#4','math',5,1,'u5','L06','g5_1_math_u5_L06_basic','lesson_basic','M5-1-u5-C6',1,'sa','auto','⟨3 3/4⟩ − ⟨1 1/3⟩에서 분수 부분을 분모 12로 통분해 뺀 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u5-C6","difficulty":1,"kind":"sa","stem":"⟨3 3/4⟩ − ⟨1 1/3⟩에서 분수 부분을 분모 12로 통분해 뺀 분자는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분수 부분은 ⟨3/4⟩과 ⟨1/3⟩이에요.","분모 12로 통분하면 ⟨9/12⟩ − ⟨4/12⟩ — 분자끼리 9 − 4 = 5예요.","그래서 분자는 5예요."],"variant_rule":{"alt":[{"stem":"⟨4 5/6⟩ − ⟨1 1/4⟩에서 분수 부분을 분모 12로 통분해 뺀 분자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["분수 부분은 ⟨5/6⟩와 ⟨1/4⟩이에요.","분모 12로 통분하면 ⟨10/12⟩ − ⟨3/12⟩ — 분자끼리 10 − 3 = 7이에요.","그래서 분자는 7이에요."]},{"stem":"⟨3 7/10⟩ − ⟨2 1/2⟩에서 분수 부분을 분모 10으로 통분해 뺀 분자는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["분수 부분은 ⟨7/10⟩과 ⟨1/2⟩이에요.","분모 10으로 통분하면 ⟨7/10⟩ − ⟨5/10⟩ — 분자끼리 7 − 5 = 2예요.","그래서 분자는 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L06_basic#5','math',5,1,'u5','L06','g5_1_math_u5_L06_basic','lesson_basic','M5-1-u5-C6',2,'mc','auto','⟨4 5/6⟩ − ⟨2 1/2⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X02','M5-1-u5-X08']::text[],true,'{"seq":5,"concept":"M5-1-u5-C6","difficulty":2,"kind":"mc","stem":"⟨4 5/6⟩ − ⟨2 1/2⟩을 계산하면 얼마인가요?","options":[{"t":"⟨2 1/3⟩","correct":true},{"t":"3","mis":"M5-1-u5-X01"},{"t":"⟨2 2/3⟩","mis":"M5-1-u5-X02"},{"t":"⟨6 1/3⟩","mis":"M5-1-u5-X08"}],"explanation":["분수 부분을 6으로 통분하면 ⟨4 5/6⟩ − ⟨2 3/6⟩이에요.","자연수끼리 4 − 2 = 2, 분수끼리 ⟨5/6⟩ − ⟨3/6⟩ = ⟨2/6⟩예요.","그래서 ⟨4 5/6⟩ − ⟨2 1/2⟩ = ⟨2 1/3⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨5 3/4⟩ − ⟨1 1/6⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 7/12⟩","correct":true},{"t":"5","mis":"M5-1-u5-X01"},{"t":"⟨4 1/6⟩","mis":"M5-1-u5-X02"},{"t":"⟨6 7/12⟩","mis":"M5-1-u5-X08"}],"explanation":["분수 부분을 12로 통분하면 ⟨5 9/12⟩ − ⟨1 2/12⟩예요.","자연수끼리 5 − 1 = 4, 분수끼리 ⟨9/12⟩ − ⟨2/12⟩ = ⟨7/12⟩이에요.","그래서 ⟨5 3/4⟩ − ⟨1 1/6⟩ = ⟨4 7/12⟩이에요."]},{"stem":"⟨3 7/8⟩ − ⟨1 1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨2 5/8⟩","correct":true},{"t":"⟨3 1/2⟩","mis":"M5-1-u5-X01"},{"t":"⟨2 3/4⟩","mis":"M5-1-u5-X02"},{"t":"⟨4 5/8⟩","mis":"M5-1-u5-X08"}],"explanation":["분수 부분을 8로 통분하면 ⟨3 7/8⟩ − ⟨1 2/8⟩예요.","자연수끼리 3 − 1 = 2, 분수끼리 ⟨7/8⟩ − ⟨2/8⟩ = ⟨5/8⟩예요.","그래서 ⟨3 7/8⟩ − ⟨1 1/4⟩ = ⟨2 5/8⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L06_basic#6','math',5,1,'u5','L06','g5_1_math_u5_L06_basic','lesson_basic','M5-1-u5-C6',2,'sa','auto','⟨29/12⟩를 대분수로 나타내면 ⟨2 □/12⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u5-C6","difficulty":2,"kind":"sa","stem":"⟨29/12⟩를 대분수로 나타내면 ⟨2 □/12⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모 12만큼 모이면 1이에요.","29칸을 12칸씩 묶으면 2묶음이고 5칸이 남아요 — 1이 2개예요.","⟨29/12⟩ = ⟨2 5/12⟩예요."],"variant_rule":{"alt":[{"stem":"⟨23/10⟩을 대분수로 나타내면 ⟨2 □/10⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["분모 10만큼 모이면 1이에요.","23칸을 10칸씩 묶으면 2묶음이고 3칸이 남아요 — 1이 2개예요.","⟨23/10⟩ = ⟨2 3/10⟩이에요."]},{"stem":"⟨19/8⟩를 대분수로 나타내면 ⟨2 □/8⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["분모 8만큼 모이면 1이에요.","19칸을 8칸씩 묶으면 2묶음이고 3칸이 남아요 — 1이 2개예요.","⟨19/8⟩ = ⟨2 3/8⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L06_basic#7','math',5,1,'u5','L06','g5_1_math_u5_L06_basic','lesson_basic','M5-1-u5-C6',2,'mc','auto','⟨2 2/3⟩ − ⟨1 1/2⟩을 가분수로 바꾸어 계산할 때 알맞은 식은 어느 것인가요?',ARRAY['M5-1-u5-X08','M5-1-u5-X07']::text[],true,'{"seq":7,"concept":"M5-1-u5-C6","difficulty":2,"kind":"mc","stem":"⟨2 2/3⟩ − ⟨1 1/2⟩을 가분수로 바꾸어 계산할 때 알맞은 식은 어느 것인가요?","options":[{"t":"⟨16/6⟩ − ⟨9/6⟩","correct":true},{"t":"⟨8/3⟩ − ⟨1/2⟩","mis":"M5-1-u5-X08"},{"t":"⟨4/6⟩ − ⟨3/6⟩","mis":"M5-1-u5-X08"},{"t":"⟨22/3⟩ − ⟨11/2⟩","mis":"M5-1-u5-X07"}],"explanation":["⟨2 2/3⟩ = ⟨8/3⟩, ⟨1 1/2⟩ = ⟨3/2⟩이에요.","분모를 6으로 통분하면 ⟨8/3⟩ = ⟨16/6⟩, ⟨3/2⟩ = ⟨9/6⟩예요.","그래서 알맞은 식은 ⟨16/6⟩ − ⟨9/6⟩예요."],"variant_rule":{"alt":[{"stem":"⟨3 3/4⟩ − ⟨1 1/3⟩을 가분수로 바꾸어 계산할 때 알맞은 식은 어느 것인가요?","options":[{"t":"⟨45/12⟩ − ⟨16/12⟩","correct":true},{"t":"⟨15/4⟩ − ⟨1/3⟩","mis":"M5-1-u5-X08"},{"t":"⟨9/12⟩ − ⟨4/12⟩","mis":"M5-1-u5-X08"},{"t":"⟨33/4⟩ − ⟨11/3⟩","mis":"M5-1-u5-X07"}],"explanation":["⟨3 3/4⟩ = ⟨15/4⟩, ⟨1 1/3⟩ = ⟨4/3⟩예요.","분모를 12로 통분하면 ⟨15/4⟩ = ⟨45/12⟩, ⟨4/3⟩ = ⟨16/12⟩이에요.","그래서 알맞은 식은 ⟨45/12⟩ − ⟨16/12⟩이에요."]},{"stem":"⟨2 4/5⟩ − ⟨1 1/2⟩을 가분수로 바꾸어 계산할 때 알맞은 식은 어느 것인가요?","options":[{"t":"⟨28/10⟩ − ⟨15/10⟩","correct":true},{"t":"⟨14/5⟩ − ⟨1/2⟩","mis":"M5-1-u5-X08"},{"t":"⟨8/10⟩ − ⟨5/10⟩","mis":"M5-1-u5-X08"},{"t":"⟨24/5⟩ − ⟨11/2⟩","mis":"M5-1-u5-X07"}],"explanation":["⟨2 4/5⟩ = ⟨14/5⟩, ⟨1 1/2⟩ = ⟨3/2⟩이에요.","분모를 10으로 통분하면 ⟨14/5⟩ = ⟨28/10⟩, ⟨3/2⟩ = ⟨15/10⟩예요.","그래서 알맞은 식은 ⟨28/10⟩ − ⟨15/10⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L06_basic#8','math',5,1,'u5','L06','g5_1_math_u5_L06_basic','lesson_basic','M5-1-u5-C6',2,'ox','auto','⟨5 2/3⟩ − ⟨2 1/4⟩은 자연수끼리 5 − 2 = 3, 분수끼리 ⟨8/12⟩ − ⟨3/12⟩ = ⟨5/12⟩라 ⟨3 5/12⟩예요.',ARRAY['M5-1-u5-X03']::text[],true,'{"seq":8,"concept":"M5-1-u5-C6","difficulty":2,"kind":"ox","stem":"⟨5 2/3⟩ − ⟨2 1/4⟩은 자연수끼리 5 − 2 = 3, 분수끼리 ⟨8/12⟩ − ⟨3/12⟩ = ⟨5/12⟩라 ⟨3 5/12⟩예요.","answer":"O","reason_options":[{"t":"자연수와 분수 부분을 각각 빼서 모았으므로","correct":true},{"t":"분수 부분은 분모끼리도 빼야 하므로","mis":"M5-1-u5-X03"}],"mis":"M5-1-u5-X03","explanation":["자연수끼리 5 − 2 = 3이에요.","분수끼리 ⟨8/12⟩ − ⟨3/12⟩ = ⟨5/12⟩예요.","⟨5 2/3⟩ − ⟨2 1/4⟩ = ⟨3 5/12⟩ — 맞아요."],"variant_rule":{"alt":[{"stem":"⟨4 5/6⟩ − ⟨1 1/2⟩은 자연수끼리 4 − 1, 분수끼리 5 − 1을 해서 ⟨3 4/6⟩예요.","answer":"X","reason_options":[{"t":"분모가 달라 분자끼리 바로 빼면 안 되고 ⟨5/6⟩ − ⟨3/6⟩으로 통분해야 하므로","correct":true},{"t":"자연수끼리 뺀 것이 틀렸으므로","mis":"M5-1-u5-X02"}],"explanation":["⟨1/2⟩ = ⟨3/6⟩으로 바꿔야 해요.","분수끼리 ⟨5/6⟩ − ⟨3/6⟩ = ⟨2/6⟩ = ⟨1/3⟩이에요.","⟨4 5/6⟩ − ⟨1 1/2⟩ = ⟨3 1/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L06_basic#9','math',5,1,'u5','L06','g5_1_math_u5_L06_basic','lesson_basic','M5-1-u5-C6',2,'match','auto','뺄셈식과 계산 결과를 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M5-1-u5-C6","difficulty":2,"kind":"match","stem":"뺄셈식과 계산 결과를 이으세요.","pairs":[{"l":"⟨3 3/4⟩ − ⟨1 1/3⟩","r":"⟨2 5/12⟩"},{"l":"⟨4 5/6⟩ − ⟨2 1/2⟩","r":"⟨2 1/3⟩"},{"l":"⟨5 2/3⟩ − ⟨2 1/4⟩","r":"⟨3 5/12⟩"}],"mis":"M5-1-u5-X13","explanation":["⟨3 3/4⟩ − ⟨1 1/3⟩ — 자연수 2, 분수 ⟨9/12⟩ − ⟨4/12⟩ = ⟨5/12⟩ → ⟨2 5/12⟩예요.","⟨4 5/6⟩ − ⟨2 1/2⟩ — 자연수 2, 분수 ⟨5/6⟩ − ⟨3/6⟩ = ⟨2/6⟩ = ⟨1/3⟩ → ⟨2 1/3⟩이에요.","⟨5 2/3⟩ − ⟨2 1/4⟩ — 자연수 3, 분수 ⟨5/12⟩ → ⟨3 5/12⟩예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 뺄셈식과 계산 결과를 이으세요.","pairs":[{"l":"⟨4 3/4⟩ − ⟨2 1/6⟩","r":"⟨2 7/12⟩"},{"l":"⟨3 4/5⟩ − ⟨1 1/2⟩","r":"⟨2 3/10⟩"},{"l":"⟨5 5/6⟩ − ⟨1 1/3⟩","r":"⟨4 1/2⟩"}],"explanation":["⟨4 3/4⟩ − ⟨2 1/6⟩ — 자연수 2, 분수 ⟨9/12⟩ − ⟨2/12⟩ = ⟨7/12⟩이에요.","⟨3 4/5⟩ − ⟨1 1/2⟩ — 자연수 2, 분수 ⟨8/10⟩ − ⟨5/10⟩ = ⟨3/10⟩이에요.","⟨5 5/6⟩ − ⟨1 1/3⟩ — 자연수 4, 분수 ⟨5/6⟩ − ⟨2/6⟩ = ⟨3/6⟩ = ⟨1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L06_basic#10','math',5,1,'u5','L06','g5_1_math_u5_L06_basic','lesson_basic','M5-1-u5-C6',3,'mc','auto','쌀이 ⟨5 2/3⟩ kg 있었는데 ⟨2 1/4⟩ kg을 썼어요. 남은 쌀은 몇 kg인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X02','M5-1-u5-X08']::text[],true,'{"seq":10,"concept":"M5-1-u5-C6","difficulty":3,"kind":"mc","stem":"쌀이 ⟨5 2/3⟩ kg 있었는데 ⟨2 1/4⟩ kg을 썼어요. 남은 쌀은 몇 kg인가요?","options":[{"t":"⟨3 5/12⟩","correct":true},{"t":"4","mis":"M5-1-u5-X01"},{"t":"⟨3 1/12⟩","mis":"M5-1-u5-X02"},{"t":"⟨7 5/12⟩","mis":"M5-1-u5-X08"}],"explanation":["분수 부분을 12로 통분하면 ⟨5 8/12⟩ − ⟨2 3/12⟩이에요.","자연수끼리 5 − 2 = 3, 분수끼리 ⟨8/12⟩ − ⟨3/12⟩ = ⟨5/12⟩예요.","그래서 ⟨5 2/3⟩ − ⟨2 1/4⟩ = ⟨3 5/12⟩예요."],"variant_rule":{"alt":[{"stem":"밀가루가 ⟨4 5/6⟩ kg 있었는데 ⟨1 3/8⟩ kg을 썼어요. 남은 밀가루는 몇 kg인가요?","options":[{"t":"⟨3 11/24⟩","correct":true},{"t":"4","mis":"M5-1-u5-X01"},{"t":"⟨3 1/12⟩","mis":"M5-1-u5-X02"},{"t":"⟨5 11/24⟩","mis":"M5-1-u5-X08"}],"explanation":["분수 부분을 24로 통분하면 ⟨4 20/24⟩ − ⟨1 9/24⟩예요.","자연수끼리 4 − 1 = 3, 분수끼리 ⟨20/24⟩ − ⟨9/24⟩ = ⟨11/24⟩이에요.","그래서 ⟨4 5/6⟩ − ⟨1 3/8⟩ = ⟨3 11/24⟩이에요."]},{"stem":"설탕이 ⟨6 3/4⟩ kg 있었는데 ⟨2 2/5⟩ kg을 썼어요. 남은 설탕은 몇 kg인가요?","options":[{"t":"⟨4 7/20⟩","correct":true},{"t":"5","mis":"M5-1-u5-X01"},{"t":"⟨4 1/20⟩","mis":"M5-1-u5-X02"},{"t":"⟨8 7/20⟩","mis":"M5-1-u5-X08"}],"explanation":["분수 부분을 20으로 통분하면 ⟨6 15/20⟩ − ⟨2 8/20⟩이에요.","자연수끼리 6 − 2 = 4, 분수끼리 ⟨15/20⟩ − ⟨8/20⟩ = ⟨7/20⟩이에요.","그래서 ⟨6 3/4⟩ − ⟨2 2/5⟩ = ⟨4 7/20⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L06_challenge#1','math',5,1,'u5','L06','g5_1_math_u5_L06_challenge','lesson_challenge','M5-1-u5-C6',2,'error','auto','⟨4 5/6⟩ − ⟨2 1/2⟩을 계산하는 과정에서 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u5-X08','M5-1-u5-X14']::text[],true,'{"seq":1,"concept":"M5-1-u5-C6","difficulty":2,"kind":"error","stem":"⟨4 5/6⟩ − ⟨2 1/2⟩을 계산하는 과정에서 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「자연수끼리 4 + 2 = 6을 써서 답은 ⟨6 1/3⟩이야.」","correct":true,"mis_target":"M5-1-u5-X08"},{"t":"도현 — 「분수 부분은 통분한 뒤 분자끼리 빼.」","mis":"M5-1-u5-X14"},{"t":"하은 — 「가분수로 바꾸어 빼도 답은 같아.」","mis":"M5-1-u5-X14"}],"explanation":["분수 부분을 6으로 통분하면 ⟨4 5/6⟩ − ⟨2 3/6⟩이에요.","자연수끼리 4 − 2 = 2, 분수끼리 ⟨5/6⟩ − ⟨3/6⟩ = ⟨2/6⟩예요.","서윤은 뺄셈인데 자연수끼리 더해 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"⟨5 3/4⟩ − ⟨1 1/3⟩을 계산하는 과정에서 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「자연수끼리 5 + 1 = 6을 써서 답은 ⟨6 5/12⟩야.」","correct":true,"mis_target":"M5-1-u5-X08"},{"t":"라온 — 「분수 부분은 통분한 뒤 분자끼리 빼.」","mis":"M5-1-u5-X14"},{"t":"예준 — 「가분수로 바꾸어 빼도 답은 같아.」","mis":"M5-1-u5-X14"}],"explanation":["분수 부분을 12로 통분하면 ⟨5 9/12⟩ − ⟨1 4/12⟩예요.","자연수끼리 5 − 1 = 4, 분수끼리 ⟨9/12⟩ − ⟨4/12⟩ = ⟨5/12⟩예요.","지민은 뺄셈인데 자연수끼리 더해 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L06_challenge#2','math',5,1,'u5','L06','g5_1_math_u5_L06_challenge','lesson_challenge','M5-1-u5-C6',2,'sa','auto','⟨3 3/4⟩ − ⟨1 1/3⟩을 가분수로 바꾸어 분모 12로 계산하면 ⟨□/12⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u5-C6","difficulty":2,"kind":"sa","stem":"⟨3 3/4⟩ − ⟨1 1/3⟩을 가분수로 바꾸어 분모 12로 계산하면 ⟨□/12⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["29"],"explanation":["⟨3 3/4⟩ = ⟨45/12⟩, ⟨1 1/3⟩ = ⟨16/12⟩이에요.","분자끼리 45 − 16 = 29예요.","⟨29/12⟩ = ⟨2 5/12⟩ — □는 29예요."],"variant_rule":{"alt":[{"stem":"⟨2 5/6⟩ − ⟨1 1/4⟩을 가분수로 바꾸어 분모 12로 계산하면 ⟨□/12⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["⟨2 5/6⟩ = ⟨34/12⟩, ⟨1 1/4⟩ = ⟨15/12⟩예요.","분자끼리 34 − 15 = 19예요.","⟨19/12⟩ = ⟨1 7/12⟩ — □는 19예요."]},{"stem":"⟨3 4/5⟩ − ⟨1 1/2⟩을 가분수로 바꾸어 분모 10으로 계산하면 ⟨□/10⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["⟨3 4/5⟩ = ⟨38/10⟩, ⟨1 1/2⟩ = ⟨15/10⟩예요.","분자끼리 38 − 15 = 23이에요.","⟨23/10⟩ = ⟨2 3/10⟩ — □는 23이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L06_challenge#3','math',5,1,'u5','L06','g5_1_math_u5_L06_challenge','lesson_challenge','M5-1-u5-C6',3,'mc','auto','⟨6 7/8⟩ − ⟨3 1/6⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X02','M5-1-u5-X08']::text[],true,'{"seq":3,"concept":"M5-1-u5-C6","difficulty":3,"kind":"mc","stem":"⟨6 7/8⟩ − ⟨3 1/6⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3 17/24⟩","correct":true},{"t":"6","mis":"M5-1-u5-X01"},{"t":"⟨3 1/4⟩","mis":"M5-1-u5-X02"},{"t":"⟨9 17/24⟩","mis":"M5-1-u5-X08"}],"explanation":["분수 부분을 24로 통분하면 ⟨6 21/24⟩ − ⟨3 4/24⟩예요.","자연수끼리 6 − 3 = 3, 분수끼리 ⟨21/24⟩ − ⟨4/24⟩ = ⟨17/24⟩이에요.","그래서 ⟨6 7/8⟩ − ⟨3 1/6⟩ = ⟨3 17/24⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨5 9/10⟩ − ⟨2 3/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3 3/20⟩","correct":true},{"t":"4","mis":"M5-1-u5-X01"},{"t":"⟨3 3/10⟩","mis":"M5-1-u5-X02"},{"t":"⟨7 3/20⟩","mis":"M5-1-u5-X08"}],"explanation":["분수 부분을 20으로 통분하면 ⟨5 18/20⟩ − ⟨2 15/20⟩예요.","자연수끼리 5 − 2 = 3, 분수끼리 ⟨18/20⟩ − ⟨15/20⟩ = ⟨3/20⟩이에요.","그래서 ⟨5 9/10⟩ − ⟨2 3/4⟩ = ⟨3 3/20⟩이에요."]},{"stem":"⟨7 5/6⟩ − ⟨4 4/9⟩를 계산하면 얼마인가요?","options":[{"t":"⟨3 7/18⟩","correct":true},{"t":"⟨3 1/3⟩","mis":"M5-1-u5-X01"},{"t":"⟨3 1/18⟩","mis":"M5-1-u5-X02"},{"t":"⟨11 7/18⟩","mis":"M5-1-u5-X08"}],"explanation":["분수 부분을 18로 통분하면 ⟨7 15/18⟩ − ⟨4 8/18⟩이에요.","자연수끼리 7 − 4 = 3, 분수끼리 ⟨15/18⟩ − ⟨8/18⟩ = ⟨7/18⟩이에요.","그래서 ⟨7 5/6⟩ − ⟨4 4/9⟩ = ⟨3 7/18⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L06_challenge#4','math',5,1,'u5','L06','g5_1_math_u5_L06_challenge','lesson_challenge','M5-1-u5-C6',3,'sa','auto','⟨4 3/4⟩ − ⟨2 1/6⟩을 계산한 값을 ⟨2 □/12⟩로 나타낼 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u5-C6","difficulty":3,"kind":"sa","stem":"⟨4 3/4⟩ − ⟨2 1/6⟩을 계산한 값을 ⟨2 □/12⟩로 나타낼 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["분수 부분을 12로 통분하면 ⟨4 9/12⟩ − ⟨2 2/12⟩예요.","자연수끼리 4 − 2 = 2, 분수끼리 ⟨9/12⟩ − ⟨2/12⟩ = ⟨7/12⟩이에요.","그래서 ⟨4 3/4⟩ − ⟨2 1/6⟩ = ⟨2 7/12⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨5 5/6⟩ − ⟨3 3/8⟩을 계산한 값을 ⟨2 □/24⟩로 나타낼 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["분수 부분을 24로 통분하면 ⟨5 20/24⟩ − ⟨3 9/24⟩예요.","자연수끼리 5 − 3 = 2, 분수끼리 ⟨20/24⟩ − ⟨9/24⟩ = ⟨11/24⟩이에요.","그래서 ⟨5 5/6⟩ − ⟨3 3/8⟩ = ⟨2 11/24⟩이에요."]},{"stem":"⟨3 9/10⟩ − ⟨1 1/4⟩을 계산한 값을 ⟨2 □/20⟩로 나타낼 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["분수 부분을 20으로 통분하면 ⟨3 18/20⟩ − ⟨1 5/20⟩예요.","자연수끼리 3 − 1 = 2, 분수끼리 ⟨18/20⟩ − ⟨5/20⟩ = ⟨13/20⟩이에요.","그래서 ⟨3 9/10⟩ − ⟨1 1/4⟩ = ⟨2 13/20⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L06_challenge#5','math',5,1,'u5','L06','g5_1_math_u5_L06_challenge','lesson_challenge','M5-1-u5-C6',3,'mc','auto','차가 가장 큰 뺄셈식은 어느 것인가요?',ARRAY['M5-1-u5-X14']::text[],true,'{"seq":5,"concept":"M5-1-u5-C6","difficulty":3,"kind":"mc","stem":"차가 가장 큰 뺄셈식은 어느 것인가요?","options":[{"t":"⟨3 7/8⟩ − ⟨1 1/4⟩","correct":true},{"t":"⟨4 5/6⟩ − ⟨2 1/3⟩","mis":"M5-1-u5-X14"},{"t":"⟨5 3/4⟩ − ⟨3 1/2⟩","mis":"M5-1-u5-X14"},{"t":"⟨6 2/3⟩ − ⟨4 1/2⟩","mis":"M5-1-u5-X14"}],"explanation":["자연수끼리, 분수끼리 빼서 계산하면 ⟨4 5/6⟩ − ⟨2 1/3⟩ = ⟨2 1/2⟩, ⟨5 3/4⟩ − ⟨3 1/2⟩ = ⟨2 1/4⟩, ⟨3 7/8⟩ − ⟨1 1/4⟩ = ⟨2 5/8⟩, ⟨6 2/3⟩ − ⟨4 1/2⟩ = ⟨2 1/6⟩이에요.","자연수 부분부터 견주고, 같으면 분수 부분을 통분해 견주어요.","차가 가장 큰 것은 ⟨3 7/8⟩ − ⟨1 1/4⟩이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 차가 가장 큰 뺄셈식은 어느 것인가요?","options":[{"t":"⟨5 5/6⟩ − ⟨3 1/4⟩","correct":true},{"t":"⟨3 4/5⟩ − ⟨1 1/2⟩","mis":"M5-1-u5-X14"},{"t":"⟨4 2/3⟩ − ⟨2 1/6⟩","mis":"M5-1-u5-X14"},{"t":"⟨6 7/10⟩ − ⟨4 1/5⟩","mis":"M5-1-u5-X14"}],"explanation":["자연수끼리, 분수끼리 빼서 계산하면 ⟨3 4/5⟩ − ⟨1 1/2⟩ = ⟨2 3/10⟩, ⟨5 5/6⟩ − ⟨3 1/4⟩ = ⟨2 7/12⟩, ⟨4 2/3⟩ − ⟨2 1/6⟩ = ⟨2 1/2⟩, ⟨6 7/10⟩ − ⟨4 1/5⟩ = ⟨2 1/2⟩이에요.","자연수 부분부터 견주고, 같으면 분수 부분을 통분해 견주어요.","차가 가장 큰 것은 ⟨5 5/6⟩ − ⟨3 1/4⟩이에요."]},{"stem":"차가 가장 작은 뺄셈식은 어느 것인가요?","options":[{"t":"⟨3 7/8⟩ − ⟨1 1/2⟩","correct":true},{"t":"⟨5 3/4⟩ − ⟨2 1/3⟩","mis":"M5-1-u5-X14"},{"t":"⟨4 5/6⟩ − ⟨1 1/2⟩","mis":"M5-1-u5-X14"},{"t":"⟨6 2/3⟩ − ⟨3 1/4⟩","mis":"M5-1-u5-X14"}],"explanation":["자연수끼리, 분수끼리 빼서 계산하면 ⟨5 3/4⟩ − ⟨2 1/3⟩ = ⟨3 5/12⟩, ⟨4 5/6⟩ − ⟨1 1/2⟩ = ⟨3 1/3⟩, ⟨6 2/3⟩ − ⟨3 1/4⟩ = ⟨3 5/12⟩, ⟨3 7/8⟩ − ⟨1 1/2⟩ = ⟨2 3/8⟩이에요.","자연수 부분부터 견주고, 같으면 분수 부분을 통분해 견주어요.","차가 가장 작은 것은 ⟨3 7/8⟩ − ⟨1 1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L06_challenge#6','math',5,1,'u5','L06','g5_1_math_u5_L06_challenge','lesson_challenge','M5-1-u5-C6',3,'sa','auto','⟨5 5/6⟩ − ⟨1 1/4⟩ − ⟨2 1/3⟩을 계산한 값을 ⟨2 □/12⟩로 나타낼 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u5-C6","difficulty":3,"kind":"sa","stem":"⟨5 5/6⟩ − ⟨1 1/4⟩ − ⟨2 1/3⟩을 계산한 값을 ⟨2 □/12⟩로 나타낼 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["앞에서부터 셈해요 — ⟨5 5/6⟩ − ⟨1 1/4⟩ = ⟨4 7/12⟩이에요.","⟨4 7/12⟩ − ⟨2 1/3⟩ = ⟨2 1/4⟩이에요.","⟨2 1/4⟩ = ⟨2 3/12⟩ — □는 3이에요."],"variant_rule":{"alt":[{"stem":"⟨6 7/8⟩ − ⟨2 1/4⟩ − ⟨1 1/2⟩을 계산한 값을 ⟨3 □/8⟩로 나타낼 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["앞에서부터 셈해요 — ⟨6 7/8⟩ − ⟨2 1/4⟩ = ⟨4 5/8⟩예요.","⟨4 5/8⟩ − ⟨1 1/2⟩ = ⟨3 1/8⟩이에요.","⟨3 1/8⟩ = ⟨3 1/8⟩ — □는 1이에요."]},{"stem":"⟨5 9/10⟩ − ⟨1 1/2⟩ − ⟨2 1/5⟩을 계산한 값을 ⟨2 □/10⟩로 나타낼 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["앞에서부터 셈해요 — ⟨5 9/10⟩ − ⟨1 1/2⟩ = ⟨4 2/5⟩예요.","⟨4 2/5⟩ − ⟨2 1/5⟩ = ⟨2 1/5⟩이에요.","⟨2 1/5⟩ = ⟨2 2/10⟩ — □는 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L06_challenge#7','math',5,1,'u5','L06','g5_1_math_u5_L06_challenge','lesson_challenge','M5-1-u5-C6',3,'ox','auto','⟨3 1/2⟩ − ⟨1 1/3⟩을 가분수로 바꾸어 계산하면 ⟨21/6⟩ − ⟨8/6⟩ = ⟨13/6⟩이고, 이것은 ⟨2 1/6⟩과 같아요.',ARRAY['M5-1-u5-X04']::text[],true,'{"seq":7,"concept":"M5-1-u5-C6","difficulty":3,"kind":"ox","stem":"⟨3 1/2⟩ − ⟨1 1/3⟩을 가분수로 바꾸어 계산하면 ⟨21/6⟩ − ⟨8/6⟩ = ⟨13/6⟩이고, 이것은 ⟨2 1/6⟩과 같아요.","answer":"O","reason_options":[{"t":"⟨3 1/2⟩ = ⟨21/6⟩, ⟨1 1/3⟩ = ⟨8/6⟩이고 ⟨13/6⟩ = ⟨2 1/6⟩이므로","correct":true},{"t":"가분수로 계산하면 자리끼리 계산한 답과 달라지므로","mis":"M5-1-u5-X04"}],"mis":"M5-1-u5-X04","explanation":["⟨3 1/2⟩ = ⟨7/2⟩ = ⟨21/6⟩, ⟨1 1/3⟩ = ⟨4/3⟩ = ⟨8/6⟩이에요.","⟨21/6⟩ − ⟨8/6⟩ = ⟨13/6⟩이에요.","⟨13/6⟩ = ⟨2 1/6⟩ — 자리끼리 뺀 답과 같아요."],"variant_rule":{"alt":[{"stem":"⟨4 3/5⟩ − ⟨2 1/2⟩을 가분수로 바꾸면 ⟨43/5⟩ − ⟨21/2⟩이에요.","answer":"X","reason_options":[{"t":"⟨4 3/5⟩ = ⟨23/5⟩, ⟨2 1/2⟩ = ⟨5/2⟩ — 자연수 × 분모 + 분자로 바꾸어야 하므로","correct":true},{"t":"자연수와 분자를 이어 쓰면 가분수가 되므로","mis":"M5-1-u5-X07"}],"explanation":["⟨4 3/5⟩ — 4 × 5 + 3 = 23, ⟨23/5⟩이에요.","⟨2 1/2⟩ — 2 × 2 + 1 = 5, ⟨5/2⟩예요.","⟨23/5⟩ − ⟨5/2⟩ = ⟨46/10⟩ − ⟨25/10⟩ = ⟨21/10⟩ = ⟨2 1/10⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L06_challenge#8','math',5,1,'u5','L06','g5_1_math_u5_L06_challenge','lesson_challenge','M5-1-u5-C6',4,'sa','auto','분수 부분이 ⟨4/5⟩인 대분수에서 ⟨2 1/2⟩을 뺐더니 ⟨3 3/10⟩이 되었어요. 처음 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u5-C6","difficulty":4,"kind":"sa","stem":"분수 부분이 ⟨4/5⟩인 대분수에서 ⟨2 1/2⟩을 뺐더니 ⟨3 3/10⟩이 되었어요. 처음 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["처음 대분수는 ⟨3 3/10⟩ + ⟨2 1/2⟩로 구해요.","⟨3 3/10⟩ + ⟨2 1/2⟩ = ⟨5 4/5⟩예요.","⟨5 4/5⟩의 자연수 부분은 5예요."],"variant_rule":{"alt":[{"stem":"분수 부분이 ⟨5/6⟩인 대분수에서 ⟨1 1/4⟩을 뺐더니 ⟨2 7/12⟩이 되었어요. 처음 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["처음 대분수는 ⟨2 7/12⟩ + ⟨1 1/4⟩로 구해요.","⟨2 7/12⟩ + ⟨1 1/4⟩ = ⟨3 5/6⟩예요.","⟨3 5/6⟩의 자연수 부분은 3이에요."]},{"stem":"분수 부분이 ⟨3/4⟩인 대분수에서 ⟨3 1/3⟩을 뺐더니 ⟨1 5/12⟩가 되었어요. 처음 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["처음 대분수는 ⟨1 5/12⟩ + ⟨3 1/3⟩로 구해요.","⟨1 5/12⟩ + ⟨3 1/3⟩ = ⟨4 3/4⟩이에요.","⟨4 3/4⟩의 자연수 부분은 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L06_challenge#9','math',5,1,'u5','L06','g5_1_math_u5_L06_challenge','lesson_challenge','M5-1-u5-C6',4,'mc','auto','빨간 끈·파란 끈·노란 끈의 길이가 ⟨3 3/4⟩ m, ⟨1 5/6⟩ m, ⟨2 2/3⟩ m예요. 가장 긴 것은 가장 짧은 것보다 몇 m 더 긴가요?',ARRAY['M5-1-u5-X11','M5-1-u5-X13']::text[],true,'{"seq":9,"concept":"M5-1-u5-C6","difficulty":4,"kind":"mc","stem":"빨간 끈·파란 끈·노란 끈의 길이가 ⟨3 3/4⟩ m, ⟨1 5/6⟩ m, ⟨2 2/3⟩ m예요. 가장 긴 것은 가장 짧은 것보다 몇 m 더 긴가요?","options":[{"t":"⟨1 11/12⟩","correct":true},{"t":"⟨5 7/12⟩","mis":"M5-1-u5-X11"},{"t":"2","mis":"M5-1-u5-X13"},{"t":"⟨1 5/6⟩","mis":"M5-1-u5-X13"}],"explanation":["가장 긴 것은 빨간 끈 ⟨3 3/4⟩ m, 가장 짧은 것은 파란 끈 ⟨1 5/6⟩ m예요.","⟨3 3/4⟩ − ⟨1 5/6⟩ = ⟨1 11/12⟩이에요.","그래서 ⟨1 11/12⟩ m 더 길어요."],"variant_rule":{"alt":[{"stem":"철사·털실·리본의 길이가 ⟨2 1/2⟩ m, ⟨4 2/5⟩ m, ⟨3 7/10⟩ m예요. 가장 긴 것은 가장 짧은 것보다 몇 m 더 긴가요?","options":[{"t":"⟨1 9/10⟩","correct":true},{"t":"⟨6 9/10⟩","mis":"M5-1-u5-X11"},{"t":"2","mis":"M5-1-u5-X13"},{"t":"⟨1 4/5⟩","mis":"M5-1-u5-X13"}],"explanation":["가장 긴 것은 털실 ⟨4 2/5⟩ m, 가장 짧은 것은 철사 ⟨2 1/2⟩ m예요.","⟨4 2/5⟩ − ⟨2 1/2⟩ = ⟨1 9/10⟩예요.","그래서 ⟨1 9/10⟩ m 더 길어요."]},{"stem":"가 막대·나 막대·다 막대의 길이가 ⟨5 5/8⟩ m, ⟨3 1/4⟩ m, ⟨4 1/2⟩ m예요. 가장 긴 것은 가장 짧은 것보다 몇 m 더 긴가요?","options":[{"t":"⟨2 3/8⟩","correct":true},{"t":"⟨8 7/8⟩","mis":"M5-1-u5-X11"},{"t":"⟨2 1/2⟩","mis":"M5-1-u5-X13"},{"t":"⟨2 1/4⟩","mis":"M5-1-u5-X13"}],"explanation":["가장 긴 것은 가 막대 ⟨5 5/8⟩ m, 가장 짧은 것은 나 막대 ⟨3 1/4⟩ m예요.","⟨5 5/8⟩ − ⟨3 1/4⟩ = ⟨2 3/8⟩이에요.","그래서 ⟨2 3/8⟩ m 더 길어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L06_challenge#10','math',5,1,'u5','L06','g5_1_math_u5_L06_challenge','lesson_challenge','M5-1-u5-C6',4,'essay','teacher','⟨3 3/4⟩ − ⟨1 1/3⟩을 자연수끼리·분수끼리 빼는 방법과 가분수로 바꾸어 빼는 방법으로 각각 계산하고, 어느 방법이 언제 편한지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u5-C6","difficulty":4,"kind":"essay","stem":"⟨3 3/4⟩ − ⟨1 1/3⟩을 자연수끼리·분수끼리 빼는 방법과 가분수로 바꾸어 빼는 방법으로 각각 계산하고, 어느 방법이 언제 편한지 쓰세요.","answer_guide":{"answer":"예: 자리끼리 빼면 자연수 3 − 1 = 2, 분수 ⟨9/12⟩ − ⟨4/12⟩ = ⟨5/12⟩라 ⟨2 5/12⟩이다. 가분수로 바꾸면 ⟨15/4⟩ − ⟨4/3⟩ = ⟨45/12⟩ − ⟨16/12⟩ = ⟨29/12⟩ = ⟨2 5/12⟩이다. 자연수가 크면 자리끼리 빼는 것이 수가 작아 편하고, 가분수는 한 번에 뺄 수 있어 편하다.","scoring_points":["자리끼리 바르게 빼서 ⟨2 5/12⟩를 구했는가","가분수로 바르게 바꾸어 ⟨29/12⟩ = ⟨2 5/12⟩를 구했는가","두 방법이 편한 때를 견주어 썼는가"]},"explanation":["자리끼리: 2와 ⟨5/12⟩ → ⟨2 5/12⟩예요.","가분수로: ⟨45/12⟩ − ⟨16/12⟩ = ⟨29/12⟩ = ⟨2 5/12⟩예요.","두 방법의 결과는 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L07_basic#1','math',5,1,'u5','L07','g5_1_math_u5_L07_basic','lesson_basic','M5-1-u5-C7',1,'mc','auto','⟨3 1/4⟩ − ⟨1 2/3⟩를 계산하면 얼마인가요?',ARRAY['M5-1-u5-X09','M5-1-u5-X10']::text[],true,'{"seq":1,"concept":"M5-1-u5-C7","difficulty":1,"kind":"mc","stem":"⟨3 1/4⟩ − ⟨1 2/3⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1 7/12⟩","correct":true},{"t":"⟨2 5/12⟩","mis":"M5-1-u5-X09"},{"t":"⟨2 7/12⟩","mis":"M5-1-u5-X10"},{"t":"⟨1 5/12⟩","mis":"M5-1-u5-X10"}],"explanation":["분수 부분을 12로 통분하면 ⟨3 3/12⟩ − ⟨1 8/12⟩이에요.","분자 3에서 8을 뺄 수 없어 자연수에서 1을 빌리면 ⟨3 3/12⟩ = ⟨2 15/12⟩예요.","⟨2 15/12⟩ − ⟨1 8/12⟩ = ⟨1 7/12⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨4 1/6⟩ − ⟨2 3/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 5/12⟩","correct":true},{"t":"⟨2 7/12⟩","mis":"M5-1-u5-X09"},{"t":"⟨2 5/12⟩","mis":"M5-1-u5-X10"},{"t":"⟨1 1/4⟩","mis":"M5-1-u5-X10"}],"explanation":["분수 부분을 12로 통분하면 ⟨4 2/12⟩ − ⟨2 9/12⟩예요.","분자 2에서 9를 뺄 수 없어 자연수에서 1을 빌리면 ⟨4 2/12⟩ = ⟨3 14/12⟩예요.","⟨3 14/12⟩ − ⟨2 9/12⟩ = ⟨1 5/12⟩예요."]},{"stem":"⟨5 1/3⟩ − ⟨1 4/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨3 8/15⟩","correct":true},{"t":"⟨4 7/15⟩","mis":"M5-1-u5-X09"},{"t":"⟨4 8/15⟩","mis":"M5-1-u5-X10"},{"t":"⟨3 1/5⟩","mis":"M5-1-u5-X10"}],"explanation":["분수 부분을 15로 통분하면 ⟨5 5/15⟩ − ⟨1 12/15⟩예요.","분자 5에서 12를 뺄 수 없어 자연수에서 1을 빌리면 ⟨5 5/15⟩ = ⟨4 20/15⟩이에요.","⟨4 20/15⟩ − ⟨1 12/15⟩ = ⟨3 8/15⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L07_basic#2','math',5,1,'u5','L07','g5_1_math_u5_L07_basic','lesson_basic','M5-1-u5-C7',1,'sa','auto','⟨3 1/4⟩을 분모 12로 통분한 뒤 자연수에서 1을 빌려 ⟨2 □/12⟩로 나타내면 □는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u5-C7","difficulty":1,"kind":"sa","stem":"⟨3 1/4⟩을 분모 12로 통분한 뒤 자연수에서 1을 빌려 ⟨2 □/12⟩로 나타내면 □는 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["⟨3 1/4⟩ = ⟨3 3/12⟩이에요.","빌려 온 1은 ⟨12/12⟩ — 분자에 12를 더해요.","⟨3 3/12⟩ = ⟨2 15/12⟩ — □는 3 + 12 = 15예요."],"variant_rule":{"alt":[{"stem":"⟨4 1/6⟩을 분모 12로 통분한 뒤 자연수에서 1을 빌려 ⟨3 □/12⟩로 나타내면 □는 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["⟨4 1/6⟩ = ⟨4 2/12⟩예요.","빌려 온 1은 ⟨12/12⟩ — 분자에 12를 더해요.","⟨4 2/12⟩ = ⟨3 14/12⟩ — □는 2 + 12 = 14예요."]},{"stem":"⟨5 1/3⟩을 분모 15로 통분한 뒤 자연수에서 1을 빌려 ⟨4 □/15⟩로 나타내면 □는 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["⟨5 1/3⟩ = ⟨5 5/15⟩예요.","빌려 온 1은 ⟨15/15⟩ — 분자에 15를 더해요.","⟨5 5/15⟩ = ⟨4 20/15⟩ — □는 5 + 15 = 20이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L07_basic#3','math',5,1,'u5','L07','g5_1_math_u5_L07_basic','lesson_basic','M5-1-u5-C7',1,'mc','auto','통분한 뒤 자연수에서 1을 빌려 와야 하는 뺄셈은 어느 것인가요?',ARRAY['M5-1-u5-X09']::text[],true,'{"seq":3,"concept":"M5-1-u5-C7","difficulty":1,"kind":"mc","stem":"통분한 뒤 자연수에서 1을 빌려 와야 하는 뺄셈은 어느 것인가요?","options":[{"t":"⟨3 1/5⟩ − ⟨1 1/2⟩","correct":true},{"t":"⟨3 3/4⟩ − ⟨1 1/3⟩","mis":"M5-1-u5-X09"},{"t":"⟨4 5/6⟩ − ⟨2 1/2⟩","mis":"M5-1-u5-X09"},{"t":"⟨5 2/3⟩ − ⟨2 1/4⟩","mis":"M5-1-u5-X09"}],"explanation":["분수 부분을 통분해 빼는 수의 분자가 더 큰지 견주어요.","⟨3 1/5⟩ − ⟨1 1/2⟩에서 분수 부분은 ⟨2/10⟩ − ⟨5/10⟩ — 2에서 5를 뺄 수 없어요.","그래서 1을 빌려 와야 하는 것은 ⟨3 1/5⟩ − ⟨1 1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 통분한 뒤 자연수에서 1을 빌려 와야 하는 뺄셈은 어느 것인가요?","options":[{"t":"⟨4 1/3⟩ − ⟨2 3/4⟩","correct":true},{"t":"⟨5 5/6⟩ − ⟨2 1/3⟩","mis":"M5-1-u5-X09"},{"t":"⟨3 3/4⟩ − ⟨1 1/2⟩","mis":"M5-1-u5-X09"},{"t":"⟨6 2/3⟩ − ⟨1 1/6⟩","mis":"M5-1-u5-X09"}],"explanation":["분수 부분을 통분해 빼는 수의 분자가 더 큰지 견주어요.","⟨4 1/3⟩ − ⟨2 3/4⟩에서 분수 부분은 ⟨4/12⟩ − ⟨9/12⟩ — 4에서 9를 뺄 수 없어요.","그래서 1을 빌려 와야 하는 것은 ⟨4 1/3⟩ − ⟨2 3/4⟩이에요."]},{"stem":"이번에는 다른 보기예요. 통분한 뒤 자연수에서 1을 빌려 와야 하는 뺄셈은 어느 것인가요?","options":[{"t":"⟨4 1/2⟩ − ⟨1 5/6⟩","correct":true},{"t":"⟨5 4/5⟩ − ⟨2 1/2⟩","mis":"M5-1-u5-X09"},{"t":"⟨3 2/3⟩ − ⟨1 1/4⟩","mis":"M5-1-u5-X09"},{"t":"⟨6 3/4⟩ − ⟨2 1/3⟩","mis":"M5-1-u5-X09"}],"explanation":["분수 부분을 통분해 빼는 수의 분자가 더 큰지 견주어요.","⟨4 1/2⟩ − ⟨1 5/6⟩에서 분수 부분은 ⟨3/6⟩ − ⟨5/6⟩ — 3에서 5를 뺄 수 없어요.","그래서 1을 빌려 와야 하는 것은 ⟨4 1/2⟩ − ⟨1 5/6⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L07_basic#4','math',5,1,'u5','L07','g5_1_math_u5_L07_basic','lesson_basic','M5-1-u5-C7',1,'sa','auto','자연수에서 1을 빌려 분모가 12인 분수로 바꾸면 ⟨□/12⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u5-C7","difficulty":1,"kind":"sa","stem":"자연수에서 1을 빌려 분모가 12인 분수로 바꾸면 ⟨□/12⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["1은 전체 — 12칸으로 나눈 것 중 12칸이에요.","그래서 1 = ⟨12/12⟩예요.","1을 빌려 오면 분자에 12를 더해요."],"variant_rule":{"alt":[{"stem":"자연수에서 1을 빌려 분모가 8인 분수로 바꾸면 ⟨□/8⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["1은 8칸 중 8칸이에요.","그래서 1 = ⟨8/8⟩이에요.","1을 빌려 오면 분자에 8을 더해요."]},{"stem":"자연수에서 1을 빌려 분모가 15인 분수로 바꾸면 ⟨□/15⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["1은 15칸 중 15칸이에요.","그래서 1 = ⟨15/15⟩예요.","1을 빌려 오면 분자에 15를 더해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L07_basic#5','math',5,1,'u5','L07','g5_1_math_u5_L07_basic','lesson_basic','M5-1-u5-C7',2,'mc','auto','⟨4 1/4⟩ − ⟨1 5/6⟩를 계산하면 얼마인가요?',ARRAY['M5-1-u5-X09','M5-1-u5-X10']::text[],true,'{"seq":5,"concept":"M5-1-u5-C7","difficulty":2,"kind":"mc","stem":"⟨4 1/4⟩ − ⟨1 5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨2 5/12⟩","correct":true},{"t":"⟨3 7/12⟩","mis":"M5-1-u5-X09"},{"t":"⟨3 5/12⟩","mis":"M5-1-u5-X10"},{"t":"⟨2 1/4⟩","mis":"M5-1-u5-X10"}],"explanation":["분수 부분을 12로 통분하면 ⟨4 3/12⟩ − ⟨1 10/12⟩이에요.","분자 3에서 10을 뺄 수 없어 자연수에서 1을 빌리면 ⟨4 3/12⟩ = ⟨3 15/12⟩예요.","⟨3 15/12⟩ − ⟨1 10/12⟩ = ⟨2 5/12⟩예요."],"variant_rule":{"alt":[{"stem":"⟨6 1/4⟩ − ⟨3 5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨2 5/12⟩","correct":true},{"t":"⟨3 7/12⟩","mis":"M5-1-u5-X09"},{"t":"⟨3 5/12⟩","mis":"M5-1-u5-X10"},{"t":"⟨2 1/4⟩","mis":"M5-1-u5-X10"}],"explanation":["분수 부분을 12로 통분하면 ⟨6 3/12⟩ − ⟨3 10/12⟩이에요.","분자 3에서 10을 뺄 수 없어 자연수에서 1을 빌리면 ⟨6 3/12⟩ = ⟨5 15/12⟩예요.","⟨5 15/12⟩ − ⟨3 10/12⟩ = ⟨2 5/12⟩예요."]},{"stem":"⟨4 2/5⟩ − ⟨1 1/2⟩을 계산하면 얼마인가요?","options":[{"t":"⟨2 9/10⟩","correct":true},{"t":"⟨3 1/10⟩","mis":"M5-1-u5-X09"},{"t":"⟨3 9/10⟩","mis":"M5-1-u5-X10"},{"t":"3","mis":"M5-1-u5-X13"}],"explanation":["분수 부분을 10으로 통분하면 ⟨4 4/10⟩ − ⟨1 5/10⟩예요.","분자 4에서 5를 뺄 수 없어 자연수에서 1을 빌리면 ⟨4 4/10⟩ = ⟨3 14/10⟩예요.","⟨3 14/10⟩ − ⟨1 5/10⟩ = ⟨2 9/10⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L07_basic#6','math',5,1,'u5','L07','g5_1_math_u5_L07_basic','lesson_basic','M5-1-u5-C7',2,'sa','auto','⟨1 2/12⟩ − ⟨7/12⟩을 계산한 값을 ⟨□/12⟩로 나타낼 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u5-C7","difficulty":2,"kind":"sa","stem":"⟨1 2/12⟩ − ⟨7/12⟩을 계산한 값을 ⟨□/12⟩로 나타낼 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["분모가 12로 같아서 바로 분자끼리 셈할 수 있어요.","분자 2에서 7을 뺄 수 없어 자연수에서 1을 빌리면 ⟨1 2/12⟩ = ⟨14/12⟩예요.","⟨14/12⟩ − ⟨7/12⟩ = ⟨7/12⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2 1/8⟩ − ⟨1 5/8⟩를 계산한 값을 ⟨□/8⟩로 나타낼 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["분모가 8로 같아서 바로 분자끼리 셈할 수 있어요.","분자 1에서 5를 뺄 수 없어 자연수에서 1을 빌리면 ⟨2 1/8⟩ = ⟨1 9/8⟩예요.","⟨1 9/8⟩ − ⟨1 5/8⟩ = ⟨4/8⟩ = ⟨1/2⟩이에요. ⟨1/2⟩ = ⟨4/8⟩니 □는 4예요."]},{"stem":"⟨1 3/10⟩ − ⟨7/10⟩을 계산한 값을 ⟨□/10⟩로 나타낼 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["분모가 10으로 같아서 바로 분자끼리 셈할 수 있어요.","분자 3에서 7을 뺄 수 없어 자연수에서 1을 빌리면 ⟨1 3/10⟩ = ⟨13/10⟩이에요.","⟨13/10⟩ − ⟨7/10⟩ = ⟨6/10⟩ = ⟨3/5⟩이에요. ⟨3/5⟩ = ⟨6/10⟩이니 □는 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L07_basic#7','math',5,1,'u5','L07','g5_1_math_u5_L07_basic','lesson_basic','M5-1-u5-C7',2,'mc','auto','3 − ⟨1 2/5⟩를 계산하면 얼마인가요?',ARRAY['M5-1-u5-X10','M5-1-u5-X09']::text[],true,'{"seq":7,"concept":"M5-1-u5-C7","difficulty":2,"kind":"mc","stem":"3 − ⟨1 2/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1 3/5⟩","correct":true},{"t":"⟨2 2/5⟩","mis":"M5-1-u5-X10"},{"t":"⟨1 2/5⟩","mis":"M5-1-u5-X09"},{"t":"⟨2 3/5⟩","mis":"M5-1-u5-X10"}],"explanation":["3에서 1을 빌려 3 = ⟨2 5/5⟩로 바꾸어요 — 1은 ⟨5/5⟩예요.","⟨2 5/5⟩ − ⟨1 2/5⟩ = ⟨1 3/5⟩이에요.","그래서 3 − ⟨1 2/5⟩ = ⟨1 3/5⟩이에요."],"variant_rule":{"alt":[{"stem":"4 − ⟨2 3/8⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 5/8⟩","correct":true},{"t":"⟨2 3/8⟩","mis":"M5-1-u5-X10"},{"t":"⟨1 3/8⟩","mis":"M5-1-u5-X09"},{"t":"⟨2 5/8⟩","mis":"M5-1-u5-X10"}],"explanation":["4에서 1을 빌려 4 = ⟨3 8/8⟩로 바꾸어요 — 1은 ⟨8/8⟩이에요.","⟨3 8/8⟩ − ⟨2 3/8⟩ = ⟨1 5/8⟩예요.","그래서 4 − ⟨2 3/8⟩ = ⟨1 5/8⟩예요."]},{"stem":"5 − ⟨1 5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨3 1/6⟩","correct":true},{"t":"⟨4 5/6⟩","mis":"M5-1-u5-X10"},{"t":"⟨3 5/6⟩","mis":"M5-1-u5-X09"},{"t":"⟨4 1/6⟩","mis":"M5-1-u5-X10"}],"explanation":["5에서 1을 빌려 5 = ⟨4 6/6⟩으로 바꾸어요 — 1은 ⟨6/6⟩이에요.","⟨4 6/6⟩ − ⟨1 5/6⟩ = ⟨3 1/6⟩이에요.","그래서 5 − ⟨1 5/6⟩ = ⟨3 1/6⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L07_basic#8','math',5,1,'u5','L07','g5_1_math_u5_L07_basic','lesson_basic','M5-1-u5-C7',2,'ox','auto','⟨4 1/3⟩은 ⟨3 4/3⟩와 크기가 같아요.',ARRAY['M5-1-u5-X10']::text[],true,'{"seq":8,"concept":"M5-1-u5-C7","difficulty":2,"kind":"ox","stem":"⟨4 1/3⟩은 ⟨3 4/3⟩와 크기가 같아요.","answer":"O","reason_options":[{"t":"자연수 4에서 1을 빌려 ⟨3/3⟩으로 바꾸어 분자에 더한 것이므로","correct":true},{"t":"자연수가 4에서 3으로 줄어 더 작은 수이므로","mis":"M5-1-u5-X10"}],"mis":"M5-1-u5-X10","explanation":["⟨4 1/3⟩ = 3 + 1 + ⟨1/3⟩이에요.","빌린 1 = ⟨3/3⟩ — ⟨3/3⟩ + ⟨1/3⟩ = ⟨4/3⟩예요.","그래서 ⟨4 1/3⟩ = ⟨3 4/3⟩예요."],"variant_rule":{"alt":[{"stem":"⟨3 1/4⟩에서 1을 빌려 오면 ⟨2 11/4⟩이 돼요.","answer":"X","reason_options":[{"t":"1 = ⟨4/4⟩라 분자에 4를 더해 ⟨2 5/4⟩가 되므로","correct":true},{"t":"1을 빌리면 분자에 10을 더하므로","mis":"M5-1-u5-X10"}],"explanation":["빌린 1은 ⟨4/4⟩예요.","⟨1/4⟩ + ⟨4/4⟩ = ⟨5/4⟩예요.","⟨3 1/4⟩ = ⟨2 5/4⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L07_basic#9','math',5,1,'u5','L07','g5_1_math_u5_L07_basic','lesson_basic','M5-1-u5-C7',2,'error','auto','⟨3 1/4⟩ − ⟨1 2/3⟩를 다음과 같이 계산했어요. 잘못된 곳은 어디인가요?  ⟨3 3/12⟩ − ⟨1 8/12⟩ = ⟨2 5/12⟩',ARRAY['M5-1-u5-X09','M5-1-u5-X14']::text[],true,'{"seq":9,"concept":"M5-1-u5-C7","difficulty":2,"kind":"error","stem":"⟨3 1/4⟩ − ⟨1 2/3⟩를 다음과 같이 계산했어요. 잘못된 곳은 어디인가요?  ⟨3 3/12⟩ − ⟨1 8/12⟩ = ⟨2 5/12⟩","options":[{"t":"분자끼리 3 − 8을 거꾸로 8 − 3으로 뺀 것","correct":true,"mis_target":"M5-1-u5-X09"},{"t":"12로 통분한 것","mis":"M5-1-u5-X14"},{"t":"자연수끼리 3 − 1을 한 것","mis":"M5-1-u5-X14"},{"t":"분모 12를 그대로 둔 것","mis":"M5-1-u5-X14"}],"explanation":["분수 부분을 12로 통분하면 ⟨3 3/12⟩ − ⟨1 8/12⟩이에요.","분자 3에서 8을 뺄 수 없어 자연수에서 1을 빌리면 ⟨3 3/12⟩ = ⟨2 15/12⟩예요.","⟨2 15/12⟩ − ⟨1 8/12⟩ = ⟨1 7/12⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨5 1/6⟩ − ⟨2 3/4⟩을 다음과 같이 계산했어요. 잘못된 곳은 어디인가요?  ⟨5 2/12⟩ − ⟨2 9/12⟩ = ⟨3 7/12⟩","options":[{"t":"분자끼리 2 − 9를 거꾸로 9 − 2로 뺀 것","correct":true,"mis_target":"M5-1-u5-X09"},{"t":"12로 통분한 것","mis":"M5-1-u5-X14"},{"t":"자연수끼리 5 − 2를 한 것","mis":"M5-1-u5-X14"},{"t":"분모 12를 그대로 둔 것","mis":"M5-1-u5-X14"}],"explanation":["분수 부분을 12로 통분하면 ⟨5 2/12⟩ − ⟨2 9/12⟩예요.","분자 2에서 9를 뺄 수 없어 자연수에서 1을 빌리면 ⟨5 2/12⟩ = ⟨4 14/12⟩예요.","⟨4 14/12⟩ − ⟨2 9/12⟩ = ⟨2 5/12⟩예요."]},{"stem":"⟨4 1/3⟩ − ⟨1 3/4⟩을 다음과 같이 계산했어요. 잘못된 곳은 어디인가요?  ⟨4 4/12⟩ − ⟨1 9/12⟩ = ⟨3 5/12⟩","options":[{"t":"분자끼리 4 − 9를 거꾸로 9 − 4로 뺀 것","correct":true,"mis_target":"M5-1-u5-X09"},{"t":"12로 통분한 것","mis":"M5-1-u5-X14"},{"t":"자연수끼리 4 − 1을 한 것","mis":"M5-1-u5-X14"},{"t":"분모 12를 그대로 둔 것","mis":"M5-1-u5-X14"}],"explanation":["분수 부분을 12로 통분하면 ⟨4 4/12⟩ − ⟨1 9/12⟩예요.","분자 4에서 9를 뺄 수 없어 자연수에서 1을 빌리면 ⟨4 4/12⟩ = ⟨3 16/12⟩이에요.","⟨3 16/12⟩ − ⟨1 9/12⟩ = ⟨2 7/12⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L07_basic#10','math',5,1,'u5','L07','g5_1_math_u5_L07_basic','lesson_basic','M5-1-u5-C7',3,'mc','auto','철사 ⟨5 1/6⟩ m에서 ⟨2 3/4⟩ m를 잘라 썼어요. 남은 철사는 몇 m인가요?',ARRAY['M5-1-u5-X09','M5-1-u5-X10']::text[],true,'{"seq":10,"concept":"M5-1-u5-C7","difficulty":3,"kind":"mc","stem":"철사 ⟨5 1/6⟩ m에서 ⟨2 3/4⟩ m를 잘라 썼어요. 남은 철사는 몇 m인가요?","options":[{"t":"⟨2 5/12⟩","correct":true},{"t":"⟨3 7/12⟩","mis":"M5-1-u5-X09"},{"t":"⟨3 5/12⟩","mis":"M5-1-u5-X10"},{"t":"⟨2 1/4⟩","mis":"M5-1-u5-X10"}],"explanation":["분수 부분을 12로 통분하면 ⟨5 2/12⟩ − ⟨2 9/12⟩예요.","분자 2에서 9를 뺄 수 없어 자연수에서 1을 빌리면 ⟨5 2/12⟩ = ⟨4 14/12⟩예요.","⟨4 14/12⟩ − ⟨2 9/12⟩ = ⟨2 5/12⟩예요."],"variant_rule":{"alt":[{"stem":"리본 ⟨4 1/3⟩ m에서 ⟨1 5/6⟩ m를 잘라 썼어요. 남은 리본은 몇 m인가요?","options":[{"t":"⟨2 1/2⟩","correct":true},{"t":"⟨3 1/2⟩","mis":"M5-1-u5-X09"},{"t":"⟨3 1/6⟩","mis":"M5-1-u5-X10"},{"t":"⟨2 2/3⟩","mis":"M5-1-u5-X13"}],"explanation":["분수 부분을 6으로 통분하면 ⟨4 2/6⟩ − ⟨1 5/6⟩예요.","분자 2에서 5를 뺄 수 없어 자연수에서 1을 빌리면 ⟨4 2/6⟩ = ⟨3 8/6⟩이에요.","⟨3 8/6⟩ − ⟨1 5/6⟩ = ⟨2 3/6⟩ = ⟨2 1/2⟩이에요."]},{"stem":"끈 ⟨6 1/5⟩ m에서 ⟨3 1/2⟩ m를 잘라 썼어요. 남은 끈은 몇 m인가요?","options":[{"t":"⟨2 7/10⟩","correct":true},{"t":"⟨3 3/10⟩","mis":"M5-1-u5-X09"},{"t":"⟨3 7/10⟩","mis":"M5-1-u5-X10"},{"t":"3","mis":"M5-1-u5-X02"}],"explanation":["분수 부분을 10으로 통분하면 ⟨6 2/10⟩ − ⟨3 5/10⟩예요.","분자 2에서 5를 뺄 수 없어 자연수에서 1을 빌리면 ⟨6 2/10⟩ = ⟨5 12/10⟩예요.","⟨5 12/10⟩ − ⟨3 5/10⟩ = ⟨2 7/10⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L07_challenge#1','math',5,1,'u5','L07','g5_1_math_u5_L07_challenge','lesson_challenge','M5-1-u5-C7',2,'error','auto','⟨3 1/4⟩ − ⟨1 2/3⟩를 다음과 같이 계산했어요. 잘못된 곳은 어디인가요?  ⟨3 1/4⟩ − ⟨1 2/3⟩ = ⟨2 13/12⟩ − ⟨1 8/12⟩ = ⟨1 5/12⟩',ARRAY['M5-1-u5-X10','M5-1-u5-X14']::text[],true,'{"seq":1,"concept":"M5-1-u5-C7","difficulty":2,"kind":"error","stem":"⟨3 1/4⟩ − ⟨1 2/3⟩를 다음과 같이 계산했어요. 잘못된 곳은 어디인가요?  ⟨3 1/4⟩ − ⟨1 2/3⟩ = ⟨2 13/12⟩ − ⟨1 8/12⟩ = ⟨1 5/12⟩","options":[{"t":"1을 빌려 오면서 분자에 10을 더한 것","correct":true,"mis_target":"M5-1-u5-X10"},{"t":"통분해 ⟨3 3/12⟩으로 바꾼 것","mis":"M5-1-u5-X14"},{"t":"자연수에서 1을 뺀 것","mis":"M5-1-u5-X14"},{"t":"자연수끼리 2 − 1을 한 것","mis":"M5-1-u5-X14"}],"explanation":["분수 부분을 12로 통분하면 ⟨3 3/12⟩ − ⟨1 8/12⟩이에요.","분자 3에서 8을 뺄 수 없어 자연수에서 1을 빌리면 ⟨3 3/12⟩ = ⟨2 15/12⟩예요.","⟨2 15/12⟩ − ⟨1 8/12⟩ = ⟨1 7/12⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨4 1/6⟩ − ⟨2 3/4⟩을 다음과 같이 계산했어요. 잘못된 곳은 어디인가요?  ⟨4 1/6⟩ − ⟨2 3/4⟩ = ⟨3 12/12⟩ − ⟨2 9/12⟩ = ⟨1 1/4⟩","options":[{"t":"1을 빌려 오면서 분자에 10을 더한 것","correct":true,"mis_target":"M5-1-u5-X10"},{"t":"통분해 ⟨4 2/12⟩로 바꾼 것","mis":"M5-1-u5-X14"},{"t":"자연수에서 1을 뺀 것","mis":"M5-1-u5-X14"},{"t":"자연수끼리 3 − 2를 한 것","mis":"M5-1-u5-X14"}],"explanation":["분수 부분을 12로 통분하면 ⟨4 2/12⟩ − ⟨2 9/12⟩예요.","분자 2에서 9를 뺄 수 없어 자연수에서 1을 빌리면 ⟨4 2/12⟩ = ⟨3 14/12⟩예요.","⟨3 14/12⟩ − ⟨2 9/12⟩ = ⟨1 5/12⟩예요."]},{"stem":"⟨5 1/3⟩ − ⟨2 4/5⟩를 다음과 같이 계산했어요. 잘못된 곳은 어디인가요?  ⟨5 1/3⟩ − ⟨2 4/5⟩ = ⟨4 15/15⟩ − ⟨2 12/15⟩ = ⟨2 1/5⟩","options":[{"t":"1을 빌려 오면서 분자에 10을 더한 것","correct":true,"mis_target":"M5-1-u5-X10"},{"t":"통분해 ⟨5 5/15⟩로 바꾼 것","mis":"M5-1-u5-X14"},{"t":"자연수에서 1을 뺀 것","mis":"M5-1-u5-X14"},{"t":"자연수끼리 4 − 2를 한 것","mis":"M5-1-u5-X14"}],"explanation":["분수 부분을 15로 통분하면 ⟨5 5/15⟩ − ⟨2 12/15⟩예요.","분자 5에서 12를 뺄 수 없어 자연수에서 1을 빌리면 ⟨5 5/15⟩ = ⟨4 20/15⟩이에요.","⟨4 20/15⟩ − ⟨2 12/15⟩ = ⟨2 8/15⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L07_challenge#2','math',5,1,'u5','L07','g5_1_math_u5_L07_challenge','lesson_challenge','M5-1-u5-C7',2,'sa','auto','⟨6 1/4⟩을 분모 12로 통분한 뒤 자연수에서 1을 빌려 ⟨5 □/12⟩로 나타내면 □는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u5-C7","difficulty":2,"kind":"sa","stem":"⟨6 1/4⟩을 분모 12로 통분한 뒤 자연수에서 1을 빌려 ⟨5 □/12⟩로 나타내면 □는 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["⟨6 1/4⟩ = ⟨6 3/12⟩이에요.","빌려 온 1은 ⟨12/12⟩ — 분자에 12를 더해요.","⟨6 3/12⟩ = ⟨5 15/12⟩ — □는 3 + 12 = 15예요."],"variant_rule":{"alt":[{"stem":"⟨3 2/5⟩를 분모 10으로 통분한 뒤 자연수에서 1을 빌려 ⟨2 □/10⟩로 나타내면 □는 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["⟨3 2/5⟩ = ⟨3 4/10⟩예요.","빌려 온 1은 ⟨10/10⟩ — 분자에 10을 더해요.","⟨3 4/10⟩ = ⟨2 14/10⟩ — □는 4 + 10 = 14예요."]},{"stem":"⟨5 1/6⟩을 분모 18로 통분한 뒤 자연수에서 1을 빌려 ⟨4 □/18⟩로 나타내면 □는 얼마인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["⟨5 1/6⟩ = ⟨5 3/18⟩이에요.","빌려 온 1은 ⟨18/18⟩ — 분자에 18을 더해요.","⟨5 3/18⟩ = ⟨4 21/18⟩ — □는 3 + 18 = 21이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L07_challenge#3','math',5,1,'u5','L07','g5_1_math_u5_L07_challenge','lesson_challenge','M5-1-u5-C7',3,'mc','auto','⟨6 1/4⟩ − ⟨3 5/6⟩를 계산하면 얼마인가요?',ARRAY['M5-1-u5-X09','M5-1-u5-X10']::text[],true,'{"seq":3,"concept":"M5-1-u5-C7","difficulty":3,"kind":"mc","stem":"⟨6 1/4⟩ − ⟨3 5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨2 5/12⟩","correct":true},{"t":"⟨3 7/12⟩","mis":"M5-1-u5-X09"},{"t":"⟨3 5/12⟩","mis":"M5-1-u5-X10"},{"t":"⟨2 1/4⟩","mis":"M5-1-u5-X10"}],"explanation":["분수 부분을 12로 통분하면 ⟨6 3/12⟩ − ⟨3 10/12⟩이에요.","분자 3에서 10을 뺄 수 없어 자연수에서 1을 빌리면 ⟨6 3/12⟩ = ⟨5 15/12⟩예요.","⟨5 15/12⟩ − ⟨3 10/12⟩ = ⟨2 5/12⟩예요."],"variant_rule":{"alt":[{"stem":"⟨7 1/3⟩ − ⟨2 7/9⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 5/9⟩","correct":true},{"t":"⟨5 4/9⟩","mis":"M5-1-u5-X09"},{"t":"⟨5 5/9⟩","mis":"M5-1-u5-X10"},{"t":"⟨4 2/3⟩","mis":"M5-1-u5-X10"}],"explanation":["분수 부분을 9로 통분하면 ⟨7 3/9⟩ − ⟨2 7/9⟩이에요.","분자 3에서 7을 뺄 수 없어 자연수에서 1을 빌리면 ⟨7 3/9⟩ = ⟨6 12/9⟩예요.","⟨6 12/9⟩ − ⟨2 7/9⟩ = ⟨4 5/9⟩예요."]},{"stem":"⟨5 3/10⟩ − ⟨1 3/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3 11/20⟩","correct":true},{"t":"⟨4 9/20⟩","mis":"M5-1-u5-X09"},{"t":"⟨4 11/20⟩","mis":"M5-1-u5-X10"},{"t":"⟨3 1/20⟩","mis":"M5-1-u5-X10"}],"explanation":["분수 부분을 20으로 통분하면 ⟨5 6/20⟩ − ⟨1 15/20⟩예요.","분자 6에서 15를 뺄 수 없어 자연수에서 1을 빌리면 ⟨5 6/20⟩ = ⟨4 26/20⟩이에요.","⟨4 26/20⟩ − ⟨1 15/20⟩ = ⟨3 11/20⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L07_challenge#4','math',5,1,'u5','L07','g5_1_math_u5_L07_challenge','lesson_challenge','M5-1-u5-C7',3,'mc','auto','끈 ⟨3 1/2⟩ m에서 ⟨1 3/4⟩ m를 잘라 썼어요. 남은 끈은 몇 m인가요?',ARRAY['M5-1-u5-X09','M5-1-u5-X10']::text[],true,'{"seq":4,"concept":"M5-1-u5-C7","difficulty":3,"kind":"mc","stem":"끈 ⟨3 1/2⟩ m에서 ⟨1 3/4⟩ m를 잘라 썼어요. 남은 끈은 몇 m인가요?","options":[{"t":"⟨1 3/4⟩","correct":true},{"t":"⟨2 1/4⟩","mis":"M5-1-u5-X09"},{"t":"⟨2 3/4⟩","mis":"M5-1-u5-X10"},{"t":"⟨3 1/4⟩","mis":"M5-1-u5-X10"}],"explanation":["분수 부분을 4로 통분하면 ⟨3 2/4⟩ − ⟨1 3/4⟩이에요.","분자 2에서 3을 뺄 수 없어 자연수에서 1을 빌리면 ⟨3 2/4⟩ = ⟨2 6/4⟩이에요.","⟨2 6/4⟩ − ⟨1 3/4⟩ = ⟨1 3/4⟩이에요."],"variant_rule":{"alt":[{"stem":"물 ⟨4 1/3⟩ L 중에서 ⟨2 1/2⟩ L를 마셨어요. 남은 물은 몇 L인가요?","options":[{"t":"⟨1 5/6⟩","correct":true},{"t":"⟨2 1/6⟩","mis":"M5-1-u5-X09"},{"t":"⟨2 5/6⟩","mis":"M5-1-u5-X10"},{"t":"⟨2 1/2⟩","mis":"M5-1-u5-X10"}],"explanation":["분수 부분을 6으로 통분하면 ⟨4 2/6⟩ − ⟨2 3/6⟩이에요.","분자 2에서 3을 뺄 수 없어 자연수에서 1을 빌리면 ⟨4 2/6⟩ = ⟨3 8/6⟩이에요.","⟨3 8/6⟩ − ⟨2 3/6⟩ = ⟨1 5/6⟩예요."]},{"stem":"모래 ⟨5 1/4⟩ kg 중에서 ⟨3 5/8⟩ kg을 썼어요. 남은 모래는 몇 kg인가요?","options":[{"t":"⟨1 5/8⟩","correct":true},{"t":"⟨2 3/8⟩","mis":"M5-1-u5-X09"},{"t":"⟨2 5/8⟩","mis":"M5-1-u5-X10"},{"t":"⟨1 7/8⟩","mis":"M5-1-u5-X10"}],"explanation":["분수 부분을 8로 통분하면 ⟨5 2/8⟩ − ⟨3 5/8⟩예요.","분자 2에서 5를 뺄 수 없어 자연수에서 1을 빌리면 ⟨5 2/8⟩ = ⟨4 10/8⟩이에요.","⟨4 10/8⟩ − ⟨3 5/8⟩ = ⟨1 5/8⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L07_challenge#5','math',5,1,'u5','L07','g5_1_math_u5_L07_challenge','lesson_challenge','M5-1-u5-C7',3,'sa','auto','⟨4 1/6⟩ − ⟨1 2/3⟩를 가분수로 바꾸어 분모 6으로 계산하면 ⟨□/6⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-1-u5-C7","difficulty":3,"kind":"sa","stem":"⟨4 1/6⟩ − ⟨1 2/3⟩를 가분수로 바꾸어 분모 6으로 계산하면 ⟨□/6⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["⟨4 1/6⟩ = ⟨25/6⟩, ⟨1 2/3⟩ = ⟨10/6⟩이에요.","분자끼리 25 − 10 = 15예요.","⟨15/6⟩ = ⟨2 1/2⟩ — □는 15예요."],"variant_rule":{"alt":[{"stem":"⟨3 1/4⟩ − ⟨1 5/8⟩를 가분수로 바꾸어 분모 8로 계산하면 ⟨□/8⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["⟨3 1/4⟩ = ⟨26/8⟩, ⟨1 5/8⟩ = ⟨13/8⟩이에요.","분자끼리 26 − 13 = 13이에요.","⟨13/8⟩ = ⟨1 5/8⟩ — □는 13이에요."]},{"stem":"⟨5 1/5⟩ − ⟨2 1/2⟩을 가분수로 바꾸어 분모 10으로 계산하면 ⟨□/10⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["⟨5 1/5⟩ = ⟨52/10⟩, ⟨2 1/2⟩ = ⟨25/10⟩예요.","분자끼리 52 − 25 = 27이에요.","⟨27/10⟩ = ⟨2 7/10⟩ — □는 27이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L07_challenge#6','math',5,1,'u5','L07','g5_1_math_u5_L07_challenge','lesson_challenge','M5-1-u5-C7',3,'mc','auto','5 − ⟨2 3/8⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X10','M5-1-u5-X09']::text[],true,'{"seq":6,"concept":"M5-1-u5-C7","difficulty":3,"kind":"mc","stem":"5 − ⟨2 3/8⟩을 계산하면 얼마인가요?","options":[{"t":"⟨2 5/8⟩","correct":true},{"t":"⟨3 3/8⟩","mis":"M5-1-u5-X10"},{"t":"⟨2 3/8⟩","mis":"M5-1-u5-X09"},{"t":"⟨3 5/8⟩","mis":"M5-1-u5-X10"}],"explanation":["5에서 1을 빌려 5 = ⟨4 8/8⟩로 바꾸어요 — 1은 ⟨8/8⟩이에요.","⟨4 8/8⟩ − ⟨2 3/8⟩ = ⟨2 5/8⟩예요.","그래서 5 − ⟨2 3/8⟩ = ⟨2 5/8⟩예요."],"variant_rule":{"alt":[{"stem":"4 − ⟨1 5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨2 1/6⟩","correct":true},{"t":"⟨3 5/6⟩","mis":"M5-1-u5-X10"},{"t":"⟨2 5/6⟩","mis":"M5-1-u5-X09"},{"t":"⟨3 1/6⟩","mis":"M5-1-u5-X10"}],"explanation":["4에서 1을 빌려 4 = ⟨3 6/6⟩으로 바꾸어요 — 1은 ⟨6/6⟩이에요.","⟨3 6/6⟩ − ⟨1 5/6⟩ = ⟨2 1/6⟩이에요.","그래서 4 − ⟨1 5/6⟩ = ⟨2 1/6⟩이에요."]},{"stem":"6 − ⟨3 4/9⟩를 계산하면 얼마인가요?","options":[{"t":"⟨2 5/9⟩","correct":true},{"t":"⟨3 4/9⟩","mis":"M5-1-u5-X10"},{"t":"⟨2 4/9⟩","mis":"M5-1-u5-X09"},{"t":"⟨3 5/9⟩","mis":"M5-1-u5-X10"}],"explanation":["6에서 1을 빌려 6 = ⟨5 9/9⟩로 바꾸어요 — 1은 ⟨9/9⟩예요.","⟨5 9/9⟩ − ⟨3 4/9⟩ = ⟨2 5/9⟩예요.","그래서 6 − ⟨3 4/9⟩ = ⟨2 5/9⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L07_challenge#7','math',5,1,'u5','L07','g5_1_math_u5_L07_challenge','lesson_challenge','M5-1-u5-C7',3,'ox','auto','1을 빌려 오는 뺄셈에서는 빼어지는 수의 자연수 부분이 1 작아지고, 분수 부분의 분자는 분모만큼 커져요.',ARRAY['M5-1-u5-X10']::text[],true,'{"seq":7,"concept":"M5-1-u5-C7","difficulty":3,"kind":"ox","stem":"1을 빌려 오는 뺄셈에서는 빼어지는 수의 자연수 부분이 1 작아지고, 분수 부분의 분자는 분모만큼 커져요.","answer":"O","reason_options":[{"t":"빌려 온 1을 분모만큼의 조각으로 바꾸어 분자에 더하므로","correct":true},{"t":"빌려 온 1은 분자에 1만 더하므로","mis":"M5-1-u5-X10"}],"mis":"M5-1-u5-X10","explanation":["⟨3 3/12⟩에서 1을 빌리면 자연수는 3 → 2예요.","빌린 1 = ⟨12/12⟩ — 분자는 3 + 12 = 15예요.","⟨3 3/12⟩ = ⟨2 15/12⟩예요."],"variant_rule":{"alt":[{"stem":"⟨5 1/6⟩ − ⟨2 5/6⟩는 분수 부분을 ⟨5/6⟩ − ⟨1/6⟩로 바꾸어 빼면 돼요.","answer":"X","reason_options":[{"t":"빼는 차례를 바꿀 수 없어 1을 빌려 ⟨7/6⟩ − ⟨5/6⟩로 빼야 하므로","correct":true},{"t":"큰 분자에서 작은 분자를 빼면 되므로","mis":"M5-1-u5-X09"}],"explanation":["⟨1/6⟩에서 ⟨5/6⟩를 뺄 수 없어요.","1을 빌리면 ⟨5 1/6⟩ = ⟨4 7/6⟩이에요.","⟨4 7/6⟩ − ⟨2 5/6⟩ = ⟨2 2/6⟩ = ⟨2 1/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L07_challenge#8','math',5,1,'u5','L07','g5_1_math_u5_L07_challenge','lesson_challenge','M5-1-u5-C7',4,'sa','auto','⟨5 1/4⟩에서 분수 부분이 ⟨3/4⟩인 대분수를 뺐더니 ⟨2 1/2⟩이 되었어요. 뺀 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u5-C7","difficulty":4,"kind":"sa","stem":"⟨5 1/4⟩에서 분수 부분이 ⟨3/4⟩인 대분수를 뺐더니 ⟨2 1/2⟩이 되었어요. 뺀 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["뺀 대분수는 ⟨5 1/4⟩ − ⟨2 1/2⟩로 구해요.","⟨5 1/4⟩ − ⟨2 1/2⟩ = ⟨2 3/4⟩이에요 — 분수 부분에서 1을 빌려 와요.","⟨2 3/4⟩의 자연수 부분은 2예요."],"variant_rule":{"alt":[{"stem":"⟨6 1/3⟩에서 분수 부분이 ⟨5/6⟩인 대분수를 뺐더니 ⟨3 1/2⟩이 되었어요. 뺀 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["뺀 대분수는 ⟨6 1/3⟩ − ⟨3 1/2⟩로 구해요.","⟨6 1/3⟩ − ⟨3 1/2⟩ = ⟨2 5/6⟩예요 — 분수 부분에서 1을 빌려 와요.","⟨2 5/6⟩의 자연수 부분은 2예요."]},{"stem":"⟨4 1/5⟩에서 분수 부분이 ⟨7/10⟩인 대분수를 뺐더니 ⟨1 1/2⟩이 되었어요. 뺀 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["뺀 대분수는 ⟨4 1/5⟩ − ⟨1 1/2⟩로 구해요.","⟨4 1/5⟩ − ⟨1 1/2⟩ = ⟨2 7/10⟩이에요 — 분수 부분에서 1을 빌려 와요.","⟨2 7/10⟩의 자연수 부분은 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L07_challenge#9','math',5,1,'u5','L07','g5_1_math_u5_L07_challenge','lesson_challenge','M5-1-u5-C7',4,'mc','auto','⟨4 1/5⟩ − □의 계산 결과가 0보다 크고 1보다 작을 때 □에 들어갈 수 있는 수는 어느 것인가요?',ARRAY['M5-1-u5-X12']::text[],true,'{"seq":9,"concept":"M5-1-u5-C7","difficulty":4,"kind":"mc","stem":"⟨4 1/5⟩ − □의 계산 결과가 0보다 크고 1보다 작을 때 □에 들어갈 수 있는 수는 어느 것인가요?","options":[{"t":"⟨3 1/2⟩","correct":true},{"t":"⟨2 4/5⟩","mis":"M5-1-u5-X12"},{"t":"⟨3 1/10⟩","mis":"M5-1-u5-X12"},{"t":"⟨4 1/2⟩","mis":"M5-1-u5-X12"}],"explanation":["□는 ⟨4 1/5⟩ − 1 = ⟨3 1/5⟩보다 크고 ⟨4 1/5⟩보다 작아야 해요.","⟨4 1/5⟩ − ⟨3 1/2⟩ = ⟨7/10⟩, ⟨4 1/5⟩ − ⟨2 4/5⟩ = ⟨1 2/5⟩, ⟨4 1/5⟩ − ⟨3 1/10⟩ = ⟨1 1/10⟩ — 이 가운데 그 사이에 드는 수는 ⟨3 1/2⟩ 하나예요.","그래서 답은 ⟨3 1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨3 1/6⟩ − □의 계산 결과가 0보다 크고 1보다 작을 때 □에 들어갈 수 있는 수는 어느 것인가요?","options":[{"t":"⟨2 1/3⟩","correct":true},{"t":"⟨1 5/6⟩","mis":"M5-1-u5-X12"},{"t":"⟨2 1/12⟩","mis":"M5-1-u5-X12"},{"t":"⟨3 1/2⟩","mis":"M5-1-u5-X12"}],"explanation":["□는 ⟨3 1/6⟩ − 1 = ⟨2 1/6⟩보다 크고 ⟨3 1/6⟩보다 작아야 해요.","⟨3 1/6⟩ − ⟨2 1/3⟩ = ⟨5/6⟩, ⟨3 1/6⟩ − ⟨1 5/6⟩ = ⟨1 1/3⟩, ⟨3 1/6⟩ − ⟨2 1/12⟩ = ⟨1 1/12⟩ — 이 가운데 그 사이에 드는 수는 ⟨2 1/3⟩ 하나예요.","그래서 답은 ⟨2 1/3⟩이에요."]},{"stem":"⟨5 1/4⟩ − □의 계산 결과가 0보다 크고 1보다 작을 때 □에 들어갈 수 있는 수는 어느 것인가요?","options":[{"t":"⟨4 1/2⟩","correct":true},{"t":"⟨3 3/4⟩","mis":"M5-1-u5-X12"},{"t":"⟨4 1/8⟩","mis":"M5-1-u5-X12"},{"t":"⟨5 1/2⟩","mis":"M5-1-u5-X12"}],"explanation":["□는 ⟨5 1/4⟩ − 1 = ⟨4 1/4⟩보다 크고 ⟨5 1/4⟩보다 작아야 해요.","⟨5 1/4⟩ − ⟨4 1/2⟩ = ⟨3/4⟩, ⟨5 1/4⟩ − ⟨3 3/4⟩ = ⟨1 1/2⟩, ⟨5 1/4⟩ − ⟨4 1/8⟩ = ⟨1 1/8⟩ — 이 가운데 그 사이에 드는 수는 ⟨4 1/2⟩ 하나예요.","그래서 답은 ⟨4 1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L07_challenge#10','math',5,1,'u5','L07','g5_1_math_u5_L07_challenge','lesson_challenge','M5-1-u5-C7',4,'essay','teacher','⟨3 1/4⟩ − ⟨1 2/3⟩를 계산할 때 왜 1을 빌려 와야 하는지, 빌려 온 1을 어떻게 바꾸는지 설명하고 답을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u5-C7","difficulty":4,"kind":"essay","stem":"⟨3 1/4⟩ − ⟨1 2/3⟩를 계산할 때 왜 1을 빌려 와야 하는지, 빌려 온 1을 어떻게 바꾸는지 설명하고 답을 쓰세요.","answer_guide":{"answer":"예: 12로 통분하면 ⟨3 3/12⟩ − ⟨1 8/12⟩인데 분자 3에서 8을 뺄 수 없다. 자연수 3에서 1을 빌려 ⟨12/12⟩로 바꾸면 ⟨3 3/12⟩ = ⟨2 15/12⟩가 된다. ⟨2 15/12⟩ − ⟨1 8/12⟩ = ⟨1 7/12⟩이다.","scoring_points":["분자 3에서 8을 뺄 수 없어서라고 썼는가","빌린 1을 ⟨12/12⟩로 바꾸어 ⟨2 15/12⟩를 만들었는가","답 ⟨1 7/12⟩을 바르게 구했는가"]},"explanation":["⟨3 3/12⟩ − ⟨1 8/12⟩ — 3에서 8을 뺄 수 없어요.","⟨3 3/12⟩ = ⟨2 15/12⟩로 바꾸어요.","⟨2 15/12⟩ − ⟨1 8/12⟩ = ⟨1 7/12⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L08_basic#1','math',5,1,'u5','L08','g5_1_math_u5_L08_basic','lesson_basic','M5-1-u5-C8',1,'mc','auto','공원 길은 ⟨1/2⟩ km와 ⟨1/3⟩ km를 이어 걸어요. 공원 길의 거리는 몇 km인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X02']::text[],true,'{"seq":1,"concept":"M5-1-u5-C8","difficulty":1,"kind":"mc","stem":"공원 길은 ⟨1/2⟩ km와 ⟨1/3⟩ km를 이어 걸어요. 공원 길의 거리는 몇 km인가요?","options":[{"t":"⟨5/6⟩","correct":true},{"t":"⟨2/5⟩","mis":"M5-1-u5-X01"},{"t":"⟨5/12⟩","mis":"M5-1-u5-X03"},{"t":"⟨1/3⟩","mis":"M5-1-u5-X02"}],"explanation":["공통분모 6으로 통분하면 ⟨3/6⟩ + ⟨2/6⟩예요.","분모는 그대로 두고 분자끼리 더하면 ⟨3/6⟩ + ⟨2/6⟩ = ⟨5/6⟩예요.","그래서 ⟨1/2⟩ + ⟨1/3⟩ = ⟨5/6⟩예요."],"variant_rule":{"alt":[{"stem":"시장 길은 ⟨2/5⟩ km와 ⟨1/4⟩ km를 이어 걸어요. 시장 길의 거리는 몇 km인가요?","options":[{"t":"⟨13/20⟩","correct":true},{"t":"⟨1/3⟩","mis":"M5-1-u5-X01"},{"t":"⟨13/40⟩","mis":"M5-1-u5-X03"},{"t":"⟨3/20⟩","mis":"M5-1-u5-X02"}],"explanation":["공통분모 20으로 통분하면 ⟨8/20⟩ + ⟨5/20⟩예요.","분모는 그대로 두고 분자끼리 더하면 ⟨8/20⟩ + ⟨5/20⟩ = ⟨13/20⟩이에요.","그래서 ⟨2/5⟩ + ⟨1/4⟩ = ⟨13/20⟩이에요."]},{"stem":"하천 길은 ⟨1/3⟩ km와 ⟨1/4⟩ km를 이어 걸어요. 하천 길의 거리는 몇 km인가요?","options":[{"t":"⟨7/12⟩","correct":true},{"t":"⟨2/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨7/24⟩","mis":"M5-1-u5-X03"},{"t":"⟨1/6⟩","mis":"M5-1-u5-X02"}],"explanation":["공통분모 12로 통분하면 ⟨4/12⟩ + ⟨3/12⟩이에요.","분모는 그대로 두고 분자끼리 더하면 ⟨4/12⟩ + ⟨3/12⟩ = ⟨7/12⟩이에요.","그래서 ⟨1/3⟩ + ⟨1/4⟩ = ⟨7/12⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L08_basic#2','math',5,1,'u5','L08','g5_1_math_u5_L08_basic','lesson_basic','M5-1-u5-C8',1,'sa','auto','하천 길은 ⟨1/3⟩ km와 ⟨1/4⟩ km를 이어 걸어요. 거리를 분모 12인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u5-C8","difficulty":1,"kind":"sa","stem":"하천 길은 ⟨1/3⟩ km와 ⟨1/4⟩ km를 이어 걸어요. 거리를 분모 12인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["12로 통분하면 ⟨4/12⟩ + ⟨3/12⟩이에요.","분자끼리 4 + 3 = 7이에요.","하천 길의 거리는 ⟨7/12⟩ km — 분자는 7이에요."],"variant_rule":{"alt":[{"stem":"공원 길은 ⟨1/2⟩ km와 ⟨1/3⟩ km를 이어 걸어요. 거리를 분모 6인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["6으로 통분하면 ⟨3/6⟩ + ⟨2/6⟩예요.","분자끼리 3 + 2 = 5예요.","공원 길의 거리는 ⟨5/6⟩ km — 분자는 5예요."]},{"stem":"시장 길은 ⟨2/5⟩ km와 ⟨1/4⟩ km를 이어 걸어요. 거리를 분모 20인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["20으로 통분하면 ⟨8/20⟩ + ⟨5/20⟩예요.","분자끼리 8 + 5 = 13이에요.","시장 길의 거리는 ⟨13/20⟩ km — 분자는 13이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L08_basic#3','math',5,1,'u5','L08','g5_1_math_u5_L08_basic','lesson_basic','M5-1-u5-C8',1,'mc','auto','⟨5/6⟩ km와 ⟨13/20⟩ km 중 더 짧은 거리는 어느 것인가요?',ARRAY['M5-1-u5-X12','M5-1-u5-X13','M5-1-u5-X04']::text[],true,'{"seq":3,"concept":"M5-1-u5-C8","difficulty":1,"kind":"mc","stem":"⟨5/6⟩ km와 ⟨13/20⟩ km 중 더 짧은 거리는 어느 것인가요?","options":[{"t":"⟨13/20⟩ km","correct":true},{"t":"⟨5/6⟩ km","mis":"M5-1-u5-X12"},{"t":"둘은 같다","mis":"M5-1-u5-X13"},{"t":"분모가 달라 비교할 수 없다","mis":"M5-1-u5-X04"}],"explanation":["60으로 통분하면 ⟨50/60⟩과 ⟨39/60⟩예요.","분자를 견주면 50 > 39예요.","더 짧은 거리는 ⟨13/20⟩ km예요."],"variant_rule":{"alt":[{"stem":"⟨7/12⟩ km와 ⟨5/8⟩ km 중 더 짧은 거리는 어느 것인가요?","options":[{"t":"⟨7/12⟩ km","correct":true},{"t":"⟨5/8⟩ km","mis":"M5-1-u5-X12"},{"t":"둘은 같다","mis":"M5-1-u5-X13"},{"t":"분모가 달라 비교할 수 없다","mis":"M5-1-u5-X04"}],"explanation":["24로 통분하면 ⟨14/24⟩와 ⟨15/24⟩예요.","분자를 견주면 14 < 15예요.","더 짧은 거리는 ⟨7/12⟩ km예요."]},{"stem":"⟨3/4⟩ km와 ⟨7/10⟩ km 중 더 짧은 거리는 어느 것인가요?","options":[{"t":"⟨7/10⟩ km","correct":true},{"t":"⟨3/4⟩ km","mis":"M5-1-u5-X12"},{"t":"둘은 같다","mis":"M5-1-u5-X13"},{"t":"분모가 달라 비교할 수 없다","mis":"M5-1-u5-X04"}],"explanation":["20으로 통분하면 ⟨15/20⟩와 ⟨14/20⟩예요.","분자를 견주면 15 > 14예요.","더 짧은 거리는 ⟨7/10⟩ km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L08_basic#4','math',5,1,'u5','L08','g5_1_math_u5_L08_basic','lesson_basic','M5-1-u5-C8',1,'sa','auto','⟨5/6⟩ km와 ⟨1/3⟩ km의 차를 분모 6인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u5-C8","difficulty":1,"kind":"sa","stem":"⟨5/6⟩ km와 ⟨1/3⟩ km의 차를 분모 6인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["6으로 통분하면 ⟨5/6⟩ − ⟨2/6⟩예요.","분자끼리 5 − 2 = 3이에요.","차는 ⟨3/6⟩ km — 분자는 3이에요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩ km와 ⟨1/2⟩ km의 차를 분모 4인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["4로 통분하면 ⟨3/4⟩ − ⟨2/4⟩예요.","분자끼리 3 − 2 = 1이에요.","차는 ⟨1/4⟩ km — 분자는 1이에요."]},{"stem":"⟨7/10⟩ km와 ⟨1/5⟩ km의 차를 분모 10인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["10으로 통분하면 ⟨7/10⟩ − ⟨2/10⟩예요.","분자끼리 7 − 2 = 5예요.","차는 ⟨5/10⟩ km — 분자는 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L08_basic#5','math',5,1,'u5','L08','g5_1_math_u5_L08_basic','lesson_basic','M5-1-u5-C8',2,'mc','auto','세 길의 거리가 ⟨5/6⟩, ⟨13/20⟩, ⟨7/12⟩ km예요. 가장 짧은 길의 거리는 어느 것인가요?',ARRAY['M5-1-u5-X12','M5-1-u5-X04']::text[],true,'{"seq":5,"concept":"M5-1-u5-C8","difficulty":2,"kind":"mc","stem":"세 길의 거리가 ⟨5/6⟩, ⟨13/20⟩, ⟨7/12⟩ km예요. 가장 짧은 길의 거리는 어느 것인가요?","options":[{"t":"⟨7/12⟩ km","correct":true},{"t":"⟨5/6⟩ km","mis":"M5-1-u5-X12"},{"t":"⟨13/20⟩ km","mis":"M5-1-u5-X12"},{"t":"셋 다 같다","mis":"M5-1-u5-X04"}],"explanation":["60으로 통분하면 ⟨50/60⟩, ⟨39/60⟩, ⟨35/60⟩예요.","분자를 견주면 가장 작은 것은 35예요.","그래서 가장 짧은 길은 ⟨7/12⟩ km예요."],"variant_rule":{"alt":[{"stem":"세 길의 거리가 ⟨3/4⟩, ⟨2/3⟩, ⟨7/10⟩ km예요. 가장 짧은 길의 거리는 어느 것인가요?","options":[{"t":"⟨2/3⟩ km","correct":true},{"t":"⟨3/4⟩ km","mis":"M5-1-u5-X12"},{"t":"⟨7/10⟩ km","mis":"M5-1-u5-X12"},{"t":"셋 다 같다","mis":"M5-1-u5-X04"}],"explanation":["60으로 통분하면 ⟨45/60⟩, ⟨40/60⟩, ⟨42/60⟩예요.","분자를 견주면 가장 작은 것은 40이에요.","그래서 가장 짧은 길은 ⟨2/3⟩ km예요."]},{"stem":"세 길의 거리가 ⟨5/8⟩, ⟨7/12⟩, ⟨2/3⟩ km예요. 가장 긴 길의 거리는 어느 것인가요?","options":[{"t":"⟨2/3⟩ km","correct":true},{"t":"⟨5/8⟩ km","mis":"M5-1-u5-X12"},{"t":"⟨7/12⟩ km","mis":"M5-1-u5-X12"},{"t":"셋 다 같다","mis":"M5-1-u5-X04"}],"explanation":["24로 통분하면 ⟨15/24⟩, ⟨14/24⟩, ⟨16/24⟩이에요.","분자를 견주면 가장 큰 것은 16이에요.","그래서 가장 긴 길은 ⟨2/3⟩ km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L08_basic#6','math',5,1,'u5','L08','g5_1_math_u5_L08_basic','lesson_basic','M5-1-u5-C8',2,'sa','auto','⟨5/6⟩ km와 ⟨5/12⟩ km의 차를 분모 12인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u5-C8","difficulty":2,"kind":"sa","stem":"⟨5/6⟩ km와 ⟨5/12⟩ km의 차를 분모 12인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["12로 통분하면 ⟨10/12⟩ − ⟨5/12⟩예요.","분자끼리 10 − 5 = 5예요.","차는 ⟨5/12⟩ km — 분자는 5예요."],"variant_rule":{"alt":[{"stem":"⟨7/8⟩ km와 ⟨1/3⟩ km의 차를 분모 24인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["24로 통분하면 ⟨21/24⟩ − ⟨8/24⟩이에요.","분자끼리 21 − 8 = 13이에요.","차는 ⟨13/24⟩ km — 분자는 13이에요."]},{"stem":"⟨9/10⟩ km와 ⟨2/5⟩ km의 차를 분모 10인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["10으로 통분하면 ⟨9/10⟩ − ⟨4/10⟩예요.","분자끼리 9 − 4 = 5예요.","차는 ⟨5/10⟩ km — 분자는 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L08_basic#7','math',5,1,'u5','L08','g5_1_math_u5_L08_basic','lesson_basic','M5-1-u5-C8',2,'mc','auto','학교까지 ⟨7/12⟩ km인 길로 왕복하면 모두 몇 km를 걷게 되나요?',ARRAY['M5-1-u5-X11','M5-1-u5-X13','M5-1-u5-X05']::text[],true,'{"seq":7,"concept":"M5-1-u5-C8","difficulty":2,"kind":"mc","stem":"학교까지 ⟨7/12⟩ km인 길로 왕복하면 모두 몇 km를 걷게 되나요?","options":[{"t":"⟨1 1/6⟩","correct":true},{"t":"⟨7/12⟩","mis":"M5-1-u5-X11"},{"t":"⟨1 1/4⟩","mis":"M5-1-u5-X13"},{"t":"⟨1/6⟩","mis":"M5-1-u5-X05"}],"explanation":["왕복은 갔다가 돌아오는 것 — 같은 길을 두 번 걸어요.","⟨7/12⟩ + ⟨7/12⟩ = ⟨1 1/6⟩이에요.","그래서 모두 ⟨1 1/6⟩ km예요."],"variant_rule":{"alt":[{"stem":"학교까지 ⟨5/8⟩ km인 길로 왕복하면 모두 몇 km를 걷게 되나요?","options":[{"t":"⟨1 1/4⟩","correct":true},{"t":"⟨5/8⟩","mis":"M5-1-u5-X11"},{"t":"⟨1 3/8⟩","mis":"M5-1-u5-X13"},{"t":"⟨1/4⟩","mis":"M5-1-u5-X05"}],"explanation":["왕복은 갔다가 돌아오는 것 — 같은 길을 두 번 걸어요.","⟨5/8⟩ + ⟨5/8⟩ = ⟨1 1/4⟩이에요.","그래서 모두 ⟨1 1/4⟩ km예요."]},{"stem":"학교까지 ⟨3/4⟩ km인 길로 왕복하면 모두 몇 km를 걷게 되나요?","options":[{"t":"⟨1 1/2⟩","correct":true},{"t":"⟨3/4⟩","mis":"M5-1-u5-X11"},{"t":"⟨1 3/4⟩","mis":"M5-1-u5-X13"},{"t":"⟨1/2⟩","mis":"M5-1-u5-X05"}],"explanation":["왕복은 갔다가 돌아오는 것 — 같은 길을 두 번 걸어요.","⟨3/4⟩ + ⟨3/4⟩ = ⟨1 1/2⟩이에요.","그래서 모두 ⟨1 1/2⟩ km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L08_basic#8','math',5,1,'u5','L08','g5_1_math_u5_L08_basic','lesson_basic','M5-1-u5-C8',2,'mc','auto','⟨5/6⟩ km인 길 대신 ⟨7/12⟩ km인 길로 가면 몇 km를 덜 걷게 되나요?',ARRAY['M5-1-u5-X11','M5-1-u5-X13']::text[],true,'{"seq":8,"concept":"M5-1-u5-C8","difficulty":2,"kind":"mc","stem":"⟨5/6⟩ km인 길 대신 ⟨7/12⟩ km인 길로 가면 몇 km를 덜 걷게 되나요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"⟨1 5/12⟩","mis":"M5-1-u5-X11"},{"t":"⟨1/3⟩","mis":"M5-1-u5-X13"},{"t":"⟨1/6⟩","mis":"M5-1-u5-X13"}],"explanation":["공통분모 12로 통분하면 ⟨10/12⟩ − ⟨7/12⟩이에요.","분모는 그대로 두고 분자끼리 빼면 ⟨10/12⟩ − ⟨7/12⟩ = ⟨3/12⟩ = ⟨1/4⟩이에요.","그래서 ⟨5/6⟩ − ⟨7/12⟩ = ⟨1/4⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩ km인 길 대신 ⟨2/3⟩ km인 길로 가면 몇 km를 덜 걷게 되나요?","options":[{"t":"⟨1/12⟩","correct":true},{"t":"⟨1 5/12⟩","mis":"M5-1-u5-X11"},{"t":"1","mis":"M5-1-u5-X01"},{"t":"⟨1/6⟩","mis":"M5-1-u5-X13"}],"explanation":["공통분모 12로 통분하면 ⟨9/12⟩ − ⟨8/12⟩이에요.","분모는 그대로 두고 분자끼리 빼면 ⟨9/12⟩ − ⟨8/12⟩ = ⟨1/12⟩이에요.","그래서 ⟨3/4⟩ − ⟨2/3⟩ = ⟨1/12⟩이에요."]},{"stem":"⟨9/10⟩ km인 길 대신 ⟨3/5⟩ km인 길로 가면 몇 km를 덜 걷게 되나요?","options":[{"t":"⟨3/10⟩","correct":true},{"t":"⟨1 1/2⟩","mis":"M5-1-u5-X11"},{"t":"⟨1 1/5⟩","mis":"M5-1-u5-X01"},{"t":"⟨3/5⟩","mis":"M5-1-u5-X02"}],"explanation":["공통분모 10으로 통분하면 ⟨9/10⟩ − ⟨6/10⟩이에요.","분모는 그대로 두고 분자끼리 빼면 ⟨9/10⟩ − ⟨6/10⟩ = ⟨3/10⟩이에요.","그래서 ⟨9/10⟩ − ⟨3/5⟩ = ⟨3/10⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L08_basic#9','math',5,1,'u5','L08','g5_1_math_u5_L08_basic','lesson_basic','M5-1-u5-C8',2,'mc','auto','⟨5/6⟩ km인 길 대신 ⟨7/12⟩ km인 길로 가면 몇 km를 덜 걷는지 구하는 식은 어느 것인가요?',ARRAY['M5-1-u5-X11','M5-1-u5-X14']::text[],true,'{"seq":9,"concept":"M5-1-u5-C8","difficulty":2,"kind":"mc","stem":"⟨5/6⟩ km인 길 대신 ⟨7/12⟩ km인 길로 가면 몇 km를 덜 걷는지 구하는 식은 어느 것인가요?","options":[{"t":"⟨5/6⟩ − ⟨7/12⟩","correct":true},{"t":"⟨5/6⟩ + ⟨7/12⟩","mis":"M5-1-u5-X11"},{"t":"⟨7/12⟩ − ⟨5/6⟩","mis":"M5-1-u5-X14"},{"t":"⟨7/12⟩ + ⟨7/12⟩","mis":"M5-1-u5-X11"}],"explanation":["덜 걷는 거리는 두 거리의 차예요.","긴 거리에서 짧은 거리를 빼요.","식은 ⟨5/6⟩ − ⟨7/12⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩ km인 길을 걷다가 ⟨1/3⟩ km를 걸었어요. 남은 거리를 구하는 식은 어느 것인가요?","options":[{"t":"⟨3/4⟩ − ⟨1/3⟩","correct":true},{"t":"⟨3/4⟩ + ⟨1/3⟩","mis":"M5-1-u5-X11"},{"t":"⟨3/4⟩ + ⟨3/4⟩","mis":"M5-1-u5-X11"},{"t":"⟨1/3⟩ − ⟨3/4⟩","mis":"M5-1-u5-X14"}],"explanation":["남은 거리는 전체 거리에서 걸은 거리를 빼요.","전체 ⟨3/4⟩ km에서 ⟨1/3⟩ km를 빼요.","식은 ⟨3/4⟩ − ⟨1/3⟩이에요."]},{"stem":"⟨7/8⟩ km인 길 대신 ⟨2/3⟩ km인 길로 가면 몇 km를 덜 걷는지 구하는 식은 어느 것인가요?","options":[{"t":"⟨7/8⟩ − ⟨2/3⟩","correct":true},{"t":"⟨7/8⟩ + ⟨2/3⟩","mis":"M5-1-u5-X11"},{"t":"⟨2/3⟩ − ⟨7/8⟩","mis":"M5-1-u5-X14"},{"t":"⟨2/3⟩ + ⟨2/3⟩","mis":"M5-1-u5-X11"}],"explanation":["덜 걷는 거리는 두 거리의 차예요.","긴 거리에서 짧은 거리를 빼요.","식은 ⟨7/8⟩ − ⟨2/3⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L08_basic#10','math',5,1,'u5','L08','g5_1_math_u5_L08_basic','lesson_basic','M5-1-u5-C8',3,'mc','auto','공원 길은 ⟨1/2⟩ km + ⟨1/3⟩ km, 시장 길은 ⟨2/5⟩ km + ⟨1/4⟩ km예요. 어느 길이 몇 km 더 짧은가요?',ARRAY['M5-1-u5-X14','M5-1-u5-X13']::text[],true,'{"seq":10,"concept":"M5-1-u5-C8","difficulty":3,"kind":"mc","stem":"공원 길은 ⟨1/2⟩ km + ⟨1/3⟩ km, 시장 길은 ⟨2/5⟩ km + ⟨1/4⟩ km예요. 어느 길이 몇 km 더 짧은가요?","options":[{"t":"시장 길이 ⟨11/60⟩ km 더 짧다","correct":true},{"t":"공원 길이 ⟨11/60⟩ km 더 짧다","mis":"M5-1-u5-X14"},{"t":"시장 길이 ⟨1/5⟩ km 더 짧다","mis":"M5-1-u5-X13"},{"t":"두 길의 거리가 같다","mis":"M5-1-u5-X13"}],"explanation":["공원 길은 ⟨1/2⟩ + ⟨1/3⟩ = ⟨5/6⟩ km, 시장 길은 ⟨2/5⟩ + ⟨1/4⟩ = ⟨13/20⟩ km예요.","60으로 통분해 견주면 시장 길이 더 짧아요.","차는 ⟨5/6⟩ − ⟨13/20⟩ = ⟨11/60⟩ km예요."],"variant_rule":{"alt":[{"stem":"하천 길은 ⟨1/3⟩ km + ⟨1/4⟩ km, 둑방 길은 ⟨1/2⟩ km + ⟨1/6⟩ km예요. 어느 길이 몇 km 더 짧은가요?","options":[{"t":"하천 길이 ⟨1/12⟩ km 더 짧다","correct":true},{"t":"둑방 길이 ⟨1/12⟩ km 더 짧다","mis":"M5-1-u5-X14"},{"t":"하천 길이 ⟨1/6⟩ km 더 짧다","mis":"M5-1-u5-X13"},{"t":"두 길의 거리가 같다","mis":"M5-1-u5-X13"}],"explanation":["하천 길은 ⟨1/3⟩ + ⟨1/4⟩ = ⟨7/12⟩ km, 둑방 길은 ⟨1/2⟩ + ⟨1/6⟩ = ⟨2/3⟩ km예요.","12로 통분해 견주면 하천 길이 더 짧아요.","차는 ⟨2/3⟩ − ⟨7/12⟩ = ⟨1/12⟩ km예요."]},{"stem":"언덕 길은 ⟨2/3⟩ km + ⟨1/6⟩ km, 골목 길은 ⟨1/2⟩ km + ⟨1/5⟩ km예요. 어느 길이 몇 km 더 짧은가요?","options":[{"t":"골목 길이 ⟨2/15⟩ km 더 짧다","correct":true},{"t":"언덕 길이 ⟨2/15⟩ km 더 짧다","mis":"M5-1-u5-X14"},{"t":"골목 길이 ⟨1/6⟩ km 더 짧다","mis":"M5-1-u5-X13"},{"t":"두 길의 거리가 같다","mis":"M5-1-u5-X13"}],"explanation":["언덕 길은 ⟨2/3⟩ + ⟨1/6⟩ = ⟨5/6⟩ km, 골목 길은 ⟨1/2⟩ + ⟨1/5⟩ = ⟨7/10⟩ km예요.","30으로 통분해 견주면 골목 길이 더 짧아요.","차는 ⟨5/6⟩ − ⟨7/10⟩ = ⟨2/15⟩ km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L08_challenge#1','math',5,1,'u5','L08','g5_1_math_u5_L08_challenge','lesson_challenge','M5-1-u5-C8',2,'mc','auto','공원 길(⟨5/6⟩ km)과 시장 길(⟨13/20⟩ km) 중 더 짧은 길을 두고 바르게 말한 친구는 누구인가요?',ARRAY['M5-1-u5-X12','M5-1-u5-X04']::text[],true,'{"seq":1,"concept":"M5-1-u5-C8","difficulty":2,"kind":"mc","stem":"공원 길(⟨5/6⟩ km)과 시장 길(⟨13/20⟩ km) 중 더 짧은 길을 두고 바르게 말한 친구는 누구인가요?","options":[{"t":"하은 — 「60으로 통분하면 ⟨50/60⟩과 ⟨39/60⟩라 시장 길이 더 짧아.」","correct":true},{"t":"서윤 — 「분자 13이 5보다 크니까 시장 길이 더 길어.」","mis":"M5-1-u5-X12"},{"t":"도현 — 「분모가 달라서 견줄 수 없어.」","mis":"M5-1-u5-X04"},{"t":"라온 — 「분모 20이 더 크니까 시장 길이 더 짧아.」","mis":"M5-1-u5-X12"}],"explanation":["분모가 다르면 분자만 견줄 수 없어요.","60으로 통분하면 ⟨50/60⟩ > ⟨39/60⟩예요.","그래서 시장 길(⟨13/20⟩ km)이 더 짧아요."],"variant_rule":{"alt":[{"stem":"하천 길(⟨7/12⟩ km)과 둑방 길(⟨5/8⟩ km) 중 더 짧은 길을 두고 바르게 말한 친구는 누구인가요?","options":[{"t":"예준 — 「24로 통분하면 ⟨14/24⟩와 ⟨15/24⟩라 하천 길이 더 짧아.」","correct":true},{"t":"지민 — 「분자 7이 5보다 크니까 하천 길이 더 길어.」","mis":"M5-1-u5-X12"},{"t":"서윤 — 「분모가 달라서 견줄 수 없어.」","mis":"M5-1-u5-X04"},{"t":"도현 — 「분모 12가 8보다 크니까 하천 길이 더 길어.」","mis":"M5-1-u5-X12"}],"explanation":["분모가 다르면 분자만 견줄 수 없어요.","24로 통분하면 ⟨14/24⟩ < ⟨15/24⟩예요.","그래서 하천 길(⟨7/12⟩ km)이 더 짧아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L08_challenge#2','math',5,1,'u5','L08','g5_1_math_u5_L08_challenge','lesson_challenge','M5-1-u5-C8',2,'sa','auto','⟨5/6⟩ km와 ⟨13/20⟩ km의 차를 분모 60인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u5-C8","difficulty":2,"kind":"sa","stem":"⟨5/6⟩ km와 ⟨13/20⟩ km의 차를 분모 60인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["60으로 통분하면 ⟨50/60⟩ − ⟨39/60⟩예요.","분자끼리 50 − 39 = 11이에요.","차는 ⟨11/60⟩ km — 분자는 11이에요."],"variant_rule":{"alt":[{"stem":"⟨7/12⟩ km와 ⟨1/3⟩ km의 차를 분모 12인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["12로 통분하면 ⟨7/12⟩ − ⟨4/12⟩예요.","분자끼리 7 − 4 = 3이에요.","차는 ⟨3/12⟩ km — 분자는 3이에요."]},{"stem":"⟨2/3⟩ km와 ⟨5/8⟩ km의 차를 분모 24인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["24로 통분하면 ⟨16/24⟩ − ⟨15/24⟩예요.","분자끼리 16 − 15 = 1이에요.","차는 ⟨1/24⟩ km — 분자는 1이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L08_challenge#3','math',5,1,'u5','L08','g5_1_math_u5_L08_challenge','lesson_challenge','M5-1-u5-C8',3,'mc','auto','세 길의 거리가 ⟨1 1/4⟩, ⟨1 1/6⟩, ⟨1 2/9⟩ km예요. 가장 짧은 길의 거리는 어느 것인가요?',ARRAY['M5-1-u5-X12','M5-1-u5-X04']::text[],true,'{"seq":3,"concept":"M5-1-u5-C8","difficulty":3,"kind":"mc","stem":"세 길의 거리가 ⟨1 1/4⟩, ⟨1 1/6⟩, ⟨1 2/9⟩ km예요. 가장 짧은 길의 거리는 어느 것인가요?","options":[{"t":"⟨1 1/6⟩ km","correct":true},{"t":"⟨1 1/4⟩ km","mis":"M5-1-u5-X12"},{"t":"⟨1 2/9⟩ km","mis":"M5-1-u5-X12"},{"t":"셋 다 같다","mis":"M5-1-u5-X04"}],"explanation":["36으로 통분하면 ⟨45/36⟩, ⟨42/36⟩, ⟨44/36⟩예요.","분자를 견주면 가장 작은 것은 42예요.","그래서 가장 짧은 길은 ⟨1 1/6⟩ km예요."],"variant_rule":{"alt":[{"stem":"세 길의 거리가 ⟨1 3/8⟩, ⟨1 1/3⟩, ⟨1 5/12⟩ km예요. 가장 짧은 길의 거리는 어느 것인가요?","options":[{"t":"⟨1 1/3⟩ km","correct":true},{"t":"⟨1 3/8⟩ km","mis":"M5-1-u5-X12"},{"t":"⟨1 5/12⟩ km","mis":"M5-1-u5-X12"},{"t":"셋 다 같다","mis":"M5-1-u5-X04"}],"explanation":["24로 통분하면 ⟨33/24⟩, ⟨32/24⟩, ⟨34/24⟩예요.","분자를 견주면 가장 작은 것은 32예요.","그래서 가장 짧은 길은 ⟨1 1/3⟩ km예요."]},{"stem":"세 길의 거리가 ⟨2 1/2⟩, ⟨2 3/5⟩, ⟨2 4/7⟩ km예요. 가장 긴 길의 거리는 어느 것인가요?","options":[{"t":"⟨2 3/5⟩ km","correct":true},{"t":"⟨2 1/2⟩ km","mis":"M5-1-u5-X12"},{"t":"⟨2 4/7⟩ km","mis":"M5-1-u5-X12"},{"t":"셋 다 같다","mis":"M5-1-u5-X04"}],"explanation":["70으로 통분하면 ⟨175/70⟩, ⟨182/70⟩, ⟨180/70⟩이에요.","분자를 견주면 가장 큰 것은 182예요.","그래서 가장 긴 길은 ⟨2 3/5⟩ km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L08_challenge#4','math',5,1,'u5','L08','g5_1_math_u5_L08_challenge','lesson_challenge','M5-1-u5-C8',3,'sa','auto','집에서 학교까지 ⟨1 1/4⟩ km예요. ⟨2/3⟩ km를 걸었다면 남은 거리는 ⟨□/12⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u5-C8","difficulty":3,"kind":"sa","stem":"집에서 학교까지 ⟨1 1/4⟩ km예요. ⟨2/3⟩ km를 걸었다면 남은 거리는 ⟨□/12⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["남은 거리 = 전체 거리 − 걸은 거리예요.","⟨1 1/4⟩ − ⟨2/3⟩ = ⟨15/12⟩ − ⟨8/12⟩ = ⟨7/12⟩이에요.","그래서 □는 7이에요."],"variant_rule":{"alt":[{"stem":"집에서 학교까지 ⟨1 1/6⟩ km예요. ⟨3/4⟩ km를 걸었다면 남은 거리는 ⟨□/12⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["남은 거리 = 전체 거리 − 걸은 거리예요.","⟨1 1/6⟩ − ⟨3/4⟩ = ⟨14/12⟩ − ⟨9/12⟩ = ⟨5/12⟩예요.","그래서 □는 5예요."]},{"stem":"집에서 학교까지 ⟨1 3/10⟩ km예요. ⟨4/5⟩ km를 걸었다면 남은 거리는 ⟨□/10⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["남은 거리 = 전체 거리 − 걸은 거리예요.","⟨1 3/10⟩ − ⟨4/5⟩ = ⟨13/10⟩ − ⟨8/10⟩ = ⟨5/10⟩예요.","그래서 □는 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L08_challenge#5','math',5,1,'u5','L08','g5_1_math_u5_L08_challenge','lesson_challenge','M5-1-u5-C8',3,'mc','auto','학교까지 ⟨1 2/5⟩ km인 길로 왕복하면 모두 몇 km를 걷게 되나요?',ARRAY['M5-1-u5-X11','M5-1-u5-X03','M5-1-u5-X13']::text[],true,'{"seq":5,"concept":"M5-1-u5-C8","difficulty":3,"kind":"mc","stem":"학교까지 ⟨1 2/5⟩ km인 길로 왕복하면 모두 몇 km를 걷게 되나요?","options":[{"t":"⟨2 4/5⟩","correct":true},{"t":"⟨1 2/5⟩","mis":"M5-1-u5-X11"},{"t":"⟨2 2/5⟩","mis":"M5-1-u5-X03"},{"t":"3","mis":"M5-1-u5-X13"}],"explanation":["왕복은 갔다가 돌아오는 것 — 같은 길을 두 번 걸어요.","⟨1 2/5⟩ + ⟨1 2/5⟩ = ⟨2 4/5⟩예요.","그래서 모두 ⟨2 4/5⟩ km예요."],"variant_rule":{"alt":[{"stem":"학교까지 ⟨1 3/8⟩ km인 길로 왕복하면 모두 몇 km를 걷게 되나요?","options":[{"t":"⟨2 3/4⟩","correct":true},{"t":"⟨1 3/8⟩","mis":"M5-1-u5-X11"},{"t":"⟨2 3/8⟩","mis":"M5-1-u5-X03"},{"t":"⟨2 7/8⟩","mis":"M5-1-u5-X13"}],"explanation":["왕복은 갔다가 돌아오는 것 — 같은 길을 두 번 걸어요.","⟨1 3/8⟩ + ⟨1 3/8⟩ = ⟨2 3/4⟩이에요.","그래서 모두 ⟨2 3/4⟩ km예요."]},{"stem":"학교까지 ⟨1 5/6⟩ km인 길로 왕복하면 모두 몇 km를 걷게 되나요?","options":[{"t":"⟨3 2/3⟩","correct":true},{"t":"⟨1 5/6⟩","mis":"M5-1-u5-X11"},{"t":"⟨2 5/6⟩","mis":"M5-1-u5-X03"},{"t":"⟨3 5/6⟩","mis":"M5-1-u5-X13"}],"explanation":["왕복은 갔다가 돌아오는 것 — 같은 길을 두 번 걸어요.","⟨1 5/6⟩ + ⟨1 5/6⟩ = ⟨3 2/3⟩예요.","그래서 모두 ⟨3 2/3⟩ km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L08_challenge#6','math',5,1,'u5','L08','g5_1_math_u5_L08_challenge','lesson_challenge','M5-1-u5-C8',3,'mc','auto','공원 길은 ⟨1/2⟩ km + ⟨1/3⟩ km, 시장 길은 ⟨2/5⟩ km + ⟨1/4⟩ km예요. 어느 길이 몇 km 더 짧은가요?',ARRAY['M5-1-u5-X14','M5-1-u5-X13']::text[],true,'{"seq":6,"concept":"M5-1-u5-C8","difficulty":3,"kind":"mc","stem":"공원 길은 ⟨1/2⟩ km + ⟨1/3⟩ km, 시장 길은 ⟨2/5⟩ km + ⟨1/4⟩ km예요. 어느 길이 몇 km 더 짧은가요?","options":[{"t":"시장 길이 ⟨11/60⟩ km 더 짧다","correct":true},{"t":"공원 길이 ⟨11/60⟩ km 더 짧다","mis":"M5-1-u5-X14"},{"t":"시장 길이 ⟨1/5⟩ km 더 짧다","mis":"M5-1-u5-X13"},{"t":"두 길의 거리가 같다","mis":"M5-1-u5-X13"}],"explanation":["공원 길은 ⟨1/2⟩ + ⟨1/3⟩ = ⟨5/6⟩ km, 시장 길은 ⟨2/5⟩ + ⟨1/4⟩ = ⟨13/20⟩ km예요.","60으로 통분해 견주면 시장 길이 더 짧아요.","차는 ⟨5/6⟩ − ⟨13/20⟩ = ⟨11/60⟩ km예요."],"variant_rule":{"alt":[{"stem":"숲길은 ⟨3/4⟩ km + ⟨1/6⟩ km, 강변 길은 ⟨2/3⟩ km + ⟨1/5⟩ km예요. 어느 길이 몇 km 더 짧은가요?","options":[{"t":"강변 길이 ⟨1/20⟩ km 더 짧다","correct":true},{"t":"숲길이 ⟨1/20⟩ km 더 짧다","mis":"M5-1-u5-X14"},{"t":"강변 길이 ⟨1/15⟩ km 더 짧다","mis":"M5-1-u5-X13"},{"t":"두 길의 거리가 같다","mis":"M5-1-u5-X13"}],"explanation":["숲길은 ⟨3/4⟩ + ⟨1/6⟩ = ⟨11/12⟩ km, 강변 길은 ⟨2/3⟩ + ⟨1/5⟩ = ⟨13/15⟩ km예요.","60으로 통분해 견주면 강변 길이 더 짧아요.","차는 ⟨11/12⟩ − ⟨13/15⟩ = ⟨1/20⟩ km예요."]},{"stem":"가로수 길은 ⟨1/2⟩ km + ⟨2/5⟩ km, 골목 길은 ⟨3/8⟩ km + ⟨1/3⟩ km예요. 어느 길이 몇 km 더 짧은가요?","options":[{"t":"골목 길이 ⟨23/120⟩ km 더 짧다","correct":true},{"t":"가로수 길이 ⟨23/120⟩ km 더 짧다","mis":"M5-1-u5-X14"},{"t":"골목 길이 ⟨1/5⟩ km 더 짧다","mis":"M5-1-u5-X13"},{"t":"두 길의 거리가 같다","mis":"M5-1-u5-X13"}],"explanation":["가로수 길은 ⟨1/2⟩ + ⟨2/5⟩ = ⟨9/10⟩ km, 골목 길은 ⟨3/8⟩ + ⟨1/3⟩ = ⟨17/24⟩ km예요.","120으로 통분해 견주면 골목 길이 더 짧아요.","차는 ⟨9/10⟩ − ⟨17/24⟩ = ⟨23/120⟩ km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L08_challenge#7','math',5,1,'u5','L08','g5_1_math_u5_L08_challenge','lesson_challenge','M5-1-u5-C8',3,'ox','auto','어느 길이 더 짧은지 알아보려면 두 길의 거리를 통분해 견주어야 해요.',ARRAY['M5-1-u5-X12']::text[],true,'{"seq":7,"concept":"M5-1-u5-C8","difficulty":3,"kind":"ox","stem":"어느 길이 더 짧은지 알아보려면 두 길의 거리를 통분해 견주어야 해요.","answer":"O","reason_options":[{"t":"분모가 다르면 같은 눈금으로 다시 재야 견줄 수 있으므로","correct":true},{"t":"분자가 큰 쪽이 언제나 더 긴 길이므로","mis":"M5-1-u5-X12"}],"mis":"M5-1-u5-X12","explanation":["통분은 같은 눈금의 자로 다시 재는 일이에요.","⟨5/6⟩ = ⟨50/60⟩, ⟨13/20⟩ = ⟨39/60⟩예요.","눈금이 같아야 큰지 작은지 알 수 있어요."],"variant_rule":{"alt":[{"stem":"학교까지 ⟨7/12⟩ km인 길을 왕복한 거리는 ⟨7/12⟩ km예요.","answer":"X","reason_options":[{"t":"왕복은 같은 길을 두 번 걸어 ⟨7/12⟩ + ⟨7/12⟩ = ⟨1 1/6⟩ km이므로","correct":true},{"t":"갔다가 돌아와도 같은 길이라 한 번만 세므로","mis":"M5-1-u5-X11"}],"explanation":["왕복은 갔다가 돌아오는 거예요.","⟨7/12⟩ + ⟨7/12⟩ = ⟨14/12⟩ = ⟨1 1/6⟩이에요.","왕복한 거리는 ⟨1 1/6⟩ km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L08_challenge#8','math',5,1,'u5','L08','g5_1_math_u5_L08_challenge','lesson_challenge','M5-1-u5-C8',4,'sa','auto','집과 도서관 사이는 ⟨1 3/4⟩ km예요. 민서는 집에서, 준우는 도서관에서 서로를 향해 각각 ⟨2/3⟩ km, ⟨5/6⟩ km를 걸었어요. 두 사람 사이에 남은 거리는 ⟨□/12⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u5-C8","difficulty":4,"kind":"sa","stem":"집과 도서관 사이는 ⟨1 3/4⟩ km예요. 민서는 집에서, 준우는 도서관에서 서로를 향해 각각 ⟨2/3⟩ km, ⟨5/6⟩ km를 걸었어요. 두 사람 사이에 남은 거리는 ⟨□/12⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["두 사람이 걸은 거리는 ⟨2/3⟩ + ⟨5/6⟩ = ⟨1 1/2⟩ km예요.","남은 거리는 ⟨1 3/4⟩ − ⟨1 1/2⟩ = ⟨21/12⟩ − ⟨18/12⟩ = ⟨3/12⟩ km예요.","그래서 □는 3이에요."],"variant_rule":{"alt":[{"stem":"집과 도서관 사이는 ⟨1 1/2⟩ km예요. 민서는 집에서, 준우는 도서관에서 서로를 향해 각각 ⟨1/3⟩ km, ⟨3/4⟩ km를 걸었어요. 두 사람 사이에 남은 거리는 ⟨□/12⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["두 사람이 걸은 거리는 ⟨1/3⟩ + ⟨3/4⟩ = ⟨1 1/12⟩ km예요.","남은 거리는 ⟨1 1/2⟩ − ⟨1 1/12⟩ = ⟨18/12⟩ − ⟨13/12⟩ = ⟨5/12⟩ km예요.","그래서 □는 5예요."]},{"stem":"집과 도서관 사이는 ⟨1 4/5⟩ km예요. 민서는 집에서, 준우는 도서관에서 서로를 향해 각각 ⟨1/2⟩ km, ⟨7/10⟩ km를 걸었어요. 두 사람 사이에 남은 거리는 ⟨□/10⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["두 사람이 걸은 거리는 ⟨1/2⟩ + ⟨7/10⟩ = ⟨1 1/5⟩ km예요.","남은 거리는 ⟨1 4/5⟩ − ⟨1 1/5⟩ = ⟨18/10⟩ − ⟨12/10⟩ = ⟨6/10⟩ km예요.","그래서 □는 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L08_challenge#9','math',5,1,'u5','L08','g5_1_math_u5_L08_challenge','lesson_challenge','M5-1-u5-C8',4,'mc','auto','왕복한 거리가 2 km를 넘지 않는 길은 어느 것인가요? (길마다 편도 거리를 적었어요)',ARRAY['M5-1-u5-X11']::text[],true,'{"seq":9,"concept":"M5-1-u5-C8","difficulty":4,"kind":"mc","stem":"왕복한 거리가 2 km를 넘지 않는 길은 어느 것인가요? (길마다 편도 거리를 적었어요)","options":[{"t":"⟨5/6⟩ km","correct":true},{"t":"⟨1 1/12⟩ km","mis":"M5-1-u5-X11"},{"t":"⟨1 1/8⟩ km","mis":"M5-1-u5-X11"}],"explanation":["왕복은 편도 거리를 두 번 더해요.","⟨1 1/12⟩ + ⟨1 1/12⟩ = ⟨2 1/6⟩, ⟨5/6⟩ + ⟨5/6⟩ = ⟨1 2/3⟩, ⟨1 1/8⟩ + ⟨1 1/8⟩ = ⟨2 1/4⟩이에요.","2 km를 넘지 않는 것은 ⟨5/6⟩ km인 길이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 왕복한 거리가 2 km를 넘지 않는 길은 어느 것인가요? (길마다 편도 거리를 적었어요)","options":[{"t":"⟨5/6⟩ km","correct":true},{"t":"⟨1 1/5⟩ km","mis":"M5-1-u5-X11"},{"t":"⟨1 1/8⟩ km","mis":"M5-1-u5-X11"}],"explanation":["왕복은 편도 거리를 두 번 더해요.","⟨1 1/5⟩ + ⟨1 1/5⟩ = ⟨2 2/5⟩, ⟨1 1/8⟩ + ⟨1 1/8⟩ = ⟨2 1/4⟩, ⟨5/6⟩ + ⟨5/6⟩ = ⟨1 2/3⟩예요.","2 km를 넘지 않는 것은 ⟨5/6⟩ km인 길이에요."]},{"stem":"이번에는 다른 보기예요. 왕복한 거리가 2 km를 넘지 않는 길은 어느 것인가요? (길마다 편도 거리를 적었어요)","options":[{"t":"⟨7/8⟩ km","correct":true},{"t":"⟨1 1/6⟩ km","mis":"M5-1-u5-X11"},{"t":"⟨1 1/10⟩ km","mis":"M5-1-u5-X11"}],"explanation":["왕복은 편도 거리를 두 번 더해요.","⟨1 1/6⟩ + ⟨1 1/6⟩ = ⟨2 1/3⟩, ⟨7/8⟩ + ⟨7/8⟩ = ⟨1 3/4⟩, ⟨1 1/10⟩ + ⟨1 1/10⟩ = ⟨2 1/5⟩이에요.","2 km를 넘지 않는 것은 ⟨7/8⟩ km인 길이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_L08_challenge#10','math',5,1,'u5','L08','g5_1_math_u5_L08_challenge','lesson_challenge','M5-1-u5-C8',4,'essay','teacher','공원 길은 ⟨1/2⟩ km + ⟨1/3⟩ km, 시장 길은 ⟨2/5⟩ km + ⟨1/4⟩ km예요. 어느 길이 더 짧은지 알아보는 방법을 차례대로 쓰고 답을 구하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u5-C8","difficulty":4,"kind":"essay","stem":"공원 길은 ⟨1/2⟩ km + ⟨1/3⟩ km, 시장 길은 ⟨2/5⟩ km + ⟨1/4⟩ km예요. 어느 길이 더 짧은지 알아보는 방법을 차례대로 쓰고 답을 구하세요.","answer_guide":{"answer":"예: 먼저 길마다 거리를 더한다. 공원 길은 ⟨3/6⟩ + ⟨2/6⟩ = ⟨5/6⟩ km, 시장 길은 ⟨8/20⟩ + ⟨5/20⟩ = ⟨13/20⟩ km이다. 두 거리를 60으로 통분하면 ⟨50/60⟩과 ⟨39/60⟩이므로 시장 길이 ⟨11/60⟩ km 더 짧다.","scoring_points":["길마다 두 거리를 통분해 더했는가","두 결과를 다시 통분해 견주었는가","시장 길이 더 짧다고(차까지) 바르게 답했는가"]},"explanation":["공원 길 ⟨5/6⟩ km, 시장 길 ⟨13/20⟩ km예요.","60으로 통분하면 ⟨50/60⟩ > ⟨39/60⟩예요.","시장 길이 ⟨11/60⟩ km 더 짧아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#1','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C1',1,'mc','auto','⟨1/4⟩ + ⟨2/5⟩를 계산할 때 가장 먼저 할 일은 무엇인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X02']::text[],false,'{"seq":1,"concept":"M5-1-u5-C1","difficulty":1,"kind":"mc","stem":"⟨1/4⟩ + ⟨2/5⟩를 계산할 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"두 분수를 통분한다","correct":true},{"t":"분모끼리 더한다","mis":"M5-1-u5-X01"},{"t":"분자끼리 더한다","mis":"M5-1-u5-X01"},{"t":"분모를 곱한 뒤 분자를 더한다","mis":"M5-1-u5-X02"}],"explanation":["⟨1/4⟩과 ⟨2/5⟩는 분모가 달라 조각의 크기가 달라요.","크기가 다른 조각은 한꺼번에 셀 수 없어요.","그래서 먼저 통분해 조각 크기를 맞춘 뒤 분자끼리 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#2','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C1',1,'sa','auto','⟨1/4⟩과 ⟨1/6⟩을 통분할 때 공통분모로 알맞은 가장 작은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M5-1-u5-C1","difficulty":1,"kind":"sa","stem":"⟨1/4⟩과 ⟨1/6⟩을 통분할 때 공통분모로 알맞은 가장 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["공통분모는 두 분모 4와 6의 공배수예요.","가장 작은 공배수는 최소공배수 12예요.","분모의 곱 4 × 6 = 24도 공통분모가 될 수 있지만 가장 작은 수는 12예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#3','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C1',2,'mc','auto','⟨1/4⟩과 ⟨1/3⟩을 그림처럼 12칸으로 맞추어 나타냈어요. 두 분수를 더하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X13']::text[],false,'{"seq":3,"concept":"M5-1-u5-C1","difficulty":2,"kind":"mc","stem":"⟨1/4⟩과 ⟨1/3⟩을 그림처럼 12칸으로 맞추어 나타냈어요. 두 분수를 더하면 얼마인가요?","options":[{"t":"⟨7/12⟩","correct":true},{"t":"⟨2/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨7/24⟩","mis":"M5-1-u5-X03"},{"t":"⟨2/3⟩","mis":"M5-1-u5-X13"}],"explanation":["⟨1/4⟩은 12칸 중 3칸, ⟨1/3⟩은 12칸 중 4칸이에요.","같은 크기의 칸이라 3칸 + 4칸 = 7칸으로 셀 수 있어요.","⟨3/12⟩ + ⟨4/12⟩ = ⟨7/12⟩이에요."],"asset":{"type":"fbar","bars":[{"den":12,"num":3,"label":"⟨1/4⟩"},{"den":12,"num":4,"label":"⟨1/3⟩"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#4','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C2',1,'mc','auto','⟨1/4⟩ + ⟨2/5⟩를 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X02']::text[],false,'{"seq":4,"concept":"M5-1-u5-C2","difficulty":1,"kind":"mc","stem":"⟨1/4⟩ + ⟨2/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨13/20⟩","correct":true},{"t":"⟨1/3⟩","mis":"M5-1-u5-X01"},{"t":"⟨13/40⟩","mis":"M5-1-u5-X03"},{"t":"⟨3/20⟩","mis":"M5-1-u5-X02"}],"explanation":["공통분모 20으로 통분하면 ⟨5/20⟩ + ⟨8/20⟩이에요.","분모는 그대로 두고 분자끼리 더하면 ⟨5/20⟩ + ⟨8/20⟩ = ⟨13/20⟩이에요.","그래서 ⟨1/4⟩ + ⟨2/5⟩ = ⟨13/20⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#5','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C2',1,'sa','auto','⟨1/3⟩ + ⟨2/5⟩를 분모 15로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M5-1-u5-C2","difficulty":1,"kind":"sa","stem":"⟨1/3⟩ + ⟨2/5⟩를 분모 15로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["분모를 15로 맞추면 ⟨5/15⟩ + ⟨6/15⟩이에요.","분모 15는 그대로 두고 분자끼리 5 + 6 = 11이에요.","그래서 분자는 11이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#6','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C2',3,'mc','auto','텃밭의 ⟨1/4⟩에는 상추를, ⟨1/3⟩에는 방울토마토를 심었어요. 아무것도 심지 않은 부분은 전체의 얼마인가요?',ARRAY['M5-1-u5-X11','M5-1-u5-X01']::text[],false,'{"seq":6,"concept":"M5-1-u5-C2","difficulty":3,"kind":"mc","stem":"텃밭의 ⟨1/4⟩에는 상추를, ⟨1/3⟩에는 방울토마토를 심었어요. 아무것도 심지 않은 부분은 전체의 얼마인가요?","options":[{"t":"⟨5/12⟩","correct":true},{"t":"⟨7/12⟩","mis":"M5-1-u5-X11"},{"t":"⟨2/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨5/7⟩","mis":"M5-1-u5-X01"}],"explanation":["심은 부분은 ⟨1/4⟩ + ⟨1/3⟩ = ⟨3/12⟩ + ⟨4/12⟩ = ⟨7/12⟩이에요.","전체 1은 ⟨12/12⟩예요.","심지 않은 부분은 ⟨12/12⟩ − ⟨7/12⟩ = ⟨5/12⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#7','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C3',1,'sa','auto','⟨17/12⟩을 대분수로 나타내면 ⟨1 □/12⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M5-1-u5-C3","difficulty":1,"kind":"sa","stem":"⟨17/12⟩을 대분수로 나타내면 ⟨1 □/12⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모 12만큼 모이면 1이에요.","17칸에서 12칸을 덜어 내면 5칸이 남아요 — 17 − 12 = 5.","⟨17/12⟩ = ⟨1 5/12⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#8','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C3',2,'mc','auto','⟨2/3⟩ + ⟨3/4⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X05']::text[],false,'{"seq":8,"concept":"M5-1-u5-C3","difficulty":2,"kind":"mc","stem":"⟨2/3⟩ + ⟨3/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 5/12⟩","correct":true},{"t":"⟨5/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨17/24⟩","mis":"M5-1-u5-X03"},{"t":"⟨5/12⟩","mis":"M5-1-u5-X05"}],"explanation":["공통분모 12로 통분하면 ⟨8/12⟩ + ⟨9/12⟩예요.","분자끼리 더하면 ⟨8/12⟩ + ⟨9/12⟩ = ⟨17/12⟩ — 분모만큼 모인 12칸이 1이에요.","⟨17/12⟩ = ⟨1 5/12⟩이므로 ⟨2/3⟩ + ⟨3/4⟩ = ⟨1 5/12⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#9','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C3',3,'sa','auto','⟨2/3⟩ + ⟨□/12⟩의 계산 결과가 1보다 클 때 □에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u5-C3","difficulty":3,"kind":"sa","stem":"⟨2/3⟩ + ⟨□/12⟩의 계산 결과가 1보다 클 때 □에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨2/3⟩ = ⟨8/12⟩이고, 1 = ⟨12/12⟩예요.","8 + □가 12보다 커야 하니 □는 12 − 8 = 4보다 커요.","그래서 가장 작은 □는 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#10','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C4',1,'mc','auto','⟨1 1/2⟩ + ⟨2 2/5⟩를 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X02']::text[],false,'{"seq":10,"concept":"M5-1-u5-C4","difficulty":1,"kind":"mc","stem":"⟨1 1/2⟩ + ⟨2 2/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨3 9/10⟩","correct":true},{"t":"⟨3 3/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨3 9/20⟩","mis":"M5-1-u5-X03"},{"t":"⟨3 3/10⟩","mis":"M5-1-u5-X02"}],"explanation":["분수 부분을 10으로 통분하면 ⟨1 5/10⟩ + ⟨2 4/10⟩예요.","자연수끼리 1 + 2 = 3, 분수끼리 ⟨5/10⟩ + ⟨4/10⟩ = ⟨9/10⟩예요.","그래서 ⟨1 1/2⟩ + ⟨2 2/5⟩ = ⟨3 9/10⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#11','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C4',2,'mc','auto','⟨1 2/3⟩ + ⟨2 3/4⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X06']::text[],false,'{"seq":11,"concept":"M5-1-u5-C4","difficulty":2,"kind":"mc","stem":"⟨1 2/3⟩ + ⟨2 3/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 5/12⟩","correct":true},{"t":"⟨3 5/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨3 17/24⟩","mis":"M5-1-u5-X03"},{"t":"⟨3 5/12⟩","mis":"M5-1-u5-X06"}],"explanation":["분수 부분을 12로 통분하면 ⟨1 8/12⟩ + ⟨2 9/12⟩예요.","자연수끼리 1 + 2 = 3, 분수끼리 ⟨8/12⟩ + ⟨9/12⟩ = ⟨17/12⟩ = ⟨1 5/12⟩예요.","분수 부분에서 넘친 1을 자연수에 올리면 ⟨1 2/3⟩ + ⟨2 3/4⟩ = ⟨4 5/12⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#12','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C4',4,'sa','auto','분수 부분이 ⟨3/8⟩인 대분수에 ⟨1 3/4⟩을 더했더니 ⟨4 1/8⟩이 되었어요. 처음 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M5-1-u5-C4","difficulty":4,"kind":"sa","stem":"분수 부분이 ⟨3/8⟩인 대분수에 ⟨1 3/4⟩을 더했더니 ⟨4 1/8⟩이 되었어요. 처음 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["처음 대분수는 ⟨4 1/8⟩ − ⟨1 3/4⟩으로 구해요.","⟨4 1/8⟩ − ⟨1 3/4⟩ = ⟨2 3/8⟩이에요.","⟨2 3/8⟩의 자연수 부분은 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#13','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C5',1,'mc','auto','⟨3/4⟩ − ⟨1/3⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X02','M5-1-u5-X13']::text[],false,'{"seq":13,"concept":"M5-1-u5-C5","difficulty":1,"kind":"mc","stem":"⟨3/4⟩ − ⟨1/3⟩을 계산하면 얼마인가요?","options":[{"t":"⟨5/12⟩","correct":true},{"t":"2","mis":"M5-1-u5-X01"},{"t":"⟨1/6⟩","mis":"M5-1-u5-X02"},{"t":"⟨1/2⟩","mis":"M5-1-u5-X13"}],"explanation":["공통분모 12로 통분하면 ⟨9/12⟩ − ⟨4/12⟩예요.","분모는 그대로 두고 분자끼리 빼면 ⟨9/12⟩ − ⟨4/12⟩ = ⟨5/12⟩예요.","그래서 ⟨3/4⟩ − ⟨1/3⟩ = ⟨5/12⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#14','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C5',2,'sa','auto','⟨3/4⟩ − ⟨1/6⟩을 분모 12로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M5-1-u5-C5","difficulty":2,"kind":"sa","stem":"⟨3/4⟩ − ⟨1/6⟩을 분모 12로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["분모를 12로 맞추면 ⟨9/12⟩ − ⟨2/12⟩예요.","분모 12는 그대로 두고 분자끼리 9 − 2 = 7이에요.","그래서 분자는 7이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#15','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C5',3,'mc','auto','⟨3/4⟩ − ⟨1/6⟩ + ⟨1/2⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X13','M5-1-u5-X11']::text[],false,'{"seq":15,"concept":"M5-1-u5-C5","difficulty":3,"kind":"mc","stem":"⟨3/4⟩ − ⟨1/6⟩ + ⟨1/2⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 1/12⟩","correct":true},{"t":"⟨1 1/6⟩","mis":"M5-1-u5-X13"},{"t":"1","mis":"M5-1-u5-X13"},{"t":"⟨1 5/12⟩","mis":"M5-1-u5-X11"}],"explanation":["세 분수를 12로 통분하면 ⟨9/12⟩ − ⟨2/12⟩ + ⟨6/12⟩이에요.","앞에서부터 차례로 셈하면 ⟨9/12⟩ − ⟨2/12⟩ + ⟨6/12⟩ = ⟨13/12⟩이에요.","그래서 ⟨3/4⟩ − ⟨1/6⟩ + ⟨1/2⟩ = ⟨1 1/12⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#16','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C6',1,'mc','auto','⟨3 3/4⟩을 가분수로 나타내면 어느 것인가요?',ARRAY['M5-1-u5-X07']::text[],false,'{"seq":16,"concept":"M5-1-u5-C6","difficulty":1,"kind":"mc","stem":"⟨3 3/4⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨15/4⟩","correct":true},{"t":"⟨33/4⟩","mis":"M5-1-u5-X07"},{"t":"⟨6/4⟩","mis":"M5-1-u5-X07"},{"t":"⟨12/4⟩","mis":"M5-1-u5-X07"}],"explanation":["자연수 3은 ⟨12/4⟩예요 — 3 × 4 = 12.","여기에 ⟨3/4⟩을 더하면 분자는 12 + 3 = 15예요.","⟨3 3/4⟩ = ⟨15/4⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#17','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C6',2,'mc','auto','⟨3 3/4⟩ − ⟨1 1/3⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X02','M5-1-u5-X08']::text[],false,'{"seq":17,"concept":"M5-1-u5-C6","difficulty":2,"kind":"mc","stem":"⟨3 3/4⟩ − ⟨1 1/3⟩을 계산하면 얼마인가요?","options":[{"t":"⟨2 5/12⟩","correct":true},{"t":"4","mis":"M5-1-u5-X01"},{"t":"⟨2 1/6⟩","mis":"M5-1-u5-X02"},{"t":"⟨4 5/12⟩","mis":"M5-1-u5-X08"}],"explanation":["분수 부분을 12로 통분하면 ⟨3 9/12⟩ − ⟨1 4/12⟩예요.","자연수끼리 3 − 1 = 2, 분수끼리 ⟨9/12⟩ − ⟨4/12⟩ = ⟨5/12⟩예요.","그래서 ⟨3 3/4⟩ − ⟨1 1/3⟩ = ⟨2 5/12⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#18','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C6',3,'sa','auto','⟨5 5/6⟩ − ⟨1 1/4⟩ − ⟨2 1/3⟩을 계산한 값을 ⟨2 □/12⟩로 나타낼 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"M5-1-u5-C6","difficulty":3,"kind":"sa","stem":"⟨5 5/6⟩ − ⟨1 1/4⟩ − ⟨2 1/3⟩을 계산한 값을 ⟨2 □/12⟩로 나타낼 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["앞에서부터 셈해요 — ⟨5 5/6⟩ − ⟨1 1/4⟩ = ⟨4 7/12⟩이에요.","⟨4 7/12⟩ − ⟨2 1/3⟩ = ⟨2 1/4⟩이에요.","⟨2 1/4⟩ = ⟨2 3/12⟩ — □는 3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#19','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C7',3,'sa','auto','⟨3 1/4⟩ − ⟨1 2/3⟩를 가분수로 바꾸어 분모 12로 계산하면 ⟨□/12⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M5-1-u5-C7","difficulty":3,"kind":"sa","stem":"⟨3 1/4⟩ − ⟨1 2/3⟩를 가분수로 바꾸어 분모 12로 계산하면 ⟨□/12⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["⟨3 1/4⟩ = ⟨39/12⟩, ⟨1 2/3⟩ = ⟨20/12⟩이에요.","분자끼리 39 − 20 = 19예요.","⟨19/12⟩ = ⟨1 7/12⟩ — □는 19예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#20','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C7',2,'mc','auto','⟨4 1/2⟩ − ⟨1 3/4⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X09','M5-1-u5-X10']::text[],false,'{"seq":20,"concept":"M5-1-u5-C7","difficulty":2,"kind":"mc","stem":"⟨4 1/2⟩ − ⟨1 3/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨2 3/4⟩","correct":true},{"t":"⟨3 1/4⟩","mis":"M5-1-u5-X09"},{"t":"⟨3 3/4⟩","mis":"M5-1-u5-X10"},{"t":"⟨4 1/4⟩","mis":"M5-1-u5-X10"}],"explanation":["분수 부분을 4로 통분하면 ⟨4 2/4⟩ − ⟨1 3/4⟩이에요.","분자 2에서 3을 뺄 수 없어 자연수에서 1을 빌리면 ⟨4 2/4⟩ = ⟨3 6/4⟩이에요.","⟨3 6/4⟩ − ⟨1 3/4⟩ = ⟨2 3/4⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#21','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C7',2,'mc','auto','3 − ⟨1 2/5⟩를 계산하면 얼마인가요?',ARRAY['M5-1-u5-X10','M5-1-u5-X09']::text[],false,'{"seq":21,"concept":"M5-1-u5-C7","difficulty":2,"kind":"mc","stem":"3 − ⟨1 2/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1 3/5⟩","correct":true},{"t":"⟨2 2/5⟩","mis":"M5-1-u5-X10"},{"t":"⟨1 2/5⟩","mis":"M5-1-u5-X09"},{"t":"⟨2 3/5⟩","mis":"M5-1-u5-X10"}],"explanation":["3에서 1을 빌려 3 = ⟨2 5/5⟩로 바꾸어요 — 1은 ⟨5/5⟩예요.","⟨2 5/5⟩ − ⟨1 2/5⟩ = ⟨1 3/5⟩이에요.","그래서 3 − ⟨1 2/5⟩ = ⟨1 3/5⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#22','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C7',4,'sa','auto','⟨5 1/4⟩에서 분수 부분이 ⟨3/4⟩인 대분수를 뺐더니 ⟨2 1/2⟩이 되었어요. 뺀 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M5-1-u5-C7","difficulty":4,"kind":"sa","stem":"⟨5 1/4⟩에서 분수 부분이 ⟨3/4⟩인 대분수를 뺐더니 ⟨2 1/2⟩이 되었어요. 뺀 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["뺀 대분수는 ⟨5 1/4⟩ − ⟨2 1/2⟩로 구해요.","⟨5 1/4⟩ − ⟨2 1/2⟩ = ⟨2 3/4⟩이에요 — 분수 부분에서 1을 빌려 와요.","⟨2 3/4⟩의 자연수 부분은 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#23','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C8',4,'sa','auto','집과 도서관 사이는 ⟨1 3/4⟩ km예요. 민서는 집에서, 준우는 도서관에서 서로를 향해 각각 ⟨2/3⟩ km, ⟨5/6⟩ km를 걸었어요. 두 사람 사이에 남은 거리는 ⟨□/12⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M5-1-u5-C8","difficulty":4,"kind":"sa","stem":"집과 도서관 사이는 ⟨1 3/4⟩ km예요. 민서는 집에서, 준우는 도서관에서 서로를 향해 각각 ⟨2/3⟩ km, ⟨5/6⟩ km를 걸었어요. 두 사람 사이에 남은 거리는 ⟨□/12⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["두 사람이 걸은 거리는 ⟨2/3⟩ + ⟨5/6⟩ = ⟨1 1/2⟩ km예요.","남은 거리는 ⟨1 3/4⟩ − ⟨1 1/2⟩ = ⟨21/12⟩ − ⟨18/12⟩ = ⟨3/12⟩ km예요.","그래서 □는 3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#24','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C8',2,'mc','auto','학교까지 ⟨7/12⟩ km인 길로 왕복하면 모두 몇 km를 걷게 되나요?',ARRAY['M5-1-u5-X11','M5-1-u5-X13','M5-1-u5-X05']::text[],false,'{"seq":24,"concept":"M5-1-u5-C8","difficulty":2,"kind":"mc","stem":"학교까지 ⟨7/12⟩ km인 길로 왕복하면 모두 몇 km를 걷게 되나요?","options":[{"t":"⟨1 1/6⟩","correct":true},{"t":"⟨7/12⟩","mis":"M5-1-u5-X11"},{"t":"⟨1 1/4⟩","mis":"M5-1-u5-X13"},{"t":"⟨1/6⟩","mis":"M5-1-u5-X05"}],"explanation":["왕복은 갔다가 돌아오는 것 — 같은 길을 두 번 걸어요.","⟨7/12⟩ + ⟨7/12⟩ = ⟨1 1/6⟩이에요.","그래서 모두 ⟨1 1/6⟩ km예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_a#25','math',5,1,'u5','','g5_1_math_u5_review_a','unit_review','M5-1-u5-C8',3,'sa','auto','집에서 학교까지 ⟨1 1/4⟩ km예요. ⟨2/3⟩ km를 걸었다면 남은 거리는 ⟨□/12⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M5-1-u5-C8","difficulty":3,"kind":"sa","stem":"집에서 학교까지 ⟨1 1/4⟩ km예요. ⟨2/3⟩ km를 걸었다면 남은 거리는 ⟨□/12⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["남은 거리 = 전체 거리 − 걸은 거리예요.","⟨1 1/4⟩ − ⟨2/3⟩ = ⟨15/12⟩ − ⟨8/12⟩ = ⟨7/12⟩이에요.","그래서 □는 7이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#1','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C1',1,'mc','auto','⟨3/4⟩ − ⟨1/6⟩을 계산할 때 가장 먼저 할 일은 무엇인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X02']::text[],false,'{"seq":1,"concept":"M5-1-u5-C1","difficulty":1,"kind":"mc","stem":"⟨3/4⟩ − ⟨1/6⟩을 계산할 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"두 분수를 통분한다","correct":true},{"t":"분모끼리 뺀다","mis":"M5-1-u5-X01"},{"t":"분자끼리 뺀다","mis":"M5-1-u5-X01"},{"t":"분모를 곱한 뒤 분자를 뺀다","mis":"M5-1-u5-X02"}],"explanation":["⟨3/4⟩과 ⟨1/6⟩은 분모가 달라 조각의 크기가 달라요.","크기가 다른 조각은 한꺼번에 셀 수 없어요.","그래서 먼저 통분해 조각 크기를 맞춘 뒤 분자끼리 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#2','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C1',1,'sa','auto','⟨2/3⟩와 ⟨3/5⟩을 통분할 때 공통분모로 알맞은 가장 작은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M5-1-u5-C1","difficulty":1,"kind":"sa","stem":"⟨2/3⟩와 ⟨3/5⟩을 통분할 때 공통분모로 알맞은 가장 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["공통분모는 두 분모 3과 5의 공배수예요.","가장 작은 공배수는 최소공배수 15예요.","분모의 곱 3 × 5 = 15도 공통분모가 될 수 있지만 가장 작은 수는 15예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#3','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C1',2,'mc','auto','⟨1/2⟩과 ⟨1/5⟩을 그림처럼 10칸으로 맞추어 나타냈어요. 두 분수를 더하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X13']::text[],false,'{"seq":3,"concept":"M5-1-u5-C1","difficulty":2,"kind":"mc","stem":"⟨1/2⟩과 ⟨1/5⟩을 그림처럼 10칸으로 맞추어 나타냈어요. 두 분수를 더하면 얼마인가요?","options":[{"t":"⟨7/10⟩","correct":true},{"t":"⟨2/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨7/20⟩","mis":"M5-1-u5-X03"},{"t":"⟨4/5⟩","mis":"M5-1-u5-X13"}],"explanation":["⟨1/2⟩은 10칸 중 5칸, ⟨1/5⟩은 10칸 중 2칸이에요.","같은 크기의 칸이라 5칸 + 2칸 = 7칸으로 셀 수 있어요.","⟨5/10⟩ + ⟨2/10⟩ = ⟨7/10⟩이에요."],"asset":{"type":"fbar","bars":[{"den":10,"num":5,"label":"⟨1/2⟩"},{"den":10,"num":2,"label":"⟨1/5⟩"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#4','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C2',1,'mc','auto','⟨1/6⟩ + ⟨1/2⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X13']::text[],false,'{"seq":4,"concept":"M5-1-u5-C2","difficulty":1,"kind":"mc","stem":"⟨1/6⟩ + ⟨1/2⟩을 계산하면 얼마인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨1/4⟩","mis":"M5-1-u5-X01"},{"t":"⟨1/3⟩","mis":"M5-1-u5-X03"},{"t":"⟨5/6⟩","mis":"M5-1-u5-X13"}],"explanation":["공통분모 6으로 통분하면 ⟨1/6⟩ + ⟨3/6⟩이에요.","분모는 그대로 두고 분자끼리 더하면 ⟨1/6⟩ + ⟨3/6⟩ = ⟨4/6⟩ = ⟨2/3⟩예요.","그래서 ⟨1/6⟩ + ⟨1/2⟩ = ⟨2/3⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#5','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C2',1,'sa','auto','⟨1/4⟩ + ⟨3/8⟩을 분모 8로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M5-1-u5-C2","difficulty":1,"kind":"sa","stem":"⟨1/4⟩ + ⟨3/8⟩을 분모 8로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모를 8로 맞추면 ⟨2/8⟩ + ⟨3/8⟩이에요.","분모 8은 그대로 두고 분자끼리 2 + 3 = 5예요.","그래서 분자는 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#6','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C2',3,'mc','auto','텃밭의 ⟨1/6⟩에는 고추를, ⟨2/5⟩에는 가지를 심었어요. 아무것도 심지 않은 부분은 전체의 얼마인가요?',ARRAY['M5-1-u5-X11','M5-1-u5-X01']::text[],false,'{"seq":6,"concept":"M5-1-u5-C2","difficulty":3,"kind":"mc","stem":"텃밭의 ⟨1/6⟩에는 고추를, ⟨2/5⟩에는 가지를 심었어요. 아무것도 심지 않은 부분은 전체의 얼마인가요?","options":[{"t":"⟨13/30⟩","correct":true},{"t":"⟨17/30⟩","mis":"M5-1-u5-X11"},{"t":"⟨3/11⟩","mis":"M5-1-u5-X01"},{"t":"⟨8/11⟩","mis":"M5-1-u5-X01"}],"explanation":["심은 부분은 ⟨1/6⟩ + ⟨2/5⟩ = ⟨5/30⟩ + ⟨12/30⟩ = ⟨17/30⟩이에요.","전체 1은 ⟨30/30⟩이에요.","심지 않은 부분은 ⟨30/30⟩ − ⟨17/30⟩ = ⟨13/30⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#7','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C3',1,'sa','auto','⟨19/15⟩를 대분수로 나타내면 ⟨1 □/15⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M5-1-u5-C3","difficulty":1,"kind":"sa","stem":"⟨19/15⟩를 대분수로 나타내면 ⟨1 □/15⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["분모 15만큼 모이면 1이에요.","19칸에서 15칸을 덜어 내면 4칸이 남아요 — 19 − 15 = 4.","⟨19/15⟩ = ⟨1 4/15⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#8','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C3',2,'mc','auto','⟨4/5⟩ + ⟨1/2⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X05']::text[],false,'{"seq":8,"concept":"M5-1-u5-C3","difficulty":2,"kind":"mc","stem":"⟨4/5⟩ + ⟨1/2⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 3/10⟩","correct":true},{"t":"⟨5/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨13/20⟩","mis":"M5-1-u5-X03"},{"t":"⟨3/10⟩","mis":"M5-1-u5-X05"}],"explanation":["공통분모 10으로 통분하면 ⟨8/10⟩ + ⟨5/10⟩예요.","분자끼리 더하면 ⟨8/10⟩ + ⟨5/10⟩ = ⟨13/10⟩ — 분모만큼 모인 10칸이 1이에요.","⟨13/10⟩ = ⟨1 3/10⟩이므로 ⟨4/5⟩ + ⟨1/2⟩ = ⟨1 3/10⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#9','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C3',3,'sa','auto','⟨3/4⟩ + ⟨□/8⟩의 계산 결과가 1보다 클 때 □에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u5-C3","difficulty":3,"kind":"sa","stem":"⟨3/4⟩ + ⟨□/8⟩의 계산 결과가 1보다 클 때 □에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨3/4⟩ = ⟨6/8⟩이고, 1 = ⟨8/8⟩이에요.","6 + □가 8보다 커야 하니 □는 8 − 6 = 2보다 커요.","그래서 가장 작은 □는 3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#10','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C4',1,'mc','auto','⟨2 1/4⟩ + ⟨1 1/3⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X02']::text[],false,'{"seq":10,"concept":"M5-1-u5-C4","difficulty":1,"kind":"mc","stem":"⟨2 1/4⟩ + ⟨1 1/3⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3 7/12⟩","correct":true},{"t":"⟨3 2/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨3 7/24⟩","mis":"M5-1-u5-X03"},{"t":"⟨3 1/6⟩","mis":"M5-1-u5-X02"}],"explanation":["분수 부분을 12로 통분하면 ⟨2 3/12⟩ + ⟨1 4/12⟩예요.","자연수끼리 2 + 1 = 3, 분수끼리 ⟨3/12⟩ + ⟨4/12⟩ = ⟨7/12⟩이에요.","그래서 ⟨2 1/4⟩ + ⟨1 1/3⟩ = ⟨3 7/12⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#11','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C4',2,'mc','auto','⟨2 5/6⟩ + ⟨1 1/2⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X06']::text[],false,'{"seq":11,"concept":"M5-1-u5-C4","difficulty":2,"kind":"mc","stem":"⟨2 5/6⟩ + ⟨1 1/2⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 1/3⟩","correct":true},{"t":"⟨3 3/4⟩","mis":"M5-1-u5-X01"},{"t":"⟨3 2/3⟩","mis":"M5-1-u5-X03"},{"t":"⟨3 1/3⟩","mis":"M5-1-u5-X06"}],"explanation":["분수 부분을 6으로 통분하면 ⟨2 5/6⟩ + ⟨1 3/6⟩이에요.","자연수끼리 2 + 1 = 3, 분수끼리 ⟨5/6⟩ + ⟨3/6⟩ = ⟨8/6⟩ = ⟨1 1/3⟩이에요.","분수 부분에서 넘친 1을 자연수에 올리면 ⟨2 5/6⟩ + ⟨1 1/2⟩ = ⟨4 1/3⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#12','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C4',4,'sa','auto','분수 부분이 ⟨5/6⟩인 대분수에 ⟨2 2/3⟩를 더했더니 ⟨4 1/2⟩이 되었어요. 처음 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M5-1-u5-C4","difficulty":4,"kind":"sa","stem":"분수 부분이 ⟨5/6⟩인 대분수에 ⟨2 2/3⟩를 더했더니 ⟨4 1/2⟩이 되었어요. 처음 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["처음 대분수는 ⟨4 1/2⟩ − ⟨2 2/3⟩로 구해요.","⟨4 1/2⟩ − ⟨2 2/3⟩ = ⟨1 5/6⟩예요.","⟨1 5/6⟩의 자연수 부분은 1이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#13','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C5',1,'mc','auto','⟨4/5⟩ − ⟨1/2⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X13']::text[],false,'{"seq":13,"concept":"M5-1-u5-C5","difficulty":1,"kind":"mc","stem":"⟨4/5⟩ − ⟨1/2⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3/10⟩","correct":true},{"t":"1","mis":"M5-1-u5-X01"},{"t":"⟨2/5⟩","mis":"M5-1-u5-X13"},{"t":"⟨1/5⟩","mis":"M5-1-u5-X13"}],"explanation":["공통분모 10으로 통분하면 ⟨8/10⟩ − ⟨5/10⟩예요.","분모는 그대로 두고 분자끼리 빼면 ⟨8/10⟩ − ⟨5/10⟩ = ⟨3/10⟩이에요.","그래서 ⟨4/5⟩ − ⟨1/2⟩ = ⟨3/10⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#14','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C5',2,'sa','auto','⟨4/5⟩ − ⟨1/3⟩을 분모 15로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M5-1-u5-C5","difficulty":2,"kind":"sa","stem":"⟨4/5⟩ − ⟨1/3⟩을 분모 15로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["분모를 15로 맞추면 ⟨12/15⟩ − ⟨5/15⟩예요.","분모 15는 그대로 두고 분자끼리 12 − 5 = 7이에요.","그래서 분자는 7이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#15','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C5',3,'mc','auto','⟨2/3⟩ + ⟨1/4⟩ − ⟨1/2⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X13','M5-1-u5-X11']::text[],false,'{"seq":15,"concept":"M5-1-u5-C5","difficulty":3,"kind":"mc","stem":"⟨2/3⟩ + ⟨1/4⟩ − ⟨1/2⟩을 계산하면 얼마인가요?","options":[{"t":"⟨5/12⟩","correct":true},{"t":"⟨1/2⟩","mis":"M5-1-u5-X13"},{"t":"⟨1/3⟩","mis":"M5-1-u5-X13"},{"t":"⟨1 5/12⟩","mis":"M5-1-u5-X11"}],"explanation":["세 분수를 12로 통분하면 ⟨8/12⟩ + ⟨3/12⟩ − ⟨6/12⟩이에요.","앞에서부터 차례로 셈하면 ⟨8/12⟩ + ⟨3/12⟩ − ⟨6/12⟩ = ⟨5/12⟩예요.","그래서 ⟨2/3⟩ + ⟨1/4⟩ − ⟨1/2⟩ = ⟨5/12⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#16','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C6',1,'mc','auto','⟨2 2/5⟩를 가분수로 나타내면 어느 것인가요?',ARRAY['M5-1-u5-X07']::text[],false,'{"seq":16,"concept":"M5-1-u5-C6","difficulty":1,"kind":"mc","stem":"⟨2 2/5⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨12/5⟩","correct":true},{"t":"⟨22/5⟩","mis":"M5-1-u5-X07"},{"t":"⟨4/5⟩","mis":"M5-1-u5-X07"},{"t":"⟨10/5⟩","mis":"M5-1-u5-X07"}],"explanation":["자연수 2는 ⟨10/5⟩이에요 — 2 × 5 = 10.","여기에 ⟨2/5⟩를 더하면 분자는 10 + 2 = 12예요.","⟨2 2/5⟩ = ⟨12/5⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#17','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C6',2,'mc','auto','⟨4 5/6⟩ − ⟨2 1/2⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X02','M5-1-u5-X08']::text[],false,'{"seq":17,"concept":"M5-1-u5-C6","difficulty":2,"kind":"mc","stem":"⟨4 5/6⟩ − ⟨2 1/2⟩을 계산하면 얼마인가요?","options":[{"t":"⟨2 1/3⟩","correct":true},{"t":"3","mis":"M5-1-u5-X01"},{"t":"⟨2 2/3⟩","mis":"M5-1-u5-X02"},{"t":"⟨6 1/3⟩","mis":"M5-1-u5-X08"}],"explanation":["분수 부분을 6으로 통분하면 ⟨4 5/6⟩ − ⟨2 3/6⟩이에요.","자연수끼리 4 − 2 = 2, 분수끼리 ⟨5/6⟩ − ⟨3/6⟩ = ⟨2/6⟩예요.","그래서 ⟨4 5/6⟩ − ⟨2 1/2⟩ = ⟨2 1/3⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#18','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C6',3,'sa','auto','⟨6 7/8⟩ − ⟨2 1/4⟩ − ⟨1 1/2⟩을 계산한 값을 ⟨3 □/8⟩로 나타낼 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"M5-1-u5-C6","difficulty":3,"kind":"sa","stem":"⟨6 7/8⟩ − ⟨2 1/4⟩ − ⟨1 1/2⟩을 계산한 값을 ⟨3 □/8⟩로 나타낼 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["앞에서부터 셈해요 — ⟨6 7/8⟩ − ⟨2 1/4⟩ = ⟨4 5/8⟩예요.","⟨4 5/8⟩ − ⟨1 1/2⟩ = ⟨3 1/8⟩이에요.","⟨3 1/8⟩ = ⟨3 1/8⟩ — □는 1이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#19','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C7',3,'sa','auto','⟨4 1/6⟩ − ⟨1 2/3⟩를 가분수로 바꾸어 분모 6으로 계산하면 ⟨□/6⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M5-1-u5-C7","difficulty":3,"kind":"sa","stem":"⟨4 1/6⟩ − ⟨1 2/3⟩를 가분수로 바꾸어 분모 6으로 계산하면 ⟨□/6⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["⟨4 1/6⟩ = ⟨25/6⟩, ⟨1 2/3⟩ = ⟨10/6⟩이에요.","분자끼리 25 − 10 = 15예요.","⟨15/6⟩ = ⟨2 1/2⟩ — □는 15예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#20','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C7',2,'mc','auto','⟨5 1/6⟩ − ⟨2 3/4⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X09','M5-1-u5-X10']::text[],false,'{"seq":20,"concept":"M5-1-u5-C7","difficulty":2,"kind":"mc","stem":"⟨5 1/6⟩ − ⟨2 3/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨2 5/12⟩","correct":true},{"t":"⟨3 7/12⟩","mis":"M5-1-u5-X09"},{"t":"⟨3 5/12⟩","mis":"M5-1-u5-X10"},{"t":"⟨2 1/4⟩","mis":"M5-1-u5-X10"}],"explanation":["분수 부분을 12로 통분하면 ⟨5 2/12⟩ − ⟨2 9/12⟩예요.","분자 2에서 9를 뺄 수 없어 자연수에서 1을 빌리면 ⟨5 2/12⟩ = ⟨4 14/12⟩예요.","⟨4 14/12⟩ − ⟨2 9/12⟩ = ⟨2 5/12⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#21','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C7',2,'mc','auto','4 − ⟨2 3/8⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X10','M5-1-u5-X09']::text[],false,'{"seq":21,"concept":"M5-1-u5-C7","difficulty":2,"kind":"mc","stem":"4 − ⟨2 3/8⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 5/8⟩","correct":true},{"t":"⟨2 3/8⟩","mis":"M5-1-u5-X10"},{"t":"⟨1 3/8⟩","mis":"M5-1-u5-X09"},{"t":"⟨2 5/8⟩","mis":"M5-1-u5-X10"}],"explanation":["4에서 1을 빌려 4 = ⟨3 8/8⟩로 바꾸어요 — 1은 ⟨8/8⟩이에요.","⟨3 8/8⟩ − ⟨2 3/8⟩ = ⟨1 5/8⟩예요.","그래서 4 − ⟨2 3/8⟩ = ⟨1 5/8⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#22','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C7',4,'sa','auto','⟨6 1/3⟩에서 분수 부분이 ⟨5/6⟩인 대분수를 뺐더니 ⟨3 1/2⟩이 되었어요. 뺀 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M5-1-u5-C7","difficulty":4,"kind":"sa","stem":"⟨6 1/3⟩에서 분수 부분이 ⟨5/6⟩인 대분수를 뺐더니 ⟨3 1/2⟩이 되었어요. 뺀 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["뺀 대분수는 ⟨6 1/3⟩ − ⟨3 1/2⟩로 구해요.","⟨6 1/3⟩ − ⟨3 1/2⟩ = ⟨2 5/6⟩예요 — 분수 부분에서 1을 빌려 와요.","⟨2 5/6⟩의 자연수 부분은 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#23','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C8',4,'sa','auto','집과 도서관 사이는 ⟨1 1/2⟩ km예요. 민서는 집에서, 준우는 도서관에서 서로를 향해 각각 ⟨1/3⟩ km, ⟨3/4⟩ km를 걸었어요. 두 사람 사이에 남은 거리는 ⟨□/12⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M5-1-u5-C8","difficulty":4,"kind":"sa","stem":"집과 도서관 사이는 ⟨1 1/2⟩ km예요. 민서는 집에서, 준우는 도서관에서 서로를 향해 각각 ⟨1/3⟩ km, ⟨3/4⟩ km를 걸었어요. 두 사람 사이에 남은 거리는 ⟨□/12⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["두 사람이 걸은 거리는 ⟨1/3⟩ + ⟨3/4⟩ = ⟨1 1/12⟩ km예요.","남은 거리는 ⟨1 1/2⟩ − ⟨1 1/12⟩ = ⟨18/12⟩ − ⟨13/12⟩ = ⟨5/12⟩ km예요.","그래서 □는 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#24','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C8',2,'mc','auto','학교까지 ⟨5/8⟩ km인 길로 왕복하면 모두 몇 km를 걷게 되나요?',ARRAY['M5-1-u5-X11','M5-1-u5-X13','M5-1-u5-X05']::text[],false,'{"seq":24,"concept":"M5-1-u5-C8","difficulty":2,"kind":"mc","stem":"학교까지 ⟨5/8⟩ km인 길로 왕복하면 모두 몇 km를 걷게 되나요?","options":[{"t":"⟨1 1/4⟩","correct":true},{"t":"⟨5/8⟩","mis":"M5-1-u5-X11"},{"t":"⟨1 3/8⟩","mis":"M5-1-u5-X13"},{"t":"⟨1/4⟩","mis":"M5-1-u5-X05"}],"explanation":["왕복은 갔다가 돌아오는 것 — 같은 길을 두 번 걸어요.","⟨5/8⟩ + ⟨5/8⟩ = ⟨1 1/4⟩이에요.","그래서 모두 ⟨1 1/4⟩ km예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_b#25','math',5,1,'u5','','g5_1_math_u5_review_b','unit_review','M5-1-u5-C8',3,'sa','auto','집에서 학교까지 ⟨1 1/6⟩ km예요. ⟨3/4⟩ km를 걸었다면 남은 거리는 ⟨□/12⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M5-1-u5-C8","difficulty":3,"kind":"sa","stem":"집에서 학교까지 ⟨1 1/6⟩ km예요. ⟨3/4⟩ km를 걸었다면 남은 거리는 ⟨□/12⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["남은 거리 = 전체 거리 − 걸은 거리예요.","⟨1 1/6⟩ − ⟨3/4⟩ = ⟨14/12⟩ − ⟨9/12⟩ = ⟨5/12⟩예요.","그래서 □는 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#1','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C1',1,'mc','auto','⟨1/3⟩ + ⟨1/5⟩을 계산할 때 가장 먼저 할 일은 무엇인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X02']::text[],false,'{"seq":1,"concept":"M5-1-u5-C1","difficulty":1,"kind":"mc","stem":"⟨1/3⟩ + ⟨1/5⟩을 계산할 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"두 분수를 통분한다","correct":true},{"t":"분모끼리 더한다","mis":"M5-1-u5-X01"},{"t":"분자끼리 더한다","mis":"M5-1-u5-X01"},{"t":"분모를 곱한 뒤 분자를 더한다","mis":"M5-1-u5-X02"}],"explanation":["⟨1/3⟩과 ⟨1/5⟩은 분모가 달라 조각의 크기가 달라요.","크기가 다른 조각은 한꺼번에 셀 수 없어요.","그래서 먼저 통분해 조각 크기를 맞춘 뒤 분자끼리 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#2','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C1',1,'sa','auto','⟨5/8⟩와 ⟨1/6⟩을 통분할 때 공통분모로 알맞은 가장 작은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M5-1-u5-C1","difficulty":1,"kind":"sa","stem":"⟨5/8⟩와 ⟨1/6⟩을 통분할 때 공통분모로 알맞은 가장 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["공통분모는 두 분모 8과 6의 공배수예요.","가장 작은 공배수는 최소공배수 24예요.","분모의 곱 8 × 6 = 48도 공통분모가 될 수 있지만 가장 작은 수는 24예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#3','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C1',2,'mc','auto','⟨1/3⟩과 ⟨1/6⟩을 그림처럼 6칸으로 맞추어 나타냈어요. 두 분수를 더하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X13']::text[],false,'{"seq":3,"concept":"M5-1-u5-C1","difficulty":2,"kind":"mc","stem":"⟨1/3⟩과 ⟨1/6⟩을 그림처럼 6칸으로 맞추어 나타냈어요. 두 분수를 더하면 얼마인가요?","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨2/9⟩","mis":"M5-1-u5-X01"},{"t":"⟨1/4⟩","mis":"M5-1-u5-X03"},{"t":"⟨2/3⟩","mis":"M5-1-u5-X13"}],"explanation":["⟨1/3⟩은 6칸 중 2칸, ⟨1/6⟩은 6칸 중 1칸이에요.","같은 크기의 칸이라 2칸 + 1칸 = 3칸으로 셀 수 있어요.","⟨2/6⟩ + ⟨1/6⟩ = ⟨1/2⟩이에요."],"asset":{"type":"fbar","bars":[{"den":6,"num":2,"label":"⟨1/3⟩"},{"den":6,"num":1,"label":"⟨1/6⟩"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#4','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C2',1,'mc','auto','⟨3/8⟩ + ⟨1/3⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X02']::text[],false,'{"seq":4,"concept":"M5-1-u5-C2","difficulty":1,"kind":"mc","stem":"⟨3/8⟩ + ⟨1/3⟩을 계산하면 얼마인가요?","options":[{"t":"⟨17/24⟩","correct":true},{"t":"⟨4/11⟩","mis":"M5-1-u5-X01"},{"t":"⟨17/48⟩","mis":"M5-1-u5-X03"},{"t":"⟨1/6⟩","mis":"M5-1-u5-X02"}],"explanation":["공통분모 24로 통분하면 ⟨9/24⟩ + ⟨8/24⟩이에요.","분모는 그대로 두고 분자끼리 더하면 ⟨9/24⟩ + ⟨8/24⟩ = ⟨17/24⟩이에요.","그래서 ⟨3/8⟩ + ⟨1/3⟩ = ⟨17/24⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#5','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C2',1,'sa','auto','⟨1/6⟩ + ⟨3/4⟩을 분모 12로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M5-1-u5-C2","difficulty":1,"kind":"sa","stem":"⟨1/6⟩ + ⟨3/4⟩을 분모 12로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["분모를 12로 맞추면 ⟨2/12⟩ + ⟨9/12⟩예요.","분모 12는 그대로 두고 분자끼리 2 + 9 = 11이에요.","그래서 분자는 11이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#6','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C2',3,'mc','auto','텃밭의 ⟨3/10⟩에는 오이를, ⟨1/4⟩에는 호박을 심었어요. 아무것도 심지 않은 부분은 전체의 얼마인가요?',ARRAY['M5-1-u5-X11','M5-1-u5-X01']::text[],false,'{"seq":6,"concept":"M5-1-u5-C2","difficulty":3,"kind":"mc","stem":"텃밭의 ⟨3/10⟩에는 오이를, ⟨1/4⟩에는 호박을 심었어요. 아무것도 심지 않은 부분은 전체의 얼마인가요?","options":[{"t":"⟨9/20⟩","correct":true},{"t":"⟨11/20⟩","mis":"M5-1-u5-X11"},{"t":"⟨2/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨5/7⟩","mis":"M5-1-u5-X01"}],"explanation":["심은 부분은 ⟨3/10⟩ + ⟨1/4⟩ = ⟨6/20⟩ + ⟨5/20⟩ = ⟨11/20⟩이에요.","전체 1은 ⟨20/20⟩이에요.","심지 않은 부분은 ⟨20/20⟩ − ⟨11/20⟩ = ⟨9/20⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#7','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C3',1,'sa','auto','⟨13/8⟩을 대분수로 나타내면 ⟨1 □/8⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M5-1-u5-C3","difficulty":1,"kind":"sa","stem":"⟨13/8⟩을 대분수로 나타내면 ⟨1 □/8⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모 8만큼 모이면 1이에요.","13칸에서 8칸을 덜어 내면 5칸이 남아요 — 13 − 8 = 5.","⟨13/8⟩ = ⟨1 5/8⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#8','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C3',2,'mc','auto','⟨5/6⟩ + ⟨3/8⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X05']::text[],false,'{"seq":8,"concept":"M5-1-u5-C3","difficulty":2,"kind":"mc","stem":"⟨5/6⟩ + ⟨3/8⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 5/24⟩","correct":true},{"t":"⟨4/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨29/48⟩","mis":"M5-1-u5-X03"},{"t":"⟨5/24⟩","mis":"M5-1-u5-X05"}],"explanation":["공통분모 24로 통분하면 ⟨20/24⟩ + ⟨9/24⟩예요.","분자끼리 더하면 ⟨20/24⟩ + ⟨9/24⟩ = ⟨29/24⟩ — 분모만큼 모인 24칸이 1이에요.","⟨29/24⟩ = ⟨1 5/24⟩이므로 ⟨5/6⟩ + ⟨3/8⟩ = ⟨1 5/24⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#9','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C3',3,'sa','auto','⟨3/5⟩ + ⟨□/10⟩의 계산 결과가 1보다 클 때 □에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u5-C3","difficulty":3,"kind":"sa","stem":"⟨3/5⟩ + ⟨□/10⟩의 계산 결과가 1보다 클 때 □에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨3/5⟩ = ⟨6/10⟩이고, 1 = ⟨10/10⟩이에요.","6 + □가 10보다 커야 하니 □는 10 − 6 = 4보다 커요.","그래서 가장 작은 □는 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#10','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C4',1,'mc','auto','⟨3 1/6⟩ + ⟨1 1/2⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X08']::text[],false,'{"seq":10,"concept":"M5-1-u5-C4","difficulty":1,"kind":"mc","stem":"⟨3 1/6⟩ + ⟨1 1/2⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 2/3⟩","correct":true},{"t":"⟨4 1/4⟩","mis":"M5-1-u5-X01"},{"t":"⟨4 1/3⟩","mis":"M5-1-u5-X03"},{"t":"⟨3 2/3⟩","mis":"M5-1-u5-X08"}],"explanation":["분수 부분을 6으로 통분하면 ⟨3 1/6⟩ + ⟨1 3/6⟩이에요.","자연수끼리 3 + 1 = 4, 분수끼리 ⟨1/6⟩ + ⟨3/6⟩ = ⟨4/6⟩예요.","그래서 ⟨3 1/6⟩ + ⟨1 1/2⟩ = ⟨4 2/3⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#11','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C4',2,'mc','auto','⟨1 3/4⟩ + ⟨3 2/5⟩를 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X06']::text[],false,'{"seq":11,"concept":"M5-1-u5-C4","difficulty":2,"kind":"mc","stem":"⟨1 3/4⟩ + ⟨3 2/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨5 3/20⟩","correct":true},{"t":"⟨4 5/9⟩","mis":"M5-1-u5-X01"},{"t":"⟨4 23/40⟩","mis":"M5-1-u5-X03"},{"t":"⟨4 3/20⟩","mis":"M5-1-u5-X06"}],"explanation":["분수 부분을 20으로 통분하면 ⟨1 15/20⟩ + ⟨3 8/20⟩이에요.","자연수끼리 1 + 3 = 4, 분수끼리 ⟨15/20⟩ + ⟨8/20⟩ = ⟨23/20⟩ = ⟨1 3/20⟩이에요.","분수 부분에서 넘친 1을 자연수에 올리면 ⟨1 3/4⟩ + ⟨3 2/5⟩ = ⟨5 3/20⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#12','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C4',4,'sa','auto','분수 부분이 ⟨2/5⟩인 대분수에 ⟨1 7/10⟩을 더했더니 ⟨4 1/10⟩이 되었어요. 처음 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M5-1-u5-C4","difficulty":4,"kind":"sa","stem":"분수 부분이 ⟨2/5⟩인 대분수에 ⟨1 7/10⟩을 더했더니 ⟨4 1/10⟩이 되었어요. 처음 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["처음 대분수는 ⟨4 1/10⟩ − ⟨1 7/10⟩로 구해요.","⟨4 1/10⟩ − ⟨1 7/10⟩ = ⟨2 2/5⟩예요.","⟨2 2/5⟩의 자연수 부분은 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#13','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C5',1,'mc','auto','⟨5/6⟩ − ⟨1/4⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X02','M5-1-u5-X13']::text[],false,'{"seq":13,"concept":"M5-1-u5-C5","difficulty":1,"kind":"mc","stem":"⟨5/6⟩ − ⟨1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨7/12⟩","correct":true},{"t":"2","mis":"M5-1-u5-X01"},{"t":"⟨1/3⟩","mis":"M5-1-u5-X02"},{"t":"⟨2/3⟩","mis":"M5-1-u5-X13"}],"explanation":["공통분모 12로 통분하면 ⟨10/12⟩ − ⟨3/12⟩이에요.","분모는 그대로 두고 분자끼리 빼면 ⟨10/12⟩ − ⟨3/12⟩ = ⟨7/12⟩이에요.","그래서 ⟨5/6⟩ − ⟨1/4⟩ = ⟨7/12⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#14','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C5',2,'sa','auto','⟨5/8⟩ − ⟨1/6⟩을 분모 24로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M5-1-u5-C5","difficulty":2,"kind":"sa","stem":"⟨5/8⟩ − ⟨1/6⟩을 분모 24로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["분모를 24로 맞추면 ⟨15/24⟩ − ⟨4/24⟩예요.","분모 24는 그대로 두고 분자끼리 15 − 4 = 11이에요.","그래서 분자는 11이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#15','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C5',3,'mc','auto','⟨5/6⟩ − ⟨1/2⟩ + ⟨1/4⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X13','M5-1-u5-X11']::text[],false,'{"seq":15,"concept":"M5-1-u5-C5","difficulty":3,"kind":"mc","stem":"⟨5/6⟩ − ⟨1/2⟩ + ⟨1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨7/12⟩","correct":true},{"t":"⟨2/3⟩","mis":"M5-1-u5-X13"},{"t":"⟨1/2⟩","mis":"M5-1-u5-X13"},{"t":"⟨1 7/12⟩","mis":"M5-1-u5-X11"}],"explanation":["세 분수를 12로 통분하면 ⟨10/12⟩ − ⟨6/12⟩ + ⟨3/12⟩이에요.","앞에서부터 차례로 셈하면 ⟨10/12⟩ − ⟨6/12⟩ + ⟨3/12⟩ = ⟨7/12⟩이에요.","그래서 ⟨5/6⟩ − ⟨1/2⟩ + ⟨1/4⟩ = ⟨7/12⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#16','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C6',1,'mc','auto','⟨4 1/3⟩을 가분수로 나타내면 어느 것인가요?',ARRAY['M5-1-u5-X07']::text[],false,'{"seq":16,"concept":"M5-1-u5-C6","difficulty":1,"kind":"mc","stem":"⟨4 1/3⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨13/3⟩","correct":true},{"t":"⟨41/3⟩","mis":"M5-1-u5-X07"},{"t":"⟨5/3⟩","mis":"M5-1-u5-X07"},{"t":"⟨12/3⟩","mis":"M5-1-u5-X07"}],"explanation":["자연수 4는 ⟨12/3⟩예요 — 4 × 3 = 12.","여기에 ⟨1/3⟩을 더하면 분자는 12 + 1 = 13이에요.","⟨4 1/3⟩ = ⟨13/3⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#17','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C6',2,'mc','auto','⟨5 2/3⟩ − ⟨2 1/4⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X02','M5-1-u5-X08']::text[],false,'{"seq":17,"concept":"M5-1-u5-C6","difficulty":2,"kind":"mc","stem":"⟨5 2/3⟩ − ⟨2 1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3 5/12⟩","correct":true},{"t":"4","mis":"M5-1-u5-X01"},{"t":"⟨3 1/12⟩","mis":"M5-1-u5-X02"},{"t":"⟨7 5/12⟩","mis":"M5-1-u5-X08"}],"explanation":["분수 부분을 12로 통분하면 ⟨5 8/12⟩ − ⟨2 3/12⟩이에요.","자연수끼리 5 − 2 = 3, 분수끼리 ⟨8/12⟩ − ⟨3/12⟩ = ⟨5/12⟩예요.","그래서 ⟨5 2/3⟩ − ⟨2 1/4⟩ = ⟨3 5/12⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#18','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C6',3,'sa','auto','⟨5 9/10⟩ − ⟨1 1/2⟩ − ⟨2 1/5⟩을 계산한 값을 ⟨2 □/10⟩로 나타낼 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"M5-1-u5-C6","difficulty":3,"kind":"sa","stem":"⟨5 9/10⟩ − ⟨1 1/2⟩ − ⟨2 1/5⟩을 계산한 값을 ⟨2 □/10⟩로 나타낼 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["앞에서부터 셈해요 — ⟨5 9/10⟩ − ⟨1 1/2⟩ = ⟨4 2/5⟩예요.","⟨4 2/5⟩ − ⟨2 1/5⟩ = ⟨2 1/5⟩이에요.","⟨2 1/5⟩ = ⟨2 2/10⟩ — □는 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#19','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C7',3,'sa','auto','⟨3 1/4⟩ − ⟨1 5/8⟩를 가분수로 바꾸어 분모 8로 계산하면 ⟨□/8⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M5-1-u5-C7","difficulty":3,"kind":"sa","stem":"⟨3 1/4⟩ − ⟨1 5/8⟩를 가분수로 바꾸어 분모 8로 계산하면 ⟨□/8⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["⟨3 1/4⟩ = ⟨26/8⟩, ⟨1 5/8⟩ = ⟨13/8⟩이에요.","분자끼리 26 − 13 = 13이에요.","⟨13/8⟩ = ⟨1 5/8⟩ — □는 13이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#20','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C7',2,'mc','auto','⟨3 1/3⟩ − ⟨1 4/5⟩를 계산하면 얼마인가요?',ARRAY['M5-1-u5-X09','M5-1-u5-X10']::text[],false,'{"seq":20,"concept":"M5-1-u5-C7","difficulty":2,"kind":"mc","stem":"⟨3 1/3⟩ − ⟨1 4/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1 8/15⟩","correct":true},{"t":"⟨2 7/15⟩","mis":"M5-1-u5-X09"},{"t":"⟨2 8/15⟩","mis":"M5-1-u5-X10"},{"t":"⟨1 1/5⟩","mis":"M5-1-u5-X10"}],"explanation":["분수 부분을 15로 통분하면 ⟨3 5/15⟩ − ⟨1 12/15⟩예요.","분자 5에서 12를 뺄 수 없어 자연수에서 1을 빌리면 ⟨3 5/15⟩ = ⟨2 20/15⟩이에요.","⟨2 20/15⟩ − ⟨1 12/15⟩ = ⟨1 8/15⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#21','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C7',2,'mc','auto','5 − ⟨1 5/6⟩를 계산하면 얼마인가요?',ARRAY['M5-1-u5-X10','M5-1-u5-X09']::text[],false,'{"seq":21,"concept":"M5-1-u5-C7","difficulty":2,"kind":"mc","stem":"5 − ⟨1 5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨3 1/6⟩","correct":true},{"t":"⟨4 5/6⟩","mis":"M5-1-u5-X10"},{"t":"⟨3 5/6⟩","mis":"M5-1-u5-X09"},{"t":"⟨4 1/6⟩","mis":"M5-1-u5-X10"}],"explanation":["5에서 1을 빌려 5 = ⟨4 6/6⟩으로 바꾸어요 — 1은 ⟨6/6⟩이에요.","⟨4 6/6⟩ − ⟨1 5/6⟩ = ⟨3 1/6⟩이에요.","그래서 5 − ⟨1 5/6⟩ = ⟨3 1/6⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#22','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C7',4,'sa','auto','⟨4 1/5⟩에서 분수 부분이 ⟨7/10⟩인 대분수를 뺐더니 ⟨1 1/2⟩이 되었어요. 뺀 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M5-1-u5-C7","difficulty":4,"kind":"sa","stem":"⟨4 1/5⟩에서 분수 부분이 ⟨7/10⟩인 대분수를 뺐더니 ⟨1 1/2⟩이 되었어요. 뺀 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["뺀 대분수는 ⟨4 1/5⟩ − ⟨1 1/2⟩로 구해요.","⟨4 1/5⟩ − ⟨1 1/2⟩ = ⟨2 7/10⟩이에요 — 분수 부분에서 1을 빌려 와요.","⟨2 7/10⟩의 자연수 부분은 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#23','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C8',4,'sa','auto','집과 도서관 사이는 ⟨1 4/5⟩ km예요. 민서는 집에서, 준우는 도서관에서 서로를 향해 각각 ⟨1/2⟩ km, ⟨7/10⟩ km를 걸었어요. 두 사람 사이에 남은 거리는 ⟨□/10⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M5-1-u5-C8","difficulty":4,"kind":"sa","stem":"집과 도서관 사이는 ⟨1 4/5⟩ km예요. 민서는 집에서, 준우는 도서관에서 서로를 향해 각각 ⟨1/2⟩ km, ⟨7/10⟩ km를 걸었어요. 두 사람 사이에 남은 거리는 ⟨□/10⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["두 사람이 걸은 거리는 ⟨1/2⟩ + ⟨7/10⟩ = ⟨1 1/5⟩ km예요.","남은 거리는 ⟨1 4/5⟩ − ⟨1 1/5⟩ = ⟨18/10⟩ − ⟨12/10⟩ = ⟨6/10⟩ km예요.","그래서 □는 6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#24','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C8',2,'mc','auto','학교까지 ⟨3/4⟩ km인 길로 왕복하면 모두 몇 km를 걷게 되나요?',ARRAY['M5-1-u5-X11','M5-1-u5-X13','M5-1-u5-X05']::text[],false,'{"seq":24,"concept":"M5-1-u5-C8","difficulty":2,"kind":"mc","stem":"학교까지 ⟨3/4⟩ km인 길로 왕복하면 모두 몇 km를 걷게 되나요?","options":[{"t":"⟨1 1/2⟩","correct":true},{"t":"⟨3/4⟩","mis":"M5-1-u5-X11"},{"t":"⟨1 3/4⟩","mis":"M5-1-u5-X13"},{"t":"⟨1/2⟩","mis":"M5-1-u5-X05"}],"explanation":["왕복은 갔다가 돌아오는 것 — 같은 길을 두 번 걸어요.","⟨3/4⟩ + ⟨3/4⟩ = ⟨1 1/2⟩이에요.","그래서 모두 ⟨1 1/2⟩ km예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_c#25','math',5,1,'u5','','g5_1_math_u5_review_c','unit_review','M5-1-u5-C8',3,'sa','auto','집에서 학교까지 ⟨1 3/10⟩ km예요. ⟨4/5⟩ km를 걸었다면 남은 거리는 ⟨□/10⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M5-1-u5-C8","difficulty":3,"kind":"sa","stem":"집에서 학교까지 ⟨1 3/10⟩ km예요. ⟨4/5⟩ km를 걸었다면 남은 거리는 ⟨□/10⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["남은 거리 = 전체 거리 − 걸은 거리예요.","⟨1 3/10⟩ − ⟨4/5⟩ = ⟨13/10⟩ − ⟨8/10⟩ = ⟨5/10⟩예요.","그래서 □는 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#1','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C1',1,'mc','auto','⟨5/6⟩ − ⟨3/8⟩을 계산할 때 가장 먼저 할 일은 무엇인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X02']::text[],false,'{"seq":1,"concept":"M5-1-u5-C1","difficulty":1,"kind":"mc","stem":"⟨5/6⟩ − ⟨3/8⟩을 계산할 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"두 분수를 통분한다","correct":true},{"t":"분모끼리 뺀다","mis":"M5-1-u5-X01"},{"t":"분자끼리 뺀다","mis":"M5-1-u5-X01"},{"t":"분모를 곱한 뒤 분자를 뺀다","mis":"M5-1-u5-X02"}],"explanation":["⟨5/6⟩와 ⟨3/8⟩은 분모가 달라 조각의 크기가 달라요.","크기가 다른 조각은 한꺼번에 셀 수 없어요.","그래서 먼저 통분해 조각 크기를 맞춘 뒤 분자끼리 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#2','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C1',1,'sa','auto','⟨3/10⟩과 ⟨1/4⟩을 통분할 때 공통분모로 알맞은 가장 작은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M5-1-u5-C1","difficulty":1,"kind":"sa","stem":"⟨3/10⟩과 ⟨1/4⟩을 통분할 때 공통분모로 알맞은 가장 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["공통분모는 두 분모 10과 4의 공배수예요.","가장 작은 공배수는 최소공배수 20이에요.","분모의 곱 10 × 4 = 40도 공통분모가 될 수 있지만 가장 작은 수는 20이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#3','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C1',2,'mc','auto','⟨1/4⟩과 ⟨1/6⟩을 그림처럼 12칸으로 맞추어 나타냈어요. 두 분수를 더하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X13']::text[],false,'{"seq":3,"concept":"M5-1-u5-C1","difficulty":2,"kind":"mc","stem":"⟨1/4⟩과 ⟨1/6⟩을 그림처럼 12칸으로 맞추어 나타냈어요. 두 분수를 더하면 얼마인가요?","options":[{"t":"⟨5/12⟩","correct":true},{"t":"⟨1/5⟩","mis":"M5-1-u5-X01"},{"t":"⟨5/24⟩","mis":"M5-1-u5-X03"},{"t":"⟨1/2⟩","mis":"M5-1-u5-X13"}],"explanation":["⟨1/4⟩은 12칸 중 3칸, ⟨1/6⟩은 12칸 중 2칸이에요.","같은 크기의 칸이라 3칸 + 2칸 = 5칸으로 셀 수 있어요.","⟨3/12⟩ + ⟨2/12⟩ = ⟨5/12⟩예요."],"asset":{"type":"fbar","bars":[{"den":12,"num":3,"label":"⟨1/4⟩"},{"den":12,"num":2,"label":"⟨1/6⟩"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#4','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C2',1,'mc','auto','⟨2/9⟩ + ⟨1/6⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X02']::text[],false,'{"seq":4,"concept":"M5-1-u5-C2","difficulty":1,"kind":"mc","stem":"⟨2/9⟩ + ⟨1/6⟩을 계산하면 얼마인가요?","options":[{"t":"⟨7/18⟩","correct":true},{"t":"⟨1/5⟩","mis":"M5-1-u5-X01"},{"t":"⟨7/36⟩","mis":"M5-1-u5-X03"},{"t":"⟨1/6⟩","mis":"M5-1-u5-X02"}],"explanation":["공통분모 18로 통분하면 ⟨4/18⟩ + ⟨3/18⟩이에요.","분모는 그대로 두고 분자끼리 더하면 ⟨4/18⟩ + ⟨3/18⟩ = ⟨7/18⟩이에요.","그래서 ⟨2/9⟩ + ⟨1/6⟩ = ⟨7/18⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#5','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C2',1,'sa','auto','⟨2/7⟩ + ⟨1/2⟩을 분모 14로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M5-1-u5-C2","difficulty":1,"kind":"sa","stem":"⟨2/7⟩ + ⟨1/2⟩을 분모 14로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["분모를 14로 맞추면 ⟨4/14⟩ + ⟨7/14⟩이에요.","분모 14는 그대로 두고 분자끼리 4 + 7 = 11이에요.","그래서 분자는 11이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#6','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C2',3,'mc','auto','텃밭의 ⟨1/8⟩에는 파를, ⟨1/3⟩에는 배추를 심었어요. 아무것도 심지 않은 부분은 전체의 얼마인가요?',ARRAY['M5-1-u5-X11','M5-1-u5-X01']::text[],false,'{"seq":6,"concept":"M5-1-u5-C2","difficulty":3,"kind":"mc","stem":"텃밭의 ⟨1/8⟩에는 파를, ⟨1/3⟩에는 배추를 심었어요. 아무것도 심지 않은 부분은 전체의 얼마인가요?","options":[{"t":"⟨13/24⟩","correct":true},{"t":"⟨11/24⟩","mis":"M5-1-u5-X11"},{"t":"⟨2/11⟩","mis":"M5-1-u5-X01"},{"t":"⟨9/11⟩","mis":"M5-1-u5-X01"}],"explanation":["심은 부분은 ⟨1/8⟩ + ⟨1/3⟩ = ⟨3/24⟩ + ⟨8/24⟩ = ⟨11/24⟩이에요.","전체 1은 ⟨24/24⟩예요.","심지 않은 부분은 ⟨24/24⟩ − ⟨11/24⟩ = ⟨13/24⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#7','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C3',1,'sa','auto','⟨11/9⟩을 대분수로 나타내면 ⟨1 □/9⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M5-1-u5-C3","difficulty":1,"kind":"sa","stem":"⟨11/9⟩을 대분수로 나타내면 ⟨1 □/9⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["분모 9만큼 모이면 1이에요.","11칸에서 9칸을 덜어 내면 2칸이 남아요 — 11 − 9 = 2.","⟨11/9⟩ = ⟨1 2/9⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#8','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C3',2,'mc','auto','⟨7/10⟩ + ⟨3/4⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X05']::text[],false,'{"seq":8,"concept":"M5-1-u5-C3","difficulty":2,"kind":"mc","stem":"⟨7/10⟩ + ⟨3/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 9/20⟩","correct":true},{"t":"⟨5/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨29/40⟩","mis":"M5-1-u5-X03"},{"t":"⟨9/20⟩","mis":"M5-1-u5-X05"}],"explanation":["공통분모 20으로 통분하면 ⟨14/20⟩ + ⟨15/20⟩예요.","분자끼리 더하면 ⟨14/20⟩ + ⟨15/20⟩ = ⟨29/20⟩ — 분모만큼 모인 20칸이 1이에요.","⟨29/20⟩ = ⟨1 9/20⟩이므로 ⟨7/10⟩ + ⟨3/4⟩ = ⟨1 9/20⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#9','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C3',3,'sa','auto','⟨5/6⟩ + ⟨□/18⟩의 계산 결과가 1보다 클 때 □에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u5-C3","difficulty":3,"kind":"sa","stem":"⟨5/6⟩ + ⟨□/18⟩의 계산 결과가 1보다 클 때 □에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨5/6⟩ = ⟨15/18⟩이고, 1 = ⟨18/18⟩이에요.","15 + □가 18보다 커야 하니 □는 18 − 15 = 3보다 커요.","그래서 가장 작은 □는 4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#10','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C4',1,'mc','auto','⟨1 2/5⟩ + ⟨2 1/4⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X02']::text[],false,'{"seq":10,"concept":"M5-1-u5-C4","difficulty":1,"kind":"mc","stem":"⟨1 2/5⟩ + ⟨2 1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3 13/20⟩","correct":true},{"t":"⟨3 1/3⟩","mis":"M5-1-u5-X01"},{"t":"⟨3 13/40⟩","mis":"M5-1-u5-X03"},{"t":"⟨3 3/20⟩","mis":"M5-1-u5-X02"}],"explanation":["분수 부분을 20으로 통분하면 ⟨1 8/20⟩ + ⟨2 5/20⟩예요.","자연수끼리 1 + 2 = 3, 분수끼리 ⟨8/20⟩ + ⟨5/20⟩ = ⟨13/20⟩이에요.","그래서 ⟨1 2/5⟩ + ⟨2 1/4⟩ = ⟨3 13/20⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#11','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C4',2,'mc','auto','⟨2 7/8⟩ + ⟨1 1/4⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X06']::text[],false,'{"seq":11,"concept":"M5-1-u5-C4","difficulty":2,"kind":"mc","stem":"⟨2 7/8⟩ + ⟨1 1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 1/8⟩","correct":true},{"t":"⟨3 2/3⟩","mis":"M5-1-u5-X01"},{"t":"⟨3 9/16⟩","mis":"M5-1-u5-X03"},{"t":"⟨3 1/8⟩","mis":"M5-1-u5-X06"}],"explanation":["분수 부분을 8로 통분하면 ⟨2 7/8⟩ + ⟨1 2/8⟩예요.","자연수끼리 2 + 1 = 3, 분수끼리 ⟨7/8⟩ + ⟨2/8⟩ = ⟨9/8⟩ = ⟨1 1/8⟩이에요.","분수 부분에서 넘친 1을 자연수에 올리면 ⟨2 7/8⟩ + ⟨1 1/4⟩ = ⟨4 1/8⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#12','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C4',4,'sa','auto','분수 부분이 ⟨3/4⟩인 대분수에 ⟨1 5/6⟩를 더했더니 ⟨4 7/12⟩이 되었어요. 처음 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M5-1-u5-C4","difficulty":4,"kind":"sa","stem":"분수 부분이 ⟨3/4⟩인 대분수에 ⟨1 5/6⟩를 더했더니 ⟨4 7/12⟩이 되었어요. 처음 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["처음 대분수는 ⟨4 7/12⟩ − ⟨1 5/6⟩로 구해요.","⟨4 7/12⟩ − ⟨1 5/6⟩ = ⟨2 3/4⟩이에요.","⟨2 3/4⟩의 자연수 부분은 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#13','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C5',1,'mc','auto','⟨7/8⟩ − ⟨1/3⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X02','M5-1-u5-X13']::text[],false,'{"seq":13,"concept":"M5-1-u5-C5","difficulty":1,"kind":"mc","stem":"⟨7/8⟩ − ⟨1/3⟩을 계산하면 얼마인가요?","options":[{"t":"⟨13/24⟩","correct":true},{"t":"⟨1 1/5⟩","mis":"M5-1-u5-X01"},{"t":"⟨1/4⟩","mis":"M5-1-u5-X02"},{"t":"⟨7/12⟩","mis":"M5-1-u5-X13"}],"explanation":["공통분모 24로 통분하면 ⟨21/24⟩ − ⟨8/24⟩이에요.","분모는 그대로 두고 분자끼리 빼면 ⟨21/24⟩ − ⟨8/24⟩ = ⟨13/24⟩이에요.","그래서 ⟨7/8⟩ − ⟨1/3⟩ = ⟨13/24⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#14','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C5',2,'sa','auto','⟨7/9⟩ − ⟨1/6⟩을 분모 18로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M5-1-u5-C5","difficulty":2,"kind":"sa","stem":"⟨7/9⟩ − ⟨1/6⟩을 분모 18로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["분모를 18로 맞추면 ⟨14/18⟩ − ⟨3/18⟩이에요.","분모 18은 그대로 두고 분자끼리 14 − 3 = 11이에요.","그래서 분자는 11이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#15','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C5',3,'mc','auto','⟨3/5⟩ + ⟨3/10⟩ − ⟨1/2⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X13','M5-1-u5-X11']::text[],false,'{"seq":15,"concept":"M5-1-u5-C5","difficulty":3,"kind":"mc","stem":"⟨3/5⟩ + ⟨3/10⟩ − ⟨1/2⟩을 계산하면 얼마인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨1/2⟩","mis":"M5-1-u5-X13"},{"t":"⟨3/10⟩","mis":"M5-1-u5-X13"},{"t":"⟨1 2/5⟩","mis":"M5-1-u5-X11"}],"explanation":["세 분수를 10으로 통분하면 ⟨6/10⟩ + ⟨3/10⟩ − ⟨5/10⟩예요.","앞에서부터 차례로 셈하면 ⟨6/10⟩ + ⟨3/10⟩ − ⟨5/10⟩ = ⟨4/10⟩예요.","그래서 ⟨3/5⟩ + ⟨3/10⟩ − ⟨1/2⟩ = ⟨2/5⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#16','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C6',1,'mc','auto','⟨1 5/6⟩를 가분수로 나타내면 어느 것인가요?',ARRAY['M5-1-u5-X07']::text[],false,'{"seq":16,"concept":"M5-1-u5-C6","difficulty":1,"kind":"mc","stem":"⟨1 5/6⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨11/6⟩","correct":true},{"t":"⟨15/6⟩","mis":"M5-1-u5-X07"},{"t":"⟨6/6⟩","mis":"M5-1-u5-X07"},{"t":"⟨5/6⟩","mis":"M5-1-u5-X07"}],"explanation":["자연수 1은 ⟨6/6⟩이에요 — 1 × 6 = 6.","여기에 ⟨5/6⟩를 더하면 분자는 6 + 5 = 11이에요.","⟨1 5/6⟩ = ⟨11/6⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#17','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C6',2,'mc','auto','⟨6 7/10⟩ − ⟨3 1/2⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X02','M5-1-u5-X08']::text[],false,'{"seq":17,"concept":"M5-1-u5-C6","difficulty":2,"kind":"mc","stem":"⟨6 7/10⟩ − ⟨3 1/2⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3 1/5⟩","correct":true},{"t":"⟨3 3/4⟩","mis":"M5-1-u5-X01"},{"t":"⟨3 3/5⟩","mis":"M5-1-u5-X02"},{"t":"⟨9 1/5⟩","mis":"M5-1-u5-X08"}],"explanation":["분수 부분을 10으로 통분하면 ⟨6 7/10⟩ − ⟨3 5/10⟩예요.","자연수끼리 6 − 3 = 3, 분수끼리 ⟨7/10⟩ − ⟨5/10⟩ = ⟨2/10⟩예요.","그래서 ⟨6 7/10⟩ − ⟨3 1/2⟩ = ⟨3 1/5⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#18','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C6',3,'sa','auto','⟨7 5/6⟩ − ⟨2 1/2⟩ − ⟨3 1/6⟩을 계산한 값을 ⟨2 □/6⟩로 나타낼 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"M5-1-u5-C6","difficulty":3,"kind":"sa","stem":"⟨7 5/6⟩ − ⟨2 1/2⟩ − ⟨3 1/6⟩을 계산한 값을 ⟨2 □/6⟩로 나타낼 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["앞에서부터 셈해요 — ⟨7 5/6⟩ − ⟨2 1/2⟩ = ⟨5 1/3⟩이에요.","⟨5 1/3⟩ − ⟨3 1/6⟩ = ⟨2 1/6⟩이에요.","⟨2 1/6⟩ = ⟨2 1/6⟩ — □는 1이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#19','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C7',3,'sa','auto','⟨5 1/5⟩ − ⟨2 1/2⟩을 가분수로 바꾸어 분모 10으로 계산하면 ⟨□/10⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M5-1-u5-C7","difficulty":3,"kind":"sa","stem":"⟨5 1/5⟩ − ⟨2 1/2⟩을 가분수로 바꾸어 분모 10으로 계산하면 ⟨□/10⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["⟨5 1/5⟩ = ⟨52/10⟩, ⟨2 1/2⟩ = ⟨25/10⟩예요.","분자끼리 52 − 25 = 27이에요.","⟨27/10⟩ = ⟨2 7/10⟩ — □는 27이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#20','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C7',2,'mc','auto','⟨6 1/4⟩ − ⟨3 5/6⟩를 계산하면 얼마인가요?',ARRAY['M5-1-u5-X09','M5-1-u5-X10']::text[],false,'{"seq":20,"concept":"M5-1-u5-C7","difficulty":2,"kind":"mc","stem":"⟨6 1/4⟩ − ⟨3 5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨2 5/12⟩","correct":true},{"t":"⟨3 7/12⟩","mis":"M5-1-u5-X09"},{"t":"⟨3 5/12⟩","mis":"M5-1-u5-X10"},{"t":"⟨2 1/4⟩","mis":"M5-1-u5-X10"}],"explanation":["분수 부분을 12로 통분하면 ⟨6 3/12⟩ − ⟨3 10/12⟩이에요.","분자 3에서 10을 뺄 수 없어 자연수에서 1을 빌리면 ⟨6 3/12⟩ = ⟨5 15/12⟩예요.","⟨5 15/12⟩ − ⟨3 10/12⟩ = ⟨2 5/12⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#21','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C7',2,'mc','auto','6 − ⟨3 4/9⟩를 계산하면 얼마인가요?',ARRAY['M5-1-u5-X10','M5-1-u5-X09']::text[],false,'{"seq":21,"concept":"M5-1-u5-C7","difficulty":2,"kind":"mc","stem":"6 − ⟨3 4/9⟩를 계산하면 얼마인가요?","options":[{"t":"⟨2 5/9⟩","correct":true},{"t":"⟨3 4/9⟩","mis":"M5-1-u5-X10"},{"t":"⟨2 4/9⟩","mis":"M5-1-u5-X09"},{"t":"⟨3 5/9⟩","mis":"M5-1-u5-X10"}],"explanation":["6에서 1을 빌려 6 = ⟨5 9/9⟩로 바꾸어요 — 1은 ⟨9/9⟩예요.","⟨5 9/9⟩ − ⟨3 4/9⟩ = ⟨2 5/9⟩예요.","그래서 6 − ⟨3 4/9⟩ = ⟨2 5/9⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#22','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C7',4,'sa','auto','⟨7 1/6⟩에서 분수 부분이 ⟨2/3⟩인 대분수를 뺐더니 ⟨4 1/2⟩이 되었어요. 뺀 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M5-1-u5-C7","difficulty":4,"kind":"sa","stem":"⟨7 1/6⟩에서 분수 부분이 ⟨2/3⟩인 대분수를 뺐더니 ⟨4 1/2⟩이 되었어요. 뺀 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["뺀 대분수는 ⟨7 1/6⟩ − ⟨4 1/2⟩로 구해요.","⟨7 1/6⟩ − ⟨4 1/2⟩ = ⟨2 2/3⟩예요 — 분수 부분에서 1을 빌려 와요.","⟨2 2/3⟩의 자연수 부분은 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#23','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C8',4,'sa','auto','집과 도서관 사이는 ⟨1 5/6⟩ km예요. 민서는 집에서, 준우는 도서관에서 서로를 향해 각각 ⟨3/4⟩ km, ⟨2/3⟩ km를 걸었어요. 두 사람 사이에 남은 거리는 ⟨□/12⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M5-1-u5-C8","difficulty":4,"kind":"sa","stem":"집과 도서관 사이는 ⟨1 5/6⟩ km예요. 민서는 집에서, 준우는 도서관에서 서로를 향해 각각 ⟨3/4⟩ km, ⟨2/3⟩ km를 걸었어요. 두 사람 사이에 남은 거리는 ⟨□/12⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["두 사람이 걸은 거리는 ⟨3/4⟩ + ⟨2/3⟩ = ⟨1 5/12⟩ km예요.","남은 거리는 ⟨1 5/6⟩ − ⟨1 5/12⟩ = ⟨22/12⟩ − ⟨17/12⟩ = ⟨5/12⟩ km예요.","그래서 □는 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#24','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C8',2,'mc','auto','학교까지 ⟨1 2/5⟩ km인 길로 왕복하면 모두 몇 km를 걷게 되나요?',ARRAY['M5-1-u5-X11','M5-1-u5-X03','M5-1-u5-X13']::text[],false,'{"seq":24,"concept":"M5-1-u5-C8","difficulty":2,"kind":"mc","stem":"학교까지 ⟨1 2/5⟩ km인 길로 왕복하면 모두 몇 km를 걷게 되나요?","options":[{"t":"⟨2 4/5⟩","correct":true},{"t":"⟨1 2/5⟩","mis":"M5-1-u5-X11"},{"t":"⟨2 2/5⟩","mis":"M5-1-u5-X03"},{"t":"3","mis":"M5-1-u5-X13"}],"explanation":["왕복은 갔다가 돌아오는 것 — 같은 길을 두 번 걸어요.","⟨1 2/5⟩ + ⟨1 2/5⟩ = ⟨2 4/5⟩예요.","그래서 모두 ⟨2 4/5⟩ km예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u5_review_d#25','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C8',3,'sa','auto','집에서 학교까지 ⟨1 1/8⟩ km예요. ⟨3/4⟩ km를 걸었다면 남은 거리는 ⟨□/8⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M5-1-u5-C8","difficulty":3,"kind":"sa","stem":"집에서 학교까지 ⟨1 1/8⟩ km예요. ⟨3/4⟩ km를 걸었다면 남은 거리는 ⟨□/8⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["남은 거리 = 전체 거리 − 걸은 거리예요.","⟨1 1/8⟩ − ⟨3/4⟩ = ⟨9/8⟩ − ⟨6/8⟩ = ⟨3/8⟩이에요.","그래서 □는 3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
